const allQuestions: ApMacroQuestion[] = [
  { id: 1, question: 'GDP measures:', options: ['Only government spending', 'The total market value of all final goods and services produced in a country in a year', 'Only exports', 'Stock market value'], correctAnswer: 1, explanation: 'GDP is the total market value of all final goods and services produced domestically in a given year.', difficulty: 'easy', topicSlug: 'macro-gdp-growth' },
  { id: 2, question: 'If nominal GDP rises but real GDP stays the same, this indicates:', options: ['Economic growth', 'Only price increases (inflation)', 'Recession', 'Deflation'], correctAnswer: 1, explanation: 'When nominal GDP increases without real GDP growth, the change is entirely due to rising prices.', difficulty: 'medium', topicSlug: 'macro-gdp-growth' },
  { id: 3, question: 'The GDP deflator measures:', options: ['Only consumer prices', 'The overall price level of all goods/services included in GDP', 'Only import prices', 'Wage levels'], correctAnswer: 1, explanation: 'The GDP deflator covers all domestically produced goods and services, broader than CPI.', difficulty: 'medium', topicSlug: 'macro-gdp-growth' },
  { id: 4, question: 'Transfer payments like Social Security are NOT included in GDP because:', options: ['They are too small', 'They don\'t represent production of goods or services', 'They are illegal', 'They only benefit the rich'], correctAnswer: 1, explanation: 'Transfer payments are redistributions, not payments for current production.', difficulty: 'medium', topicSlug: 'macro-gdp-growth' },
  { id: 5, question: 'The natural rate of unemployment includes:', options: ['Only cyclical unemployment', 'Frictional and structural unemployment', 'Zero unemployment', 'Only seasonal unemployment'], correctAnswer: 1, explanation: 'The natural rate includes frictional (between jobs) and structural (skills mismatch) but not cyclical unemployment.', difficulty: 'medium', topicSlug: 'macro-unemployment-inflation' },
  { id: 6, question: 'Demand-pull inflation is caused by:', options: ['Higher production costs', 'Excessive aggregate demand outpacing supply', 'Government regulation', 'Lower wages'], correctAnswer: 1, explanation: 'Demand-pull inflation occurs when too much money chases too few goods, pulling prices up.', difficulty: 'easy', topicSlug: 'macro-unemployment-inflation' },
  { id: 7, question: 'Cost-push inflation results from:', options: ['Higher consumer demand', 'Rising production costs like wages or raw materials', 'Too much money supply', 'Tax cuts'], correctAnswer: 1, explanation: 'Cost-push inflation occurs when higher input costs push up the prices of final goods and services.', difficulty: 'easy', topicSlug: 'macro-unemployment-inflation' },
  { id: 8, question: 'CPI measures price changes of:', options: ['Only luxury goods', 'A fixed basket of goods and services bought by typical consumers', 'All goods in the economy', 'Only imported goods'], correctAnswer: 1, explanation: 'The Consumer Price Index tracks prices of a representative basket of consumer goods and services.', difficulty: 'easy', topicSlug: 'macro-unemployment-inflation' },
  { id: 9, question: 'In the AD-AS model, a rightward shift of AD indicates:', options: ['Decrease in demand', 'Increase in aggregate demand', 'Supply shock', 'Stagflation'], correctAnswer: 1, explanation: 'A rightward AD shift means more total spending at every price level.', difficulty: 'easy', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 10, question: 'Stagflation is characterized by:', options: ['Low inflation and high growth', 'High inflation combined with high unemployment and stagnant growth', 'Deflation and low unemployment', 'Rapid GDP growth'], correctAnswer: 1, explanation: 'Stagflation occurs when an economy faces both inflation and stagnation simultaneously.', difficulty: 'medium', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 11, question: 'The long-run aggregate supply (LRAS) curve is vertical because:', options: ['Prices don\'t matter', 'Output is determined by resources and technology, not price level', 'Government sets output', 'Supply is infinite'], correctAnswer: 1, explanation: 'In the long run, output depends on available resources and technology, not the price level.', difficulty: 'medium', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 12, question: 'The spending multiplier equals:', options: ['1/MPC', '1/(1-MPC)', 'MPC x MPS', '1/GDP'], correctAnswer: 1, explanation: 'The spending multiplier = 1/(1-MPC) = 1/MPS, showing how initial spending creates larger total GDP changes.', difficulty: 'medium', topicSlug: 'macro-multiplier-effect' },
  { id: 13, question: 'If MPC is 0.8, the spending multiplier is:', options: ['4', '5', '8', '0.8'], correctAnswer: 1, explanation: 'Multiplier = 1/(1-0.8) = 1/0.2 = 5.', difficulty: 'medium', topicSlug: 'macro-multiplier-effect' },
  { id: 14, question: 'The Phillips Curve shows the inverse relationship between:', options: ['GDP and investment', 'Inflation and unemployment', 'Savings and consumption', 'Exports and imports'], correctAnswer: 1, explanation: 'The short-run Phillips Curve shows that lower unemployment tends to correlate with higher inflation.', difficulty: 'medium', topicSlug: 'macro-phillips-curve' },
  { id: 15, question: 'In the long run, the Phillips Curve is:', options: ['Downward sloping', 'Vertical at the natural rate of unemployment', 'Horizontal', 'Upward sloping'], correctAnswer: 1, explanation: 'The long-run Phillips Curve is vertical because there is no permanent tradeoff between inflation and unemployment.', difficulty: 'hard', topicSlug: 'macro-phillips-curve' },
  { id: 16, question: 'Banks create money through:', options: ['Printing currency', 'Fractional reserve lending', 'Selling stock', 'Government orders'], correctAnswer: 1, explanation: 'Banks lend out deposits beyond their required reserves, creating new money through fractional reserve banking.', difficulty: 'medium', topicSlug: 'macro-money-banking' },
  { id: 17, question: 'The money multiplier equals:', options: ['Reserve ratio', '1/reserve ratio', 'Reserve ratio x deposits', '1/interest rate'], correctAnswer: 1, explanation: 'The money multiplier = 1/required reserve ratio, showing total potential deposit creation from new reserves.', difficulty: 'medium', topicSlug: 'macro-money-banking' },
  { id: 18, question: 'If the reserve ratio is 10%, the money multiplier is:', options: ['5', '10', '100', '0.1'], correctAnswer: 1, explanation: 'Money multiplier = 1/0.10 = 10.', difficulty: 'easy', topicSlug: 'macro-money-banking' },
  { id: 19, question: 'Open market operations involve the Fed:', options: ['Changing reserve requirements', 'Buying and selling government bonds', 'Setting tax rates', 'Printing money'], correctAnswer: 1, explanation: 'The Fed buys (expansionary) or sells (contractionary) government securities to influence money supply.', difficulty: 'easy', topicSlug: 'macro-monetary-policy' },
  { id: 20, question: 'When the Fed lowers the federal funds rate:', options: ['Borrowing becomes more expensive', 'Borrowing becomes cheaper, encouraging spending and investment', 'Inflation immediately drops', 'The money supply contracts'], correctAnswer: 1, explanation: 'Lower interest rates make borrowing cheaper, stimulating consumption and investment.', difficulty: 'easy', topicSlug: 'macro-monetary-policy' },
  { id: 21, question: 'The federal funds rate is:', options: ['The rate banks charge consumers', 'The overnight lending rate between banks', 'The rate on Treasury bonds', 'The prime rate'], correctAnswer: 1, explanation: 'The federal funds rate is what banks charge each other for overnight loans of reserves.', difficulty: 'medium', topicSlug: 'macro-monetary-policy' },
  { id: 22, question: 'Expansionary fiscal policy includes:', options: ['Raising taxes and cutting spending', 'Increasing government spending and/or cutting taxes', 'Only monetary changes', 'Deregulation'], correctAnswer: 1, explanation: 'Expansionary fiscal policy uses increased spending or tax cuts to stimulate aggregate demand during recessions.', difficulty: 'easy', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 23, question: 'Contractionary fiscal policy is used to combat:', options: ['Recession', 'Inflation by reducing government spending or increasing taxes', 'Unemployment', 'Deflation'], correctAnswer: 1, explanation: 'Contractionary fiscal policy reduces aggregate demand through spending cuts or tax increases to fight inflation.', difficulty: 'easy', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 24, question: 'Crowding out occurs when:', options: ['Government spending creates jobs', 'Government borrowing raises interest rates, reducing private investment', 'Exports exceed imports', 'Inflation falls'], correctAnswer: 1, explanation: 'Crowding out happens when increased government borrowing drives up interest rates, discouraging private investment.', difficulty: 'medium', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 25, question: 'Automatic stabilizers are:', options: ['Discretionary policies', 'Programs like unemployment insurance that automatically cushion economic downturns', 'Federal Reserve tools', 'International trade agreements'], correctAnswer: 1, explanation: 'Automatic stabilizers (progressive taxes, unemployment benefits) automatically increase spending/reduce taxes during recessions.', difficulty: 'medium', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 26, question: 'A budget deficit occurs when:', options: ['Tax revenue equals spending', 'Government spending exceeds tax revenue', 'Revenue exceeds spending', 'The trade balance is negative'], correctAnswer: 1, explanation: 'A budget deficit means the government spends more than it collects in revenue during a fiscal year.', difficulty: 'easy', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 27, question: 'The loanable funds market determines:', options: ['Exchange rates', 'The real interest rate through supply and demand for savings', 'The money supply', 'The price level'], correctAnswer: 1, explanation: 'The loanable funds market brings together savers (supply) and borrowers (demand) to determine the real interest rate.', difficulty: 'medium', topicSlug: 'macro-money-banking' },
  { id: 28, question: 'Comparative advantage in international trade means:', options: ['Producing more of everything', 'Producing a good at lower opportunity cost than trading partners', 'Having more natural resources', 'Being the largest economy'], correctAnswer: 1, explanation: 'Countries benefit from specializing in goods they can produce at the lowest opportunity cost.', difficulty: 'medium', topicSlug: 'macro-comparative-advantage' },
  { id: 29, question: 'A trade deficit means a country:', options: ['Exports more than it imports', 'Imports more than it exports', 'Has a balanced trade', 'Only trades services'], correctAnswer: 1, explanation: 'A trade deficit occurs when the value of imports exceeds the value of exports.', difficulty: 'easy', topicSlug: 'macro-international-trade-finance' },
  { id: 30, question: 'If the US dollar appreciates against the euro:', options: ['US exports become cheaper abroad', 'US exports become more expensive, imports from Europe become cheaper', 'Nothing changes', 'Both currencies gain value'], correctAnswer: 1, explanation: 'A stronger dollar makes US goods more expensive for foreigners and foreign goods cheaper for Americans.', difficulty: 'medium', topicSlug: 'macro-international-trade-finance' },
  { id: 31, question: 'The quantity theory of money states:', options: ['Money doesn\'t affect prices', 'MV = PQ, linking money supply to price levels', 'Only velocity matters', 'Banks set prices'], correctAnswer: 1, explanation: 'The equation of exchange (MV=PQ) connects money supply and velocity to price level and real output.', difficulty: 'medium', topicSlug: 'macro-monetary-policy' },
  { id: 32, question: 'Frictional unemployment is caused by:', options: ['Economic downturns', 'Workers transitioning between jobs', 'Technological changes', 'Minimum wage laws'], correctAnswer: 1, explanation: 'Frictional unemployment is temporary unemployment while people search for new jobs or enter the workforce.', difficulty: 'easy', topicSlug: 'macro-unemployment-inflation' },
  { id: 33, question: 'Structural unemployment results from:', options: ['Normal job searching', 'Mismatch between workers\' skills and available jobs', 'Seasonal layoffs', 'Economic recession'], correctAnswer: 1, explanation: 'Structural unemployment occurs when workers\' skills don\'t match job requirements, often due to technological change.', difficulty: 'medium', topicSlug: 'macro-unemployment-inflation' },
  { id: 34, question: 'The velocity of money measures:', options: ['How fast the Fed prints money', 'How many times a dollar changes hands in a year', 'The speed of online transactions', 'How fast prices rise'], correctAnswer: 1, explanation: 'Velocity measures the average number of times a dollar is spent purchasing final goods and services per year.', difficulty: 'medium', topicSlug: 'macro-monetary-policy' },
  { id: 35, question: 'A recessionary gap exists when:', options: ['Real GDP exceeds potential GDP', 'Real GDP is below potential GDP', 'The economy is at full employment', 'Inflation is too high'], correctAnswer: 1, explanation: 'A recessionary gap means the economy is producing below its potential, with higher-than-natural unemployment.', difficulty: 'medium', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 36, question: 'Supply-side economics emphasizes:', options: ['Demand management through government spending', 'Tax cuts and deregulation to increase production', 'Higher government spending', 'Price controls'], correctAnswer: 1, explanation: 'Supply-side economics focuses on boosting aggregate supply through lower taxes and less regulation.', difficulty: 'medium', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 37, question: 'The discount rate is:', options: ['The rate consumers pay', 'The interest rate the Fed charges banks for borrowing reserves', 'The prime lending rate', 'The inflation rate'], correctAnswer: 1, explanation: 'The discount rate is the interest rate charged by the Fed when banks borrow directly from the discount window.', difficulty: 'medium', topicSlug: 'macro-monetary-policy' },
  { id: 38, question: 'Net exports equal:', options: ['Imports minus exports', 'Exports minus imports', 'Total trade volume', 'GDP minus consumption'], correctAnswer: 1, explanation: 'Net exports (NX) = Exports - Imports. A positive NX means trade surplus; negative means deficit.', difficulty: 'easy', topicSlug: 'macro-international-trade-finance' },
  { id: 39, question: 'The GDP equation is:', options: ['GDP = C + I + G + NX', 'GDP = C × I × G × NX', 'GDP = C + I - G', 'GDP = only consumption'], correctAnswer: 0, explanation: 'GDP = Consumption + Investment + Government Spending + Net Exports.', difficulty: 'easy', topicSlug: 'macro-gdp-growth' },
  { id: 40, question: 'Okun\'s Law describes the relationship between:', options: ['Inflation and unemployment', 'Unemployment and GDP (each 1% above natural rate = ~2% GDP loss)', 'Interest rates and investment', 'Money supply and prices'], correctAnswer: 1, explanation: 'Okun\'s Law estimates that each percentage point of unemployment above natural rate costs ~2% of real GDP.', difficulty: 'hard', topicSlug: 'macro-unemployment-inflation' },

  // ============ TOP-UP: bring under-10 sub-topics to >=10 questions ============
  // ad-as (8 → 10)
  { id: 41, question: 'A leftward shift of aggregate demand causes:', options: ['Lower output and lower price level (recession)', 'Higher output and higher prices', 'Stagflation', 'No effect'], correctAnswer: 0, explanation: 'Demand-side recession in AD-AS model.', difficulty: 'medium', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 42, question: 'A negative supply shock (e.g., oil price spike) causes:', options: ['Higher prices and lower output (stagflation)', 'Lower prices and higher output', 'No change', 'Falling unemployment only'], correctAnswer: 0, explanation: 'SRAS shifts left.', difficulty: 'medium', topicSlug: 'macro-aggregate-demand-supply' },

  // ============ NEW competitive AP-style (stimulus/application) items, ids 43+ ============
  { id: 43, question: 'A nation can produce, with one day of labor, either 40 bushels of wheat or 10 barrels of oil. A neighboring nation can produce either 30 bushels of wheat or 30 barrels of oil. Based on opportunity cost, which pattern of specialization makes both nations better off through trade?', options: ['The first nation specializes in oil; the second in wheat', 'The first nation specializes in wheat; the second in oil', 'Both nations should produce only wheat', 'Neither nation gains because the first is more productive at wheat'], correctAnswer: 1, explanation: 'For the first nation, 1 oil costs 4 wheat; for the second, 1 oil costs only 1 wheat. The second has the lower opportunity cost in oil and should specialize there, while the first (1 wheat costs only 0.25 oil vs the second\'s 1 oil) specializes in wheat.', difficulty: 'hard', topicSlug: 'macro-comparative-advantage' },
  { id: 44, question: 'A student says, "Because I chose to attend a concert tonight, I gave up the chance to earn $60 at my part-time job and the enjoyment I would have gotten from studying." Which concept does this statement best illustrate?', options: ['Opportunity cost as the value of the next-best forgone alternative', 'Diminishing marginal utility', 'Sunk cost', 'Absolute advantage'], correctAnswer: 0, explanation: 'Opportunity cost is the value of the most highly valued alternative given up when a choice is made; the forgone wages and study benefit represent that cost.', difficulty: 'easy', topicSlug: 'macro-scarcity-opportunity-cost' },
  { id: 45, question: 'An economy produces only two goods, capital goods and consumer goods, and is currently operating at a point inside its production possibilities curve. Which of the following best explains this situation?', options: ['The economy is using all resources efficiently', 'The economy has experienced long-run economic growth', 'The point is currently unattainable for the economy', 'Some resources are unemployed or underutilized'], correctAnswer: 3, explanation: 'A point inside the PPC indicates productive inefficiency caused by unemployed or underused resources; the economy could produce more of both goods.', difficulty: 'easy', topicSlug: 'macro-scarcity-opportunity-cost' },
  { id: 46, question: 'In Country X, nominal GDP rose from $500 billion to $560 billion while the GDP deflator rose from 100 to 112 over the same year. Which conclusion is best supported?', options: ['Real GDP rose by 12%', 'Real GDP was unchanged', 'Real GDP fell relative to the base year', 'Real GDP and nominal GDP both rose by the same amount'], correctAnswer: 1, explanation: 'Real GDP = nominal GDP / (deflator/100) = 560 / 1.12 = $500 billion, equal to the prior year. All of the 12% nominal increase was due to higher prices.', difficulty: 'medium', topicSlug: 'macro-gdp-growth' },
  { id: 47, question: 'A news report states: "Last year, factories produced 2,000 cars; this year they produced the same 2,000 cars, but 300 of them sat unsold in dealer inventories at year-end." How are the 300 unsold cars treated in this year\'s GDP?', options: ['They are excluded because they were not sold to consumers', 'They are subtracted as a transfer payment', 'They are counted this year as inventory investment', 'They are counted only when sold next year'], correctAnswer: 2, explanation: 'Unsold output produced during the year is counted in GDP as inventory investment (part of gross private domestic investment) in the year it is produced, regardless of when it sells.', difficulty: 'medium', topicSlug: 'macro-gdp-growth' },
  { id: 48, question: 'A survey of an economy of 200,000 people finds: 120,000 employed, 8,000 unemployed and actively seeking work, 50,000 retirees and full-time students not seeking work, and 22,000 children under 16. What is the unemployment rate?', options: ['4.0%', '6.25%', '6.7%', '8.0%'], correctAnswer: 1, explanation: 'Labor force = employed + unemployed = 120,000 + 8,000 = 128,000. Unemployment rate = 8,000 / 128,000 = 6.25%. Retirees, students, and children are not in the labor force.', difficulty: 'hard', topicSlug: 'macro-unemployment-inflation' },
  { id: 49, question: 'A factory automates its assembly line, permanently laying off workers whose manual skills are no longer demanded. Months later these workers remain jobless because they lack the technical skills employers now require. This is an example of:', options: ['Cyclical unemployment', 'Frictional unemployment', 'Structural unemployment', 'Seasonal unemployment'], correctAnswer: 2, explanation: 'A persistent mismatch between workers\' skills and the skills employers demand, here caused by technological change, defines structural unemployment.', difficulty: 'easy', topicSlug: 'macro-unemployment-inflation' },
  { id: 50, question: 'A worker signed a contract a year ago for a fixed $50,000 salary, expecting 2% inflation. Actual inflation turned out to be 6%. Which statement best describes the effect of this unexpected inflation?', options: ['The worker gained purchasing power at the employer\'s expense', 'Both the worker and employer were unaffected in real terms', 'The worker\'s real wage fell, benefiting the employer', 'Lenders to the worker gained relative to expectations'], correctAnswer: 2, explanation: 'When inflation exceeds expectations, the fixed nominal wage buys less, so the worker\'s real wage falls and the employer benefits. Unanticipated inflation also tends to help borrowers over lenders.', difficulty: 'medium', topicSlug: 'macro-unemployment-inflation' },
  { id: 51, question: 'During a recession, a large oil-exporting region experiences a sudden, sustained increase in global oil prices that raises production costs across the economy. In the short-run AD-AS model, what is the most likely combined effect?', options: ['Output rises and the price level falls', 'Output falls and the price level rises (stagflation)', 'Output rises and the price level rises', 'Output and the price level both fall'], correctAnswer: 1, explanation: 'A negative supply shock shifts SRAS leftward, simultaneously raising the price level and reducing real output, the defining condition of stagflation.', difficulty: 'medium', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 52, question: 'A central bank unexpectedly raises interest rates, and at the same time consumer confidence collapses, sharply reducing planned spending. Holding short-run aggregate supply fixed, which outcome does the AD-AS model predict?', options: ['A rightward shift of AD, raising output and prices', 'A leftward shift of AD, lowering output and the price level', 'A leftward shift of SRAS, causing stagflation', 'No change because the two effects offset'], correctAnswer: 1, explanation: 'Both higher interest rates (less investment) and lower consumer confidence (less consumption) reduce aggregate demand, shifting AD left and lowering both real output and the price level.', difficulty: 'medium', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 53, question: 'An economy is in long-run equilibrium when a wave of optimism causes a surge in investment spending. According to the AD-AS model, what happens in the short run versus the long run?', options: ['Short run: output above potential and rising prices; long run: SRAS shifts left, returning output to potential at a higher price level', 'Short run: output below potential; long run: prices fall back to the original level', 'Output stays at potential in both the short and long run', 'Long run: LRAS shifts right, permanently raising output above the original potential'], correctAnswer: 0, explanation: 'The AD increase first pushes real output above potential (an inflationary gap) and raises prices. Over time rising input costs shift SRAS left, returning output to potential GDP but at a higher price level.', difficulty: 'hard', topicSlug: 'macro-aggregate-demand-supply' },
  { id: 54, question: 'A government increases its purchases by $40 billion in an economy where the marginal propensity to consume is 0.75. Ignoring crowding out and price changes, by how much could real GDP ultimately change?', options: ['$30 billion', '$53 billion', '$160 billion', '$200 billion'], correctAnswer: 2, explanation: 'The spending multiplier = 1/(1 - MPC) = 1/(1 - 0.75) = 4. Change in real GDP = 4 × $40 billion = $160 billion.', difficulty: 'medium', topicSlug: 'macro-multiplier-effect' },
  { id: 55, question: 'Two economies receive an identical $50 billion increase in autonomous spending. Economy A has an MPC of 0.6; Economy B has an MPC of 0.9. Which statement is best supported?', options: ['Economy A experiences a larger total change in GDP because it saves more', 'Both economies experience identical total changes in GDP', 'Economy B experiences a larger total change in GDP because more income is re-spent each round', 'Neither economy\'s GDP changes because saving cancels the spending'], correctAnswer: 2, explanation: 'A higher MPC means a larger multiplier (1/(1-MPC)). Economy B\'s multiplier is 10 versus Economy A\'s 2.5, so B sees a larger total GDP change as each round\'s spending feeds further rounds.', difficulty: 'medium', topicSlug: 'macro-multiplier-effect' },
  { id: 56, question: 'A government wants to close a recessionary gap of $120 billion using a tax cut. If the MPC is 0.8, what initial tax cut is required (tax multiplier = -MPC/(1-MPC))?', options: ['$24 billion', '$30 billion', '$120 billion', '$150 billion'], correctAnswer: 1, explanation: 'Tax multiplier = -MPC/(1-MPC) = -0.8/0.2 = -4 (magnitude 4). To raise GDP by $120 billion, a tax cut of $120/4 = $30 billion is needed.', difficulty: 'hard', topicSlug: 'macro-multiplier-effect' },
  { id: 57, question: 'A bank receives a new $1,000 cash deposit. The required reserve ratio is 20%, and banks lend out all excess reserves while the public holds no additional cash. What is the maximum increase in the total money supply the banking system can generate?', options: ['$1,000', '$4,000', '$5,000', '$20,000'], correctAnswer: 2, explanation: 'The money multiplier = 1/0.20 = 5. The maximum increase in the money supply = $1,000 × 5 = $5,000 (which includes the original $1,000 deposit).', difficulty: 'medium', topicSlug: 'macro-money-banking' },
  { id: 58, question: 'A bank\'s simplified balance sheet shows $10,000 in demand deposits and $3,000 in total reserves. If the required reserve ratio is 10%, how much can this single bank lend out right now?', options: ['$1,000', '$2,000', '$3,000', '$7,000'], correctAnswer: 1, explanation: 'Required reserves = 10% × $10,000 = $1,000. Excess reserves = $3,000 - $1,000 = $2,000, which is the maximum the individual bank can lend immediately.', difficulty: 'medium', topicSlug: 'macro-money-banking' },
  { id: 59, question: 'A saver moves $5,000 from a checking account (M1) into a newly purchased corporate stock. Holding everything else constant, what is the immediate effect on the M1 money supply?', options: ['M1 rises by $5,000', 'M1 falls by $5,000', 'M1 is unchanged because the funds still exist somewhere', 'M1 is unchanged because the seller of the stock receives the $5,000 in their checking account'], correctAnswer: 3, explanation: 'When the buyer pays for the stock, the $5,000 moves from the buyer\'s checking account to the seller\'s checking account. The funds remain demand deposits, so total M1 is unchanged.', difficulty: 'hard', topicSlug: 'macro-money-banking' },
  { id: 60, question: 'Facing rising inflation, a central bank wants to reduce the money supply using open market operations. Which action is consistent with this goal, and what is the expected effect on the nominal interest rate?', options: ['Buy government bonds; interest rates fall', 'Buy government bonds; interest rates rise', 'Sell government bonds; interest rates rise', 'Sell government bonds; interest rates fall'], correctAnswer: 2, explanation: 'Selling government bonds drains reserves and reduces the money supply (contractionary). A smaller money supply raises the nominal interest rate, discouraging borrowing and spending to fight inflation.', difficulty: 'medium', topicSlug: 'macro-monetary-policy' },
  { id: 61, question: 'A central bank announces it will lower the policy interest rate. Trace the most likely short-run channel to real GDP.', options: ['Lower rates → more investment and consumption → AD shifts right → higher GDP', 'Lower rates → less investment and consumption → AD shifts left → lower GDP', 'Lower rates → SRAS shifts left → stagflation', 'Lower rates → currency appreciates → exports rise → higher GDP'], correctAnswer: 0, explanation: 'Lower interest rates reduce the cost of borrowing, increasing interest-sensitive investment and consumption. This raises aggregate demand, shifting AD right and increasing real GDP in the short run.', difficulty: 'easy', topicSlug: 'macro-monetary-policy' },
  { id: 62, question: 'An economy faces a severe recession. A central banker argues, "Cutting our policy rate further will not stimulate borrowing because rates are already near zero and banks are simply holding excess reserves." This concern is most consistent with:', options: ['Crowding out of private investment', 'A liquidity trap limiting conventional monetary policy', 'Cost-push inflation', 'An appreciating exchange rate'], correctAnswer: 1, explanation: 'When interest rates are near zero and additional reserves fail to spur lending or spending, expansionary monetary policy loses traction, a situation known as a liquidity trap.', difficulty: 'hard', topicSlug: 'macro-monetary-policy' },
  { id: 63, question: 'A legislature passes a large increase in government spending financed by borrowing while the economy is already near full employment. Critics warn the policy will "raise interest rates and reduce private investment." This concern describes:', options: ['The multiplier effect', 'Automatic stabilization', 'Comparative advantage', 'Crowding out'], correctAnswer: 3, explanation: 'Deficit-financed government spending increases demand for loanable funds, raising the real interest rate and discouraging private investment, the crowding-out effect.', difficulty: 'medium', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 64, question: 'During a sharp recession, total tax revenues automatically fall while spending on unemployment benefits automatically rises, even though Congress passed no new laws. This behavior best illustrates:', options: ['Discretionary fiscal policy', 'Contractionary monetary policy', 'Supply-side tax reform', 'Automatic stabilizers cushioning the downturn'], correctAnswer: 3, explanation: 'Progressive taxes and transfer programs like unemployment insurance respond automatically to the business cycle, increasing the deficit and supporting demand during recessions without new legislation.', difficulty: 'easy', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 65, question: 'An economy has an inflationary gap. A policymaker proposes a fiscal response. Which combination is appropriate, and what is its goal?', options: ['Increase spending and cut taxes to shift AD right and raise output', 'Cut spending and raise taxes to shift AD left and reduce the price level', 'Cut spending and raise taxes to shift SRAS left', 'Increase spending and raise taxes simultaneously to leave AD unchanged'], correctAnswer: 1, explanation: 'An inflationary gap calls for contractionary fiscal policy: reducing government spending and/or raising taxes shifts AD leftward, easing upward pressure on the price level and returning output toward potential.', difficulty: 'medium', topicSlug: 'macro-fiscal-policy-tools' },
  { id: 66, question: 'After an unexpected increase in aggregate demand, an economy moves up its short-run Phillips curve. According to the long-run adjustment process, what happens once workers and firms fully revise their inflation expectations?', options: ['Unemployment remains permanently below the natural rate', 'The short-run Phillips curve shifts up, returning unemployment to the natural rate at a higher inflation rate', 'The long-run Phillips curve becomes downward sloping', 'Inflation falls back to its original level with no lasting effect'], correctAnswer: 1, explanation: 'Lower unemployment from unexpected inflation is temporary. As expectations adjust upward, the short-run Phillips curve shifts up and unemployment returns to its natural rate, leaving only higher inflation, consistent with the vertical long-run Phillips curve.', difficulty: 'hard', topicSlug: 'macro-phillips-curve' },
  { id: 67, question: 'A US firm imports machinery from Germany. Over the next month the US dollar appreciates substantially against the euro. Holding other factors constant, how does this affect the firm and US net exports?', options: ['Imported machinery becomes more expensive; net exports rise', 'Imported machinery becomes cheaper; net exports rise', 'Imported machinery becomes cheaper; net exports tend to fall', 'There is no effect on import prices or net exports'], correctAnswer: 2, explanation: 'A stronger dollar buys more euros, making euro-priced imports cheaper for the US firm. At the same time US exports become more expensive abroad, so imports rise and exports fall, reducing net exports.', difficulty: 'medium', topicSlug: 'macro-international-trade-finance' },
  { id: 68, question: "Two countries each use all their resources to produce wheat or cloth. In one day of full production, Country A can make 60 bushels of wheat OR 30 yards of cloth, while Country B can make 40 bushels of wheat OR 40 yards of cloth. What is Country A's opportunity cost of producing 1 bushel of wheat?", options: ["0.5 yards of cloth","2 yards of cloth","1 yard of cloth","0.67 yards of cloth"], correctAnswer: 0, explanation: "Country A gives up 30 yards of cloth to gain 60 bushels of wheat, so the opportunity cost of 1 bushel is 30/60 = 0.5 yards of cloth. The value 2 yards inverts the ratio (the cost of cloth in terms of wheat), 1 yard treats the trade-off as one-for-one, and 0.67 yards comes from using Country B's numbers (40/60).", difficulty: "easy", topicSlug: "macro-comparative-advantage" },
  { id: 69, question: "Using the same data (Country A: 60 wheat OR 30 cloth; Country B: 40 wheat OR 40 cloth), which country has the comparative advantage in cloth?", options: ["Country A, because it has the absolute advantage in wheat","Country B, because its opportunity cost of cloth (1 wheat) is lower than A's (2 wheat)","Country B, because it can produce more cloth in absolute terms","Neither, because the opportunity costs are equal"], correctAnswer: 1, explanation: "Country A's opportunity cost of 1 yard of cloth is 60/30 = 2 bushels of wheat; Country B's is 40/40 = 1 bushel of wheat. Because B sacrifices less wheat per yard of cloth, B has the comparative advantage in cloth. Absolute advantage in wheat or the larger absolute cloth output is irrelevant to comparative advantage, and the opportunity costs are not equal.", difficulty: "easy", topicSlug: "macro-comparative-advantage" },
  { id: 70, question: "A worker in Nation X can produce either 8 shirts or 4 phones per hour. A worker in Nation Y can produce either 6 shirts or 6 phones per hour. Which nation should specialize in phones according to comparative advantage?", options: ["Nation X, because it has the absolute advantage in shirts","Nation Y, because it produces more total output","Nation Y, because its opportunity cost of a phone is 1 shirt versus 2 shirts in X","Nation X, because its phone output is higher per worker"], correctAnswer: 2, explanation: "In Nation X, producing 1 phone costs 8/4 = 2 shirts. In Nation Y, producing 1 phone costs 6/6 = 1 shirt. Y sacrifices fewer shirts per phone, so Y has the comparative advantage in phones and should specialize there. Absolute advantage in shirts, total output, or raw phone counts do not determine comparative advantage.", difficulty: "easy", topicSlug: "macro-comparative-advantage" },
  { id: 71, question: "Country M can produce 100 units of food or 50 units of machines with its resources; Country N can produce 80 units of food or 80 units of machines. After both specialize according to comparative advantage and trade, which terms of trade would benefit BOTH countries for machines?", options: ["1 machine for 0.5 units of food","1 machine for 1 unit of food","1 machine for 3 units of food","1 machine for 1.5 units of food"], correctAnswer: 3, explanation: "Country M's opportunity cost of a machine is 100/50 = 2 food; Country N's is 80/80 = 1 food. M specializes in food, N in machines. Mutually beneficial terms for machines must fall strictly between N's cost (1 food) and M's cost (2 food). Only 1.5 food per machine lies in that range. 0.5 and 1 are at or below N's cost (no gain for N), and 3 exceeds M's cost (M would rather make its own).", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 72, question: "The table shows daily output per worker. Brazil: 12 coffee OR 6 textiles. Vietnam: 4 coffee OR 4 textiles. If the two countries trade 1 textile for 1.5 coffee, what is the gain to Vietnam per textile it exports compared with making coffee itself?", options: ["0.5 extra coffee per textile","1.5 extra coffee per textile","1 extra coffee per textile","There is no gain for Vietnam"], correctAnswer: 0, explanation: "Vietnam's opportunity cost of a textile is 4/4 = 1 coffee (by making textiles it forgoes 1 coffee). By exporting a textile it instead receives 1.5 coffee, a gain of 1.5 - 1 = 0.5 coffee per textile. The 1.5 figure is the total received, not the net gain; 1 is the autarky cost; and a 'no gain' answer ignores that 1.5 exceeds Vietnam's cost of 1.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 73, question: "Two firms can each make widgets or gadgets. Firm 1's PPC has a constant slope of -3 (gadgets on the vertical axis, widgets on the horizontal). Firm 2's PPC has a constant slope of -0.5. Which firm has the comparative advantage in widgets?", options: ["Firm 1, because its widget cost of 3 gadgets is higher and a higher cost signals an advantage","Firm 2, because its opportunity cost of a widget is 0.5 gadgets versus 3 for Firm 1","Firm 1, because a steeper PPC means lower cost","Both firms have equal comparative advantage in widgets"], correctAnswer: 1, explanation: "With gadgets on the vertical axis, the slope magnitude equals the opportunity cost of one widget in gadgets. Firm 1 sacrifices 3 gadgets per widget; Firm 2 sacrifices only 0.5 gadgets per widget. Firm 2's lower opportunity cost gives it the comparative advantage in widgets. A steeper PPC means higher (not lower) widget cost, and the costs are not equal.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 74, question: "A country can produce 20 tons of steel or 10 tractors using all resources. Currently it makes both itself. A trading partner offers steel at a price of 1 tractor per 3 tons of steel. Should this country import steel?", options: ["No, because it can produce steel domestically","Yes, because importing always raises output","Yes, because its own cost of steel (0.5 tractor per ton) exceeds the import price implied (0.33 tractor per ton)","No, because the partner's price for steel is too high"], correctAnswer: 2, explanation: "Domestically, 20 steel costs 10 tractors, so 1 ton of steel costs 10/20 = 0.5 tractor. The import deal is 3 tons per tractor, i.e., 1/3 = 0.33 tractor per ton, which is cheaper. Because steel is cheaper abroad than at home, the country should import steel (and specialize in tractors). 'No, because it can produce it' ignores cost comparison; importing does not always raise output unless prices are favorable; and the partner's price is actually lower, not higher.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 75, question: "Output table (per day): Country G makes 30 cars OR 90 computers. Country H makes 20 cars OR 40 computers. After full specialization by comparative advantage, what is the combined maximum output of the good in which Country G specializes?", options: ["130 computers","30 cars","50 cars","90 computers"], correctAnswer: 3, explanation: "G's cost of a computer is 30/90 = 0.33 car; H's is 20/40 = 0.5 car. G has the lower cost in computers, so G specializes in computers, producing 90. H specializes in cars (its comparative advantage), so G alone contributes 90 computers. The 130 figure wrongly adds H's computers, while the car figures describe H's specialization, not G's.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 76, question: "Suppose Country P can produce 50 wheat or 25 oil, and Country Q can produce 30 wheat or 30 oil. The countries agree to trade at 1 oil for 1.2 wheat. Which statement correctly identifies who exports oil and why?", options: ["Country Q exports oil because its opportunity cost of oil (1 wheat) is below P's (2 wheat)","Country P exports oil because it has more wheat capacity","Country Q exports oil because it produces more oil in absolute terms","Country P exports oil because oil is scarce there"], correctAnswer: 0, explanation: "P's opportunity cost of 1 oil is 50/25 = 2 wheat; Q's is 30/30 = 1 wheat. Q gives up less wheat per oil, so Q has the comparative advantage in oil and should export it. P specializes in and exports wheat. Wheat capacity, raw oil counts, and scarcity claims do not determine the direction of trade.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 77, question: "In a two-good, two-country model, Country A has the absolute advantage in BOTH goods. Which of the following must be true?", options: ["No trade can benefit both countries because A is more productive in everything","Mutually beneficial trade is still possible if the countries' opportunity costs differ","Country B must specialize in the good A is best at","Country A gains from trade only if it also imports the good it is worst at"], correctAnswer: 1, explanation: "Absolute advantage in both goods does not eliminate gains from trade. As long as the two countries have different opportunity-cost ratios, each has a comparative advantage in one good, and specialization plus trade can make both better off. Mutual gains do not require A to be less productive; B specializes where its opportunity cost is lowest (not where A excels); and gains follow from comparative, not absolute, advantage.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 78, question: "Country R: 40 fish OR 80 bananas per day. Country S: 30 fish OR 30 bananas per day. The autarky (no-trade) price of 1 fish in Country R is how many bananas?", options: ["0.5 bananas","1 banana","2 bananas","1.33 bananas"], correctAnswer: 2, explanation: "In Country R, giving up production of fish frees resources for bananas at a rate of 80 bananas per 40 fish = 2 bananas per fish. So 1 fish costs 2 bananas in autarky. The 0.5 figure inverts the ratio (banana cost in fish), 1 treats the trade-off as one-for-one, and 1.33 comes from misusing Country S data or arithmetic error.", difficulty: "easy", topicSlug: "macro-comparative-advantage" },
  { id: 79, question: "Using R (40 fish OR 80 bananas) and S (30 fish OR 30 bananas): which country exports bananas and which exports fish under comparative advantage?", options: ["R exports fish and S exports bananas","R exports both because it has higher banana output","S exports both because its costs are balanced","R exports bananas (cost 0.5 fish/banana) and S exports fish (cost 1 banana/fish)"], correctAnswer: 3, explanation: "R's cost of a banana is 40/80 = 0.5 fish; S's is 30/30 = 1 fish, so R has the comparative advantage in bananas. For fish, R's cost is 2 bananas and S's is 1 banana, so S has the comparative advantage in fish. Therefore R exports bananas and S exports fish. A country cannot have a comparative advantage in both goods, ruling out the other options.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 80, question: "A linear PPC for an economy passes through (0 capital goods, 200 consumer goods) and (100 capital goods, 0 consumer goods). What is the opportunity cost of producing one additional capital good?", options: ["2 consumer goods","0.5 consumer goods","1 consumer good","100 consumer goods"], correctAnswer: 0, explanation: "Moving from 0 to 100 capital goods sacrifices 200 consumer goods, so each capital good costs 200/100 = 2 consumer goods. The 0.5 figure inverts the ratio (cost of a consumer good in capital goods), 1 assumes a one-for-one trade-off, and 100 is the maximum capital output, not the per-unit cost.", difficulty: "easy", topicSlug: "macro-comparative-advantage" },
  { id: 81, question: "Two students do a group project. Ana can write 6 pages OR make 12 slides per hour. Ben can write 2 pages OR make 8 slides per hour. To finish fastest, who should focus on slides?", options: ["Ana, because she makes more slides per hour","Ben, because his opportunity cost of a slide is 0.25 pages versus 0.5 pages for Ana","Ben, because he is slower at writing","Ana, because she has the absolute advantage in both tasks"], correctAnswer: 1, explanation: "Ana's cost of 1 slide is 6/12 = 0.5 pages; Ben's is 2/8 = 0.25 pages. Ben sacrifices fewer pages per slide, so he has the comparative advantage in slides and should make them while Ana writes. Ana's higher slide count is absolute advantage, which does not govern specialization; being slow at writing alone is not the criterion; and absolute advantage in both does not assign Ana to slides.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 82, question: "Country J's PPC (constant slope): it can make 600 tons of rice or 200 tons of sugar. Country K can make 300 tons of rice or 300 tons of sugar. What is the lowest amount of rice (per ton of sugar) that Country J would accept to export sugar to K?", options: ["More than 3 tons of rice per ton of sugar","Exactly 1 ton of rice per ton of sugar","Country J would never export sugar","Less than 1 ton of rice per ton of sugar"], correctAnswer: 2, explanation: "J's opportunity cost of sugar is 600/200 = 3 rice; K's is 300/300 = 1 rice. Because K can make sugar more cheaply (1 rice) than J (3 rice), K — not J — has the comparative advantage in sugar. J specializes in rice (cost 1/3 sugar vs K's 1 sugar). So J would export rice, not sugar. Hence J would never export sugar under comparative advantage.", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 83, question: "A country produces only laptops and tablets along a straight-line PPC. It currently produces 40 laptops and 30 tablets, a point that lies INSIDE the PPC. What does this most likely indicate about comparative advantage and trade?", options: ["The country has no comparative advantage in either good","The point inside the PPC proves the country is specializing correctly","Trade is impossible until the country reaches a point beyond the PPC alone","The economy is using resources inefficiently; comparative advantage gains require operating on, not inside, the PPC"], correctAnswer: 3, explanation: "A point inside the PPC signals unemployed or inefficiently used resources. To realize comparative-advantage gains, a country should first operate efficiently (on its PPC) and then specialize and trade. Operating inside does not prove specialization, says nothing about whether a comparative advantage exists (it always does if costs differ), and a single country cannot reach a point beyond its own PPC without trade.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 84, question: "Per-worker daily output. Country T: 10 trucks OR 50 toys. Country U: 4 trucks OR 8 toys. Which good should Country U export, and what is U's opportunity cost of that good?", options: ["Trucks; opportunity cost 2 toys per truck","Toys; opportunity cost 0.5 trucks per toy","Trucks; opportunity cost 0.5 toys per truck","Toys; opportunity cost 2 toys per truck"], correctAnswer: 0, explanation: "U's cost of a truck is 8/4 = 2 toys; T's cost of a truck is 50/10 = 5 toys. U sacrifices fewer toys per truck, so U has the comparative advantage in trucks and should export trucks at a cost of 2 toys each. T exports toys (cost 0.2 trucks vs U's 0.5 trucks). The other options mislabel the export good or miscompute the cost.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 85, question: "Country D and Country E each produce corn and electronics. Their opportunity costs of 1 unit of electronics are: D = 4 corn, E = 4 corn. What can we conclude about trade between them?", options: ["D should export electronics because it listed first","There is no comparative advantage difference, so specialization yields no mutual gains from trade","E should export corn because corn is cheaper there","Both can gain by each specializing in electronics"], correctAnswer: 1, explanation: "When opportunity costs are identical (both 4 corn per electronics, hence both 0.25 electronics per corn), neither country has a comparative advantage. With equal cost ratios the PPCs have the same slope, and specialization plus trade cannot make both better off. Listing order is irrelevant, corn costs are equal (not cheaper in E), and both countries cannot specialize in the same good and trade with each other.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 86, question: "An economy can produce 90 units of Good X or 45 units of Good Y. It signs a trade agreement allowing it to exchange Good X for Good Y at a rate of 1 Y for 1.5 X. By specializing in X and trading, how many units of Y can it ultimately obtain if it devotes all resources to X?", options: ["45 units of Y","90 units of Y","60 units of Y","30 units of Y"], correctAnswer: 2, explanation: "All resources in X yield 90 units of X. Trading at 1 Y per 1.5 X means 90 X / 1.5 = 60 units of Y. This exceeds the 45 units of Y it could make alone, showing the gain from trade. 45 is the autarky maximum, 90 confuses X output with Y, and 30 misapplies the exchange rate.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 87, question: "Country A: 80 wine OR 40 cheese. Country B: 60 wine OR 60 cheese. They negotiate terms of trade for cheese. Which proposed rate would be rejected by Country B because it offers B no gain?", options: ["1 cheese for 1.5 wine","1 cheese for 1.2 wine","1 cheese for 1.9 wine","1 cheese for 0.8 wine"], correctAnswer: 3, explanation: "B's opportunity cost of cheese is 60/60 = 1 wine, and A's is 80/40 = 2 wine. B specializes in cheese and will only export it for MORE than 1 wine. A rate of 0.8 wine per cheese is below B's cost, so B gains nothing and rejects it. Rates of 1.5, 1.2, and 1.9 wine all exceed 1 and are below A's cost of 2, so they benefit both.", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 88, question: "A small economy faces a straight-line PPC: 1,000 bushels of grain or 250 barrels of oil. World markets let it trade grain for oil at 3 bushels per barrel. Compared with autarky, what is the best description of its consumption possibilities?", options: ["It can consume beyond its PPC by specializing in grain and trading for oil, since the world price (3 grain/oil) is below its domestic cost (4 grain/oil)","It cannot exceed its PPC because trade only redistributes existing output","It should specialize in oil because oil is more valuable","Trade leaves its consumption possibilities unchanged"], correctAnswer: 0, explanation: "Domestically, 1 barrel of oil costs 1000/250 = 4 bushels. The world lets it get oil for only 3 bushels, so it should specialize in grain and import oil, reaching consumption points beyond its own PPC. Trade expands consumption possibilities (it does not merely redistribute), the country should specialize where its cost is lower (grain), and consumption possibilities do change.", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 89, question: "Two regions produce books and pencils. Region 1: opportunity cost of 1 book = 5 pencils. Region 2: opportunity cost of 1 book = 2 pencils. At which terms of trade for books would BOTH regions gain?", options: ["1 book for 1 pencil","1 book for 3 pencils","1 book for 6 pencils","1 book for 2 pencils"], correctAnswer: 1, explanation: "Region 2 has the comparative advantage in books (cost 2 pencils) and exports them; Region 1 imports books. Mutually beneficial book prices lie strictly between Region 2's cost (2 pencils) and Region 1's cost (5 pencils). Only 3 pencils per book qualifies. 1 pencil is below the exporter's cost, 6 exceeds the importer's cost, and 2 equals the exporter's cost (no gain to the exporter).", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 90, question: "Country W has 100 workers; each can make 5 radios or 10 clocks per day. Country Z has 50 workers; each can make 8 radios or 8 clocks per day. Which country has the comparative advantage in radios?", options: ["Country W, because it has more workers and total output","Country Z, because it produces more radios per worker","Country Z, because its opportunity cost of a radio is 1 clock versus 2 clocks in W","Country W, because radios are its specialty by size"], correctAnswer: 2, explanation: "Comparative advantage uses per-unit opportunity cost, which here is per-worker. W's cost of a radio is 10/5 = 2 clocks; Z's is 8/8 = 1 clock. Z gives up fewer clocks per radio, so Z has the comparative advantage in radios. The number of workers (total output) and absolute per-worker radio output are about absolute advantage, not comparative advantage.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 91, question: "A nation's PPC between food and gadgets is a straight line from (0, 300 gadgets) to (150 food, 0). It currently produces and consumes at (90 food, 120 gadgets). Is this point attainable, and what is the opportunity cost of food here?", options: ["Unattainable; the point lies beyond the PPC","Attainable but inefficient; opportunity cost of 1 food = 0.5 gadgets","Attainable and efficient; opportunity cost of 1 food = 0.5 gadgets","Attainable and efficient; opportunity cost of 1 food = 2 gadgets"], correctAnswer: 3, explanation: "The PPC slope magnitude is 300 gadgets / 150 food = 2 gadgets per food, so the line is gadgets = 300 - 2(food). At 90 food, gadgets = 300 - 180 = 120, exactly on the line — attainable and efficient. The opportunity cost of 1 food is 2 gadgets. It is not beyond the PPC, not inefficient (it is on the line), and the cost is 2 (not 0.5, which inverts the ratio).", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 92, question: "Country A: 24 tools OR 8 boots per week. Country B: 9 tools OR 9 boots per week. After both specialize fully by comparative advantage, what is the total combined output of tools?", options: ["24 tools","33 tools","9 tools","48 tools"], correctAnswer: 0, explanation: "A's cost of a tool is 8/24 = 0.33 boots; B's is 9/9 = 1 boot. A has the lower tool cost, so A specializes in tools (24) and B specializes in boots. Only A makes tools, so combined tool output is 24. 33 wrongly adds B's tools, 9 is B's tool capacity, and 48 doubles A's output.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 93, question: "Suppose the world price of cloth (in terms of wheat) settles at exactly a country's own domestic opportunity cost of cloth. What happens to that country's gains from trade in cloth?", options: ["It gains the most, because prices are aligned","It has no gains from trading cloth, since the world price equals its autarky price","It must export cloth regardless of price","It must import cloth to capture the gains"], correctAnswer: 1, explanation: "Gains from trade arise when the world price differs from a country's domestic opportunity cost. If the world price of cloth equals the country's own cost, the country is indifferent between making and trading cloth — there is no gain on that margin. Aligned prices mean zero (not maximal) gain, and with no cost advantage the country is not compelled to either export or import cloth.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 94, question: "Country X: 1 worker makes 100 phones OR 200 cases. Country Y: 1 worker makes 30 phones OR 90 cases. Which country has the comparative advantage in phones, and what is its opportunity cost of a phone?", options: ["Country Y; opportunity cost 3 cases per phone","Country X; opportunity cost 0.5 cases per phone","Country X; opportunity cost 2 cases per phone","Country Y; opportunity cost 0.33 cases per phone"], correctAnswer: 2, explanation: "X's cost of a phone is 200/100 = 2 cases; Y's is 90/30 = 3 cases. X sacrifices fewer cases per phone, so X has the comparative advantage in phones at 2 cases each. Y's cost is 3 (not the one with the advantage), and 0.5 and 0.33 invert the ratios (cost of a case in phones).", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 95, question: "A trade economist notes that when two countries with different opportunity costs specialize and trade, the combined world output of both goods can rise. The fundamental reason is that:", options: ["Specialization increases the total amount of resources available worldwide","Trade barriers force countries to produce more of everything","The country with absolute advantage in both goods produces all output","Each country shifts production toward the good in which it is the relatively lower-cost producer"], correctAnswer: 3, explanation: "Gains from specialization come from each country concentrating on the good in which it has the lower opportunity cost, raising total output without any increase in resources. Resources are not created by trade, barriers reduce (not raise) efficient output, and having one country produce everything ignores comparative advantage entirely.", difficulty: "easy", topicSlug: "macro-comparative-advantage" },
  { id: 96, question: "Country A: 50 units of A-good OR 100 units of B-good. Country B: 60 units of A-good OR 60 units of B-good. Determine the RANGE of terms of trade (price of 1 A-good in B-goods) that benefits both.", options: ["Between 1 and 2 B-goods per A-good","Between 0.5 and 1 B-goods per A-good","Between 2 and 3 B-goods per A-good","Exactly 1.5 B-goods per A-good only"], correctAnswer: 0, explanation: "A's opportunity cost of an A-good is 100/50 = 2 B-goods; B's is 60/60 = 1 B-good. Country B has the comparative advantage in A-good (cost 1) and exports it; Country A imports A-good. Mutually beneficial prices for A-good lie strictly between the exporter's cost (1) and the importer's cost (2), i.e., between 1 and 2 B-goods. The other ranges fall outside this interval.", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 97, question: "A country with a straight-line PPC produces only butter and guns. Increasing butter output from 20 to 50 reduces guns from 160 to 100. What is the opportunity cost of one additional unit of butter?", options: ["0.5 guns","2 guns","3 guns","5 guns"], correctAnswer: 1, explanation: "Butter rises by 50 - 20 = 30 units; guns fall by 160 - 100 = 60 units. The opportunity cost per butter is 60/30 = 2 guns. The 0.5 figure inverts the ratio, 3 misreads the gun change, and 5 confuses totals with the marginal trade-off.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 98, question: "Country H can produce 200 units of clothing or 50 units of food. Country I can produce 60 units of clothing or 60 units of food. If both specialize by comparative advantage and then trade clothing for food at 2 clothing per 1 food, which country exports food and is it gaining?", options: ["Country H exports food because it has the absolute advantage in clothing","Country I exports clothing because it produces less food","Country I exports food; it gains because it receives 2 clothing per food, above its cost of 1 clothing per food","Neither gains because the price is exactly fair"], correctAnswer: 2, explanation: "H's cost of food is 200/50 = 4 clothing; I's is 60/60 = 1 clothing. I has the comparative advantage in food and exports it. At 2 clothing per food, I receives 2 clothing for a food that cost it only 1 clothing to make — a gain. H imports food (its own cost was 4 clothing, now only 2). Absolute advantage in clothing does not make H the food exporter, and the price (2) is not equal to either country's cost.", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 99, question: "On a graph with computers on the vertical axis and shoes on the horizontal axis, Country A's PPC is steeper than Country B's PPC (both linear). What does the steeper PPC tell you about Country A?", options: ["Country A has a lower opportunity cost of shoes than Country B","Country A has the comparative advantage in shoes","Country A and B have identical opportunity costs","Country A has a higher opportunity cost of shoes (gives up more computers per shoe) than Country B"], correctAnswer: 3, explanation: "With computers on the vertical axis, the slope magnitude equals the opportunity cost of shoes in computers. A steeper PPC means a larger slope magnitude, so Country A gives up more computers per shoe — a higher cost of shoes. Therefore A has the comparative advantage in computers (not shoes), and the costs are not identical.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 100, question: "Country A makes 12 cars OR 36 bikes per day; Country B makes 10 cars OR 20 bikes per day. After specialization, they trade 1 car for 2.5 bikes. Compute Country A's gain in bikes from importing one car instead of making it domestically.", options: ["0.5 bikes saved per car (A's own car costs 3 bikes; it now pays 2.5 bikes)","2.5 bikes saved per car","0.5 bikes lost per car","No gain, since A should make cars itself"], correctAnswer: 0, explanation: "A's opportunity cost of a car is 36/12 = 3 bikes; B's is 20/10 = 2 bikes, so B has the comparative advantage in cars and exports them. A imports cars at 2.5 bikes each, cheaper than its own cost of 3 bikes — a saving of 3 - 2.5 = 0.5 bikes per car. The 2.5 figure is the price paid, not the saving; A does not lose; and A should specialize in bikes, not make its own cars.", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 101, question: "Two countries have these opportunity costs for 1 unit of Good Y: Country 1 = 0.25 units of X; Country 2 = 0.75 units of X. Which country should specialize in Good Y, and why?", options: ["Country 2, because a higher cost means higher quality","Country 1, because it sacrifices less of Good X (0.25) per unit of Y than Country 2 (0.75)","Country 1, because it has the absolute advantage in X","Country 2, because 0.75 is closer to 1"], correctAnswer: 1, explanation: "The country with the lower opportunity cost in a good has the comparative advantage in it. Country 1 gives up only 0.25 X per Y, less than Country 2's 0.75 X, so Country 1 should specialize in Good Y. Higher cost does not imply quality, the problem gives no absolute-advantage data on X, and proximity to 1 is irrelevant.", difficulty: "easy", topicSlug: "macro-comparative-advantage" },
  { id: 102, question: "An economy can produce 120 smartphones or 480 chargers using all its resources along a linear PPC. Currently it produces 80 smartphones. How many chargers can it produce alongside the 80 smartphones?", options: ["320 chargers","400 chargers","160 chargers","240 chargers"], correctAnswer: 2, explanation: "Each smartphone costs 480/120 = 4 chargers. Producing 80 smartphones uses resources that could have made 80 x 4 = 320 chargers, leaving 480 - 320 = 160 chargers. So the efficient combination is 80 smartphones and 160 chargers. 320 is the chargers forgone, 400 and 240 result from arithmetic slips in the trade-off.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 103, question: "Country A and Country B both produce milk and eggs. A's cost: 1 milk = 2 eggs. B's cost: 1 milk = 0.5 eggs. After specialization and trade, in which direction will milk and eggs flow?", options: ["A exports milk and B exports eggs","Both export milk because milk is universally cheaper","Neither exports anything because costs differ","B exports milk (its cheaper good) and A exports eggs (its cheaper good)"], correctAnswer: 3, explanation: "B's milk cost (0.5 eggs) is below A's (2 eggs), so B has the comparative advantage in milk and exports it. Conversely, A's egg cost is 0.5 milk while B's is 2 milk, so A has the comparative advantage in eggs and exports them. Thus B exports milk, A exports eggs. Both cannot export the same good to each other, and differing costs are exactly what makes trade beneficial.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 104, question: "Country A: 16 hats OR 4 scarves per hour. Country B: 6 hats OR 6 scarves per hour. They agree to exchange at 1 scarf for 3 hats. Verify whether this rate benefits the scarf-exporting country.", options: ["Yes; Country B exports scarves, its cost is 1 hat per scarf, and it receives 3 hats — a gain of 2 hats per scarf","Yes; Country A exports scarves and gains 2 hats per scarf","No; the rate of 3 hats per scarf is below the exporter's cost","No; the exporter is indifferent at this rate"], correctAnswer: 0, explanation: "B's cost of a scarf is 6/6 = 1 hat; A's cost is 16/4 = 4 hats. B has the comparative advantage in scarves and exports them, receiving 3 hats for a scarf that cost it 1 hat — a 2-hat gain. A (cost 4 hats) imports scarves at 3 hats, also gaining. A is the hat exporter, not the scarf exporter; 3 hats exceeds B's cost of 1; and B is not indifferent since 3 > 1.", difficulty: "hard", topicSlug: "macro-comparative-advantage" },
  { id: 105, question: "A country is currently in autarky producing both software and hardware on a linear PPC where 1 software unit costs 5 hardware units. A trading bloc offers to buy software at a price of 7 hardware units each. What is the country's best response?", options: ["Specialize in hardware, because hardware is always the safer choice","Specialize in software and export it, since the offered price (7 hardware) exceeds the domestic cost (5 hardware)","Refuse to trade, because producing both goods is more balanced","Specialize in software but only consume it domestically"], correctAnswer: 1, explanation: "The country can make software at a cost of 5 hardware but sell each unit for 7 hardware abroad — a 2-hardware gain per unit. It should specialize in software and export it, importing hardware. Hardware is not automatically safer, refusing trade forgoes clear gains, and the whole point of the favorable price is to export software, not merely consume it at home.", difficulty: "medium", topicSlug: "macro-comparative-advantage" },
  { id: 106, question: "An economist begins an introductory lecture by stating that 'scarcity is the fundamental economic problem.' Which situation best illustrates the concept of scarcity as economists use the term?", options: ["A rare painting sells at auction for a record-breaking $90 million.","A natural disaster temporarily destroys a region's food supply.","A government rations gasoline during a wartime emergency.","Society has limited resources but people have virtually unlimited wants."], correctAnswer: 3, explanation: "In economics, scarcity refers to the universal, permanent condition that resources (land, labor, capital, entrepreneurship) are finite while human wants are essentially unlimited. The rare painting and the disaster describe shortages or rarity of specific items, and rationing is a response to scarcity, not its definition. Scarcity is what forces every society to make choices.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 107, question: "A student spends an evening studying for an economics exam. During that same evening she could have either earned $40 working at her part-time job or attended a concert for which she had already bought a non-refundable $25 ticket. She values the concert experience at $55. What is the opportunity cost of studying?", options: ["$40, the wage forgone","$55, the value of attending the concert","$65, the wage plus the concert ticket","$95, the wage plus the value of the concert"], correctAnswer: 1, explanation: "Opportunity cost is the value of the single best alternative forgone. Her two mutually exclusive alternatives are working (worth $40) and the concert (worth $55 in enjoyment). The best forgone alternative is the concert at $55. The $25 ticket is a sunk cost already paid and is irrelevant. You cannot add the two alternatives together because she could only have chosen one of them.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 108, question: "A nation can produce only two goods, military equipment and consumer goods, and is currently producing at a point INSIDE its production possibilities curve (PPC). Which statement is most accurate about this economy?", options: ["It is using all of its resources efficiently.","It is producing a combination that is currently unattainable.","It has unemployed or underused resources and could produce more of both goods.","It must give up consumer goods to produce more military equipment."], correctAnswer: 2, explanation: "Points inside the PPC represent inefficient production, meaning some resources are unemployed or underutilized. From such a point the economy can increase production of one good without sacrificing the other, or even increase both, until it reaches the frontier. Only points ON the curve are efficient, and points outside are currently unattainable.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 109, question: "A country's PPC for wheat and steel is a straight downward-sloping line. As the country moves along this line by reallocating resources from wheat to steel, what happens to the opportunity cost of producing additional steel?", options: ["It increases because resources are not perfectly adaptable.","It decreases because of economies of scale.","It remains constant because the goods use resources equally well.","It first decreases and then increases."], correctAnswer: 2, explanation: "A straight-line (linear) PPC has a constant slope, which means the opportunity cost of one good in terms of the other is constant. This occurs when resources are equally suited to producing both goods. A bowed-out (concave) PPC, by contrast, reflects increasing opportunity costs because resources are not perfectly adaptable between uses.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 110, question: "The table shows four output combinations on a nation's PPC for capital goods and consumer goods:\n\nPoint | Capital | Consumer\n  A   |   0     |   120\n  B   |  10     |   100\n  C   |  20     |    70\n  D   |  30     |    30\n\nWhat is the opportunity cost of moving from point C to point D?", options: ["10 units of capital goods","30 units of consumer goods","40 units of consumer goods","70 units of consumer goods"], correctAnswer: 2, explanation: "Moving from C to D increases capital goods from 20 to 30 (a gain of 10 capital). The cost is the consumer goods given up: 70 - 30 = 40 consumer goods. The opportunity cost of those additional 10 capital goods is the 40 consumer goods sacrificed. The bowed pattern (costs of 20, 30, then 40 consumer goods per 10 capital) shows increasing opportunity cost.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 111, question: "Using the same PPC data (A: 0 capital/120 consumer; B: 10/100; C: 20/70; D: 30/30), the increasing amounts of consumer goods given up for each additional 10 units of capital goods illustrate which economic principle?", options: ["The law of diminishing marginal utility","The law of increasing opportunity cost","Comparative advantage","Constant returns to scale"], correctAnswer: 1, explanation: "As the nation produces more capital goods, it sacrifices increasing amounts of consumer goods (20, then 30, then 40), reflecting the law of increasing opportunity cost. This arises because resources are not equally productive in all uses, so the least-suited resources must be shifted as production of one good expands. This is what gives the PPC its bowed-out (concave) shape.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 112, question: "A farmer owns 100 acres and must decide how to allocate them between corn and soybeans. Which of the following is the clearest example of opportunity cost in this decision?", options: ["The cost of the seeds and fertilizer she buys for the corn","The property taxes she pays on all 100 acres","The soybean revenue she gives up by planting corn on a portion of the land","The interest on the loan she took to buy the farm equipment"], correctAnswer: 2, explanation: "Opportunity cost is the value of the best forgone alternative. By devoting acres to corn, she gives up the soybeans (and their revenue) she could have grown on that land. Seeds, fertilizer, taxes, and loan interest are explicit monetary expenses, not the forgone alternative use of the land itself. Opportunity cost captures what is sacrificed by choosing one use over another.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 113, question: "An economy's PPC shifts outward (the entire curve moves away from the origin). Which of the following could NOT, by itself, cause this shift?", options: ["A technological breakthrough that raises productivity in both industries","An increase in the size and skill of the labor force","A movement from a point inside the curve to a point on the curve","Discovery of large new deposits of natural resources"], correctAnswer: 2, explanation: "An outward shift of the entire PPC represents economic growth and is caused by increases in resources or improvements in technology. Moving from inside the curve to a point on it is a change in efficiency (reducing unemployment of resources), which is a movement TO the existing curve, not a shift of the curve itself. The other three all expand the economy's productive capacity.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 114, question: "Country X discovers a new technology that dramatically improves the production of computers but has no effect on the production of agricultural goods. On a PPC with computers on the vertical axis and agricultural goods on the horizontal axis, how does the curve change?", options: ["The entire curve shifts outward uniformly.","The vertical (computer) intercept moves outward while the horizontal (agricultural) intercept stays fixed.","The horizontal (agricultural) intercept moves outward while the vertical intercept stays fixed.","The curve shifts inward because resources are diverted to computers."], correctAnswer: 1, explanation: "Technology that improves only computer production raises the maximum number of computers the economy can make, pushing the vertical intercept outward. Since agricultural production is unaffected, the horizontal intercept stays fixed. The result is a curve that pivots outward along the computer axis only. A uniform outward shift would require improvements affecting both goods.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 115, question: "Maria has $50 to spend on either books or movie tickets. Books cost $25 each and movie tickets cost $10 each. If she is currently buying 2 books, what is the opportunity cost (in movie tickets) of those 2 books?", options: ["2 movie tickets","5 movie tickets","10 movie tickets","0 movie tickets"], correctAnswer: 1, explanation: "Two books cost 2 x $25 = $50, using her entire budget. That same $50 could have bought $50 / $10 = 5 movie tickets. Therefore the opportunity cost of the 2 books is the 5 movie tickets forgone. Opportunity cost here is measured in terms of the alternative good that the same resources (her budget) could have purchased.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 116, question: "A small island economy produces only fish and coconuts. With all resources devoted to fish it can catch 80 fish; with all resources devoted to coconuts it can gather 40 coconuts. The PPC is a straight line. What is the opportunity cost of producing 1 additional coconut?", options: ["0.5 fish","1 fish","2 fish","40 fish"], correctAnswer: 2, explanation: "Giving up all 40 coconuts allows 80 fish, so 40 coconuts trade off against 80 fish. Therefore 1 coconut costs 80/40 = 2 fish. Equivalently, the slope of the PPC (fish per coconut) is 80/40 = 2. The reciprocal, 0.5, is the opportunity cost of 1 fish (in coconuts), a common reversal error.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 117, question: "During a recession, a nation that had been producing on its PPC experiences widespread unemployment. On the PPC diagram, this change is best represented as:", options: ["A movement from a point on the PPC to a point inside the PPC","An inward shift of the entire PPC","A movement along the PPC from one efficient point to another","A movement from a point on the PPC to a point outside the PPC"], correctAnswer: 0, explanation: "A recession causes resources (especially labor) to become unemployed, so the economy no longer uses all its resources fully. This is shown as a movement from a point on the frontier to a point INSIDE it (inefficient production). The economy's underlying capacity has not been destroyed, so the curve itself does not shift inward; it is simply not being reached.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 118, question: "Which of the following statements correctly distinguishes a shortage from scarcity?", options: ["A shortage is permanent, while scarcity is temporary.","Scarcity affects only poor countries, while shortages affect all countries.","Scarcity is the universal imbalance between unlimited wants and limited resources; a shortage is a specific situation where quantity demanded exceeds quantity supplied at a given price.","Shortages can be eliminated by economic growth, while scarcity cannot be eliminated by anything."], correctAnswer: 2, explanation: "Scarcity is the fundamental, ever-present economic condition that wants exceed available resources and can never be fully eliminated. A shortage is a market-specific phenomenon that occurs when the price is below equilibrium so that quantity demanded exceeds quantity supplied; shortages can be resolved by a price increase. Confusing the two is a common error.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 119, question: "An economy operates on its PPC at a point where it produces large quantities of consumer goods and very few capital goods. Holding all else equal, what is the most likely long-run consequence of this choice compared with a country that produces more capital goods?", options: ["Its PPC will shift outward more slowly in the future.","Its PPC will shift outward more rapidly in the future.","Its PPC will not shift at all because it is already efficient.","Its PPC will shift inward in the future."], correctAnswer: 0, explanation: "Capital goods (tools, machines, factories) increase an economy's future productive capacity. A country that favors current consumer goods over capital goods invests less in future production, so its PPC will tend to shift outward more slowly than that of a country emphasizing capital goods. This illustrates the present-versus-future opportunity cost embedded in the capital-versus-consumption choice.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 120, question: "A city is deciding whether to build a new park on a vacant downtown lot. The lot could instead be sold to a developer for $4 million, or leased to a parking company for $300,000 per year. Construction of the park would cost $1.5 million. In evaluating the opportunity cost of the land used for the park (ignoring the construction cost), the relevant figure is:", options: ["$1.5 million, the construction cost","The single highest-valued forgone use of the land","The sum of the sale value and all future lease payments","Zero, because the city already owns the land"], correctAnswer: 1, explanation: "Opportunity cost is the value of the best single alternative use forgone, not the sum of all alternatives. The city must compare the one-time $4 million sale against the stream of $300,000 annual lease payments and use whichever is more valuable as the opportunity cost of the land. The construction cost is a separate explicit cost, and ownership does not make the land 'free'-it still has valuable alternative uses.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 121, question: "A factory worker quits a job paying $48,000 per year to open her own bakery. She uses $20,000 of her own savings (which had been earning 5% annual interest) to buy equipment and pays $30,000 per year in rent, ingredients, and supplies. What is the total annual opportunity cost (implicit costs) of running the bakery?", options: ["$30,000","$48,000","$49,000","$78,000"], correctAnswer: 2, explanation: "Implicit (opportunity) costs are the forgone returns on resources the owner already owns. She gives up her $48,000 salary and the $1,000 in interest her $20,000 savings would have earned (5% of $20,000), for a total of $49,000 in implicit costs. The $30,000 is an explicit cost paid to others, not an opportunity cost of her own resources. Economists count both, but the question asks only for the implicit (opportunity) costs.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 122, question: "Two points on a nation's bowed-out PPC are: producing 50 tanks and 200 bushels of grain, versus producing 60 tanks and 170 bushels of grain. What is the opportunity cost of each additional tank as the nation moves from the first point to the second?", options: ["3 bushels of grain per tank","10 bushels of grain per tank","30 bushels of grain per tank","1/3 bushel of grain per tank"], correctAnswer: 0, explanation: "Tank production rises from 50 to 60, a gain of 10 tanks. Grain falls from 200 to 170, a loss of 30 bushels. The opportunity cost per tank is 30 bushels / 10 tanks = 3 bushels per tank. Dividing in the wrong order (10/30) gives the reciprocal 1/3, the opportunity cost of grain in terms of tanks, which is a common reversal mistake.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 123, question: "Which of the following best explains why a typical production possibilities curve is bowed outward (concave to the origin) rather than a straight line?", options: ["Resources become more abundant as production increases.","Resources are specialized and not equally productive in all uses, causing opportunity cost to rise.","The economy experiences constant opportunity costs across all output levels.","Technology improves automatically as more of a good is produced."], correctAnswer: 1, explanation: "The bowed-out shape reflects the law of increasing opportunity cost. Because resources are specialized and better suited to some uses than others, as a society produces more of one good it must transfer increasingly ill-suited resources, sacrificing ever-larger amounts of the other good. If resources were perfectly adaptable, opportunity cost would be constant and the PPC would be a straight line.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 124, question: "A government considers a proposal to expand its military, which would require shifting workers and factories from civilian production. An economist describes this as a 'guns versus butter' trade-off. This phrase is intended to illustrate:", options: ["That military spending always reduces a nation's total output","That butter is a more efficient use of resources than guns","That wealthy nations face no real trade-offs","That producing more of one type of good requires giving up some of another due to scarce resources"], correctAnswer: 3, explanation: "'Guns versus butter' is the classic metaphor for the opportunity cost embedded in any PPC: because resources are scarce, devoting more to military goods (guns) means producing fewer civilian goods (butter). The phrase makes no claim about which is more efficient or that output falls; it simply highlights that scarcity forces a trade-off between the two categories of output.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 125, question: "An economy is at point on its PPC and a journalist claims, 'If we just decided to, we could produce more of both consumer goods and capital goods at the same time without any cost.' For an economy producing efficiently on its PPC, this claim is:", options: ["Correct, because growth is always possible at no cost","Incorrect, because at an efficient point on the PPC more of one good requires less of the other","Correct, only if the economy is in a recession","Incorrect, because the PPC can never shift outward"], correctAnswer: 1, explanation: "At a point ON the PPC, the economy is already producing efficiently and fully employing its resources, so more of one good necessarily means less of the other; there is no free lunch. The journalist's claim would only hold if the economy were currently inside the PPC (with idle resources). Growth (an outward shift) is possible over time but generally requires sacrificing current consumption to build capital, which is itself a cost.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 126, question: "A consulting firm bills clients $200 per hour. The owner is offered a chance to spend 5 hours mentoring at a local school, an activity she personally values at $600 of satisfaction. What is the net benefit (or cost) to her, in monetary terms, of choosing to mentor instead of working those 5 hours?", options: ["A net benefit of $600","A net cost of $400","A net benefit of $400","A net cost of $1,000"], correctAnswer: 1, explanation: "Mentoring for 5 hours means forgoing 5 x $200 = $1,000 in billable revenue, which is the opportunity cost. The benefit she gains is the $600 of personal satisfaction. Net benefit = $600 benefit - $1,000 opportunity cost = -$400, i.e., a net cost of $400. Rational decision-making weighs the value gained against the value of the best forgone alternative.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 127, question: "Which of the following pairs correctly matches an economy's situation with its representation on a PPC diagram?", options: ["Full employment and efficiency -> a point inside the curve","Economic growth -> a movement along the curve","Unemployment of resources -> a point inside the curve","An unattainable output combination -> a point on the curve"], correctAnswer: 2, explanation: "Unemployed or underutilized resources are represented by a point INSIDE the PPC, where the economy produces less than its potential. Full employment with efficiency is a point ON the curve, economic growth is an outward SHIFT of the curve, and currently unattainable combinations lie OUTSIDE the curve. Matching each concept to its correct graphical representation is a core PPC skill.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 128, question: "Suppose a nation's PPC for robots and bread is given by the equation: (robots/100) + (bread/400) = 1, where robots and bread are annual output. What is the opportunity cost of producing 1 additional robot?", options: ["4 units of bread","1/4 unit of bread","100 units of bread","400 units of bread"], correctAnswer: 0, explanation: "The intercepts are 100 robots (when bread = 0) and 400 bread (when robots = 0). The straight-line trade-off means giving up all 400 bread yields 100 robots, so 1 robot costs 400/100 = 4 bread. Equivalently, solving for bread gives bread = 400 - 4(robots), so the slope is -4: each robot costs 4 bread. The reciprocal 1/4 is the cost of 1 bread in robots.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 129, question: "A student argues, 'Because Bill Gates is so wealthy, he does not face scarcity.' The best economic critique of this statement is that:", options: ["Scarcity applies only to money, which Gates has plenty of","Scarcity applies only to entire nations, not to individuals","Gates does not face scarcity because he can buy anything he wants","Even with great wealth, time is a finite resource, so Gates still faces trade-offs and opportunity costs"], correctAnswer: 3, explanation: "Scarcity is not merely about money. Even an extraordinarily wealthy person has only 24 hours in a day and a finite lifespan, so every choice about how to use time carries an opportunity cost. Because no amount of wealth eliminates the finiteness of time (and other resources), even the richest individuals must make choices and confront scarcity.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 130, question: "A country can devote its resources to either education (which builds human capital) or current consumption. Two policy advisors disagree. Advisor 1 favors more education; Advisor 2 favors more current consumption. Which statement best captures the opportunity cost faced by this society?", options: ["Choosing more education sacrifices some current consumption but may shift the future PPC outward.","Choosing more education has no opportunity cost because education is beneficial.","Choosing more current consumption guarantees faster future growth.","There is no trade-off because the two choices use entirely different resources."], correctAnswer: 0, explanation: "Education and current consumption compete for the same scarce resources, so devoting more to education means forgoing some present consumption-that is its opportunity cost. The benefit is that investing in human capital can expand future productive capacity, shifting the PPC outward later. Beneficial activities still carry opportunity costs, and emphasizing current consumption tends to slow, not speed, future growth.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 131, question: "The table gives the maximum output of two goods using all of an economy's resources:\n\nGood A (alone): 600 units\nGood B (alone): 300 units\n\nThe PPC is linear. If the economy currently produces 200 units of Good A, how many units of Good B can it produce?", options: ["100 units","200 units","250 units","300 units"], correctAnswer: 1, explanation: "With a linear PPC, the equation is A/600 + B/300 = 1. Substituting A = 200: 200/600 + B/300 = 1, so B/300 = 1 - 1/3 = 2/3, giving B = 200. Each unit of A costs 300/600 = 1/2 unit of B, so producing 200 A (instead of zero) costs 100 B, leaving 300 - 100 = 200 B. Both methods confirm 200 units of Good B.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 132, question: "Which of the following is the best example of opportunity cost being measured in terms of time rather than money?", options: ["Paying $12 for a movie ticket","Choosing to wait in a 2-hour line for free concert tickets instead of working","Spending $80 on a new pair of shoes","Earning $15 per hour at a part-time job"], correctAnswer: 1, explanation: "Waiting in line costs no money, but the 2 hours spent could have been used to work or do something else valuable; the forgone use of that time is the opportunity cost. The other options describe explicit monetary payments or wages, not the sacrifice of time. Opportunity cost includes non-monetary sacrifices such as time, which is itself a scarce resource.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 133, question: "An economy initially produces on its PPC. A devastating earthquake destroys 20% of its factories and capital stock but leaves its labor force and technology unchanged. The most accurate way to depict this on a PPC diagram is:", options: ["A movement from a point on the PPC to a point inside it","An inward shift of the entire PPC","A movement along the PPC","An outward shift of the PPC"], correctAnswer: 1, explanation: "Destroying part of the capital stock permanently reduces the economy's productive capacity, so the entire PPC shifts inward (toward the origin). This differs from a recession, where capacity is intact but underused (a point inside the existing curve). Because actual resources were lost, the frontier itself contracts.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 134, question: "A car manufacturer can use its assembly line to produce either sedans or SUVs. In one shift it can make 40 sedans or 25 SUVs. Currently it makes 16 sedans. Assuming a constant trade-off, how many SUVs can it make in the same shift?", options: ["9 SUVs","10 SUVs","15 SUVs","24 SUVs"], correctAnswer: 2, explanation: "Each sedan costs 25/40 = 0.625 SUVs. Producing 16 sedans uses 16 x 0.625 = 10 SUVs worth of capacity, leaving 25 - 10 = 15 SUVs. Equivalently, the fraction of capacity on sedans is 16/40 = 0.4, leaving 0.6 of capacity for SUVs: 0.6 x 25 = 15 SUVs. Both approaches give 15 SUVs.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 135, question: "An economist states that a point lying OUTSIDE a country's current PPC is unattainable today but might become attainable in the future. Which single development would make that outside point reachable?", options: ["Reducing unemployment to put idle resources back to work","Reallocating resources from one good to the other","Economic growth that shifts the entire PPC outward","Producing at a more efficient point on the existing curve"], correctAnswer: 2, explanation: "A point outside the current PPC exceeds the economy's present capacity and can only be reached if the curve itself shifts outward through economic growth (more resources or better technology). Reducing unemployment or improving efficiency can only move production up to the existing frontier, not beyond it. Reallocation just moves along the curve. Growth is what expands the set of attainable combinations.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 136, question: "Jordan must choose among three ways to spend Saturday afternoon: tutoring for $30, helping a friend move (which he values at $45), or relaxing at home (which he values at $20). He chooses to relax at home. What is the opportunity cost of his choice?", options: ["$20, the value of relaxing","$30, the tutoring pay","$45, the value of helping his friend move","$75, the tutoring pay plus helping his friend"], correctAnswer: 2, explanation: "Opportunity cost is the value of the single best forgone alternative. Among the rejected options, helping his friend move ($45) is worth more than tutoring ($30), so the best alternative he gave up is worth $45. The $20 value of relaxing is the benefit of his chosen activity, not its cost, and you never sum the forgone options.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 137, question: "On a PPC with butter on one axis and guns on the other, an economy moves from a point of high butter/low guns to a point of low butter/high guns. Along a bowed-out PPC, what happens to the opportunity cost of producing each additional gun during this movement?", options: ["It stays constant because the PPC has a fixed slope.","It rises because increasingly butter-suited resources must be shifted to gun production.","It falls because gun production becomes more efficient.","It cannot be determined without knowing prices."], correctAnswer: 1, explanation: "On a bowed-out PPC the slope steepens as you move toward more guns, so each additional gun costs increasingly more butter. This reflects the law of increasing opportunity cost: as gun production expands, resources that were better suited to making butter must be reallocated, sacrificing larger and larger amounts of butter. Prices are irrelevant; opportunity cost here is measured in forgone butter.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 138, question: "A firm is deciding whether to keep using a machine it already owns or sell it. The machine originally cost $50,000, has a current resale value of $12,000, and if kept could generate $9,000 in additional profit over the next year (after which it is worthless). From an opportunity-cost perspective, which figure is the cost of continuing to use the machine for another year?", options: ["$12,000, the forgone resale value","$50,000, the original purchase price","$9,000, the additional profit","$38,000, the original price minus resale value"], correctAnswer: 0, explanation: "The opportunity cost of keeping the machine is the $12,000 the firm gives up by not selling it now. The original $50,000 is a sunk cost and irrelevant to the forward-looking decision. Comparing the opportunity cost ($12,000) with the benefit of keeping it ($9,000 profit) shows the firm should actually sell, since $12,000 > $9,000. The correct cost figure is the $12,000 forgone resale value.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 139, question: "Which of the following best describes the relationship between scarcity and the need for an economic system to answer the three basic economic questions (what, how, and for whom to produce)?", options: ["Scarcity is irrelevant because the questions arise only in market economies.","The three questions matter only when resources are abundant.","Only command economies must answer these questions; market economies avoid them.","Because resources are scarce, every society must make choices about what, how, and for whom to produce."], correctAnswer: 3, explanation: "Scarcity is precisely why every society-regardless of its economic system-must answer the three fundamental questions. Because resources cannot satisfy all wants, choices must be made about which goods to produce, how to produce them, and who receives them. Market, command, and mixed economies all confront these questions; they simply answer them through different mechanisms.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 140, question: "An economy has a bowed-out PPC. Currently it is producing at a point that is both on the curve and where the value to society of the last unit of each good is maximized given its resources. Suppose it then chooses to produce inside the curve to 'save resources for later.' What is the flaw in this reasoning?", options: ["Producing inside the curve wastes resources in the current period rather than saving them; idle resources like labor and time cannot be stored.","Producing inside the curve is impossible.","Producing inside the curve automatically shifts the PPC outward.","Producing inside the curve always increases future growth."], correctAnswer: 0, explanation: "Producing inside the PPC means leaving resources unemployed, which does not 'save' them-many resources, especially labor and time, cannot be stockpiled, so their current potential output is simply lost forever. To prepare for the future, an economy should produce efficiently (on the curve) and devote some output to capital goods, which expands future capacity. Idleness wastes scarce resources rather than conserving them.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 141, question: "A high school graduate is deciding whether to attend a 4-year college. Tuition and books total $40,000 over four years. By attending, she gives up a job that would have paid $25,000 per year. What is the total opportunity cost of attending college for the four years?", options: ["$40,000","$100,000","$140,000","$25,000"], correctAnswer: 2, explanation: "The full opportunity cost of college includes both the explicit costs paid ($40,000 in tuition and books) and the implicit cost of forgone earnings (4 x $25,000 = $100,000). Adding these gives $40,000 + $100,000 = $140,000. A common error is to count only the $40,000 explicit cost and ignore the substantial earnings sacrificed by not working, which is often the largest part of the cost of college.", difficulty: "hard", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 142, question: "Two countries, Alpha and Beta, both lie on their respective PPCs. Alpha devotes 30% of its output to capital goods, while Beta devotes only 5%. Assuming all else is equal, which prediction about their future PPCs is most consistent with economic theory?", options: ["Beta's PPC will shift outward faster than Alpha's.","Both PPCs will shift outward at exactly the same rate.","Neither PPC will shift because both are already efficient.","Alpha's PPC will shift outward faster than Beta's."], correctAnswer: 3, explanation: "Capital goods expand future productive capacity, so the country investing more in them (Alpha, at 30%) will tend to experience faster economic growth, shifting its PPC outward more rapidly than Beta's. The opportunity cost is that Alpha forgoes more current consumer goods today. Being currently efficient (on the curve) does not prevent future growth; the composition of output drives the differing growth rates.", difficulty: "medium", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 143, question: "A policymaker claims, 'A well-designed government program can provide benefits to society at literally no cost.' Based on the principle of scarcity, the best response is:", options: ["The claim is valid as long as the program is funded by borrowing.","The claim ignores opportunity cost: resources used for the program could have produced other valued goods or services.","The claim is valid because government resources are unlimited.","The claim is valid only if the program runs a budget surplus."], correctAnswer: 1, explanation: "Because resources are scarce, every government program has an opportunity cost: the labor, materials, and funds devoted to it cannot be used for other valued purposes (the principle that 'there is no such thing as a free lunch'). Borrowing or running a surplus does not eliminate this cost-it merely shifts when and how the cost is borne. Scarcity guarantees that no program is truly costless.", difficulty: "easy", topicSlug: "macro-scarcity-opportunity-cost" },
  { id: 144, question: "The short-run Phillips curve illustrates which of the following relationships?", options: ["A positive relationship between the unemployment rate and the inflation rate in the short run","An inverse relationship between the unemployment rate and the inflation rate in the short run","A positive relationship between real GDP and the price level in the long run","An inverse relationship between nominal wages and real output in the long run"], correctAnswer: 1, explanation: "The short-run Phillips curve (SRPC) shows an inverse (negative) tradeoff: as the inflation rate rises, the unemployment rate falls, and vice versa. The first option reverses the sign of the relationship. The third describes the aggregate supply/price-level relationship, and the fourth misstates the long-run labor market, where there is no permanent tradeoff.", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 145, question: "An economy is initially producing at its full-employment level of output with a natural rate of unemployment of 5%. The central bank unexpectedly increases the money supply, causing the actual inflation rate to rise above the expected rate. In the SHORT run, what happens along the short-run Phillips curve?", options: ["The economy moves up and to the left, with unemployment falling below 5%","The economy moves down and to the right, with unemployment rising above 5%","The short-run Phillips curve shifts rightward with no change in unemployment","The long-run Phillips curve shifts leftward, lowering the natural rate"], correctAnswer: 0, explanation: "Unexpectedly higher inflation reduces real wages and boosts profits and hiring in the short run, so the economy moves up the existing SRPC to a point with higher inflation and lower unemployment (below the 5% natural rate). It does not move down/right (that is the opposite shock), and a single demand shock moves the economy ALONG the SRPC rather than shifting it. The natural rate is unchanged by a monetary shock.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 146, question: "The long-run Phillips curve (LRPC) is best described as", options: ["A downward-sloping curve showing a permanent inflation-unemployment tradeoff","An upward-sloping curve reflecting cost-push inflation","A horizontal line at the current inflation rate","A vertical line at the natural rate of unemployment"], correctAnswer: 3, explanation: "In the long run there is no tradeoff between inflation and unemployment, so the LRPC is vertical at the natural rate of unemployment. Output and employment return to their full-employment levels regardless of the inflation rate. A downward slope describes only the SHORT run, and the upward/horizontal options do not correspond to the standard Phillips-curve framework.", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 147, question: "The natural rate of unemployment in an economy is 4.5%. According to the long-run Phillips curve, what will the unemployment rate be in the long run if the central bank permanently raises the inflation rate from 2% to 6%?", options: ["It will fall to a value below 4.5%","It will remain at 4.5%","It will rise above 4.5% in proportion to inflation","It cannot be determined without knowing the velocity of money"], correctAnswer: 1, explanation: "Because the LRPC is vertical at the natural rate, higher inflation has no permanent effect on unemployment. In the long run the economy returns to the natural rate of 4.5% regardless of whether inflation is 2% or 6%. The other options incorrectly assume a permanent tradeoff or dependence on monetary velocity.", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 148, question: "Suppose workers and firms expect 3% inflation and negotiate wage contracts accordingly. Actual inflation then turns out to be 3%. On the Phillips-curve diagram, where is the economy operating?", options: ["Up the SRPC at a point with unemployment below the natural rate","Down the SRPC at a point with unemployment above the natural rate","On a new SRPC that has shifted leftward from higher expected inflation","At the intersection of the SRPC and the LRPC, at the natural rate of unemployment"], correctAnswer: 3, explanation: "When actual inflation equals expected inflation, there are no surprises, real wages are at their intended level, and the economy operates at the natural rate of unemployment, which is the point where the SRPC crosses the vertical LRPC. Moving below the natural rate requires actual inflation ABOVE expected; moving above requires actual BELOW expected.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 149, question: "An economy experiences a sharp increase in oil prices, a negative supply shock. What happens to the short-run Phillips curve?", options: ["It shifts rightward (upward), so any given unemployment rate is associated with higher inflation","It shifts leftward (downward), so any given unemployment rate is associated with lower inflation","It becomes vertical at a lower natural rate of unemployment","The economy simply moves up along the existing curve with no shift"], correctAnswer: 0, explanation: "A negative (adverse) supply shock raises production costs and prices for every level of output, shifting the SRPC up/right so each unemployment rate now corresponds to higher inflation; this produces stagflation (higher inflation and higher unemployment together). A leftward shift would come from a positive supply shock. Supply shocks shift the curve rather than moving along it, and they do not change the curve's vertical/long-run character in this way.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 150, question: "Which combination would most likely cause an economy to move DOWN and to the RIGHT along a given short-run Phillips curve?", options: ["An increase in government spending that boosts aggregate demand","A decrease in aggregate demand caused by falling consumer confidence","A favorable supply shock that lowers input prices","An increase in the expected rate of inflation"], correctAnswer: 1, explanation: "A decline in aggregate demand reduces both inflation and output, raising unemployment, which is a movement down and to the right along the SRPC. Increased government spending raises AD (movement up/left). A favorable supply shock shifts the curve, not a movement along it, and a change in expected inflation shifts the SRPC rather than causing a movement along the existing one.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 151, question: "The economy is operating at point A with unemployment of 3% (below the natural rate of 5%) and inflation of 7%. Over time, workers come to expect the higher inflation and demand higher nominal wages. According to the self-correcting mechanism, what happens next?", options: ["The SRPC shifts upward and the economy returns toward 5% unemployment at higher inflation","The SRPC shifts downward and unemployment falls further below 5%","The LRPC shifts rightward to 3% to validate the lower unemployment","The economy stays permanently at 3% unemployment because of money illusion"], correctAnswer: 0, explanation: "Operating below the natural rate is unsustainable. As expected inflation rises to match actual inflation, the SRPC shifts upward; the economy slides back to the natural rate of 5% but at a higher inflation rate. Money illusion is temporary, so the economy does not stay at 3%, and the LRPC does not move in response to a demand-driven boom.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 152, question: "On a Phillips-curve diagram, an increase in expected inflation is represented by", options: ["A movement up along a fixed short-run Phillips curve","A leftward (downward) shift of the short-run Phillips curve","A rightward (upward) shift of the short-run Phillips curve","A rightward shift of the long-run Phillips curve"], correctAnswer: 2, explanation: "Each SRPC is drawn for a particular expected inflation rate. When expected inflation rises, the entire SRPC shifts up/right so that any given unemployment rate is associated with higher actual inflation. A movement ALONG the curve comes from demand changes, not expectations changes, and the LRPC (the natural rate) is unaffected by expected inflation.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 153, question: "Two short-run Phillips curves are drawn: SRPC1 reflects expected inflation of 2%, and SRPC2 lies above it reflecting expected inflation of 5%. Both curves intersect the long-run Phillips curve at the natural rate. The vertical distance from SRPC1 to SRPC2 at the natural rate is approximately", options: ["0 percentage points, since they meet on the LRPC","3 percentage points, equal to the difference in expected inflation","5 percentage points, equal to the higher expected inflation rate","2 percentage points, equal to the lower expected inflation rate"], correctAnswer: 1, explanation: "Each SRPC crosses the LRPC at the natural rate, where actual inflation equals expected inflation. So SRPC1 crosses at 2% inflation and SRPC2 crosses at 5% inflation. The vertical gap between them at the natural rate equals 5% - 2% = 3 percentage points. They do not coincide; the gap is the difference, not the level, of expected inflation.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 154, question: "An economy with a natural rate of unemployment of 6% is currently in a recession with unemployment at 9% and inflation at 1%. If the government takes no action and the economy self-corrects, what happens along the Phillips-curve diagram?", options: ["Expected inflation rises, shifting the SRPC up and lowering unemployment","Expected inflation falls, shifting the SRPC down and returning unemployment to 6%","The LRPC shifts left so that 9% becomes the new natural rate","Unemployment stays at 9% because wages are fully flexible"], correctAnswer: 1, explanation: "With unemployment above the natural rate, there is downward pressure on wages and prices. As expected inflation falls, the SRPC shifts downward, the economy slides back toward the natural rate of 6%, and unemployment declines. The LRPC stays fixed at the structural natural rate, and self-correction relies precisely on wage and price adjustment.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 155, question: "Which of the following events would shift the LONG-run Phillips curve to the LEFT (toward a lower natural rate of unemployment)?", options: ["A permanent increase in the money supply growth rate","An expansionary fiscal policy that raises aggregate demand","An improvement in job-matching technology that reduces frictional unemployment","A temporary favorable supply shock that lowers oil prices"], correctAnswer: 2, explanation: "The LRPC sits at the natural rate, which depends on structural and frictional factors. Better job-matching (for example, online job platforms) reduces frictional unemployment, lowering the natural rate and shifting the LRPC left. Monetary growth and fiscal expansion affect inflation/demand but not the natural rate, and a temporary supply shock moves the SRPC, not the LRPC.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 156, question: "According to the expectations-augmented Phillips curve, the actual inflation rate equals", options: ["Expected inflation minus the natural rate of unemployment","The growth rate of the money supply divided by velocity","The natural rate of unemployment times the output gap","Expected inflation plus a term that rises as unemployment falls below the natural rate (plus a supply-shock term)"], correctAnswer: 3, explanation: "The expectations-augmented Phillips curve is written as actual inflation = expected inflation - b(u - u*) + supply shock, where u is unemployment and u* is the natural rate. When unemployment is below the natural rate the -b(u - u*) term is positive, so inflation rises above expected inflation. The other options confuse this with the quantity theory of money or invent relationships that are not part of the model.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 157, question: "Suppose expected inflation is 4%, the natural rate of unemployment is 5%, and the Phillips relationship is: actual inflation = expected inflation - 0.5(u - 5). If the actual unemployment rate is 3%, what is the actual inflation rate?", options: ["3%","4%","5%","6%"], correctAnswer: 2, explanation: "Substitute u = 3: inflation = 4 - 0.5(3 - 5) = 4 - 0.5(-2) = 4 + 1 = 5%. Because unemployment (3%) is below the natural rate (5%), actual inflation exceeds expected inflation. The 4% answer forgets the unemployment-gap term, and 3% incorrectly subtracts instead of adds.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 158, question: "Using the relationship actual inflation = expected inflation - 0.4(u - u*), with expected inflation of 3%, a natural rate u* of 6%, and an actual unemployment rate of 9%, the actual inflation rate is", options: ["1.2%","1.8%","3.0%","4.2%"], correctAnswer: 1, explanation: "inflation = 3 - 0.4(9 - 6) = 3 - 0.4(3) = 3 - 1.2 = 1.8%. With unemployment above the natural rate, actual inflation falls below expected inflation. The 4.2% answer adds the gap term instead of subtracting, and 1.2% mistakenly reports just the adjustment term.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 159, question: "A point lying to the LEFT of the long-run Phillips curve (unemployment below the natural rate) corresponds to which condition in the AD/AS model?", options: ["A recessionary (contractionary) gap with output below potential","An inflationary (expansionary) gap with output above potential","Long-run equilibrium with output at potential","A point on the vertical long-run aggregate supply curve"], correctAnswer: 1, explanation: "Unemployment below the natural rate means the economy is producing above potential output, which is an inflationary (expansionary) gap. In AD/AS terms, real GDP exceeds full-employment GDP. A recessionary gap corresponds to a point to the RIGHT of the LRPC (unemployment above the natural rate), and long-run equilibrium is ON the LRPC.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 160, question: "The short-run aggregate supply curve and the short-run Phillips curve are related such that a movement upward along the SRAS curve (rising price level, rising output) corresponds to which movement on the Phillips curve?", options: ["A movement down and to the right along the SRPC (lower inflation, higher unemployment)","A movement up and to the left along the SRPC (higher inflation, lower unemployment)","A rightward shift of the SRPC","A movement along the vertical LRPC"], correctAnswer: 1, explanation: "The SRPC is essentially the SRAS curve viewed through inflation and unemployment. Higher output along SRAS means lower unemployment, and a rising price level means higher inflation, which is a movement up and to the left on the SRPC. The down/right movement corresponds instead to falling output (a leftward AD move), and shifts versus movements are distinct.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 161, question: "Milton Friedman and Edmund Phelps argued in the late 1960s that the apparent long-run inflation-unemployment tradeoff would disappear because", options: ["Velocity of money is constant in the long run","Workers and firms eventually adjust their inflation expectations, eliminating any real effects of inflation","The natural rate of unemployment is always zero","Fiscal policy is more powerful than monetary policy in the long run"], correctAnswer: 1, explanation: "Friedman and Phelps argued that any tradeoff depends on people being fooled by unexpected inflation. Once expectations adjust to actual inflation, unemployment returns to the natural rate, so the LRPC is vertical and there is no permanent tradeoff. The claim does not rest on constant velocity, a zero natural rate, or the relative power of fiscal policy.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 162, question: "An economy starts in long-run equilibrium. The central bank conducts expansionary monetary policy. Trace the SHORT-RUN then LONG-RUN effects on the Phillips-curve diagram.", options: ["Short run: move down-right along SRPC; long run: SRPC shifts down, returning to a lower natural rate","Short run: move up-left along SRPC to lower unemployment and higher inflation; long run: SRPC shifts up, returning to the natural rate at higher inflation","Short run: LRPC shifts left; long run: SRPC shifts right","Short run and long run: unemployment falls permanently below the natural rate"], correctAnswer: 1, explanation: "Expansionary monetary policy raises AD: in the short run the economy moves up the existing SRPC (lower unemployment, higher inflation). As expectations adjust, the SRPC shifts up and the economy returns to the natural rate of unemployment but at a higher inflation rate. The natural rate is unchanged, and the boost to employment is only temporary.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 163, question: "Which scenario best illustrates STAGFLATION on a Phillips-curve diagram?", options: ["The economy moves up-left along a fixed SRPC due to higher aggregate demand","The SRPC shifts rightward (up) so that both inflation and unemployment increase simultaneously","The SRPC shifts leftward (down) so both inflation and unemployment fall","The LRPC shifts left, lowering the natural rate"], correctAnswer: 1, explanation: "Stagflation means simultaneously rising inflation and rising unemployment, which on the Phillips diagram is a rightward/upward shift of the SRPC caused by an adverse supply shock. A movement along the curve produces the usual inverse tradeoff (one rises while the other falls), and a leftward shift describes a favorable shock with disinflation and lower unemployment.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 164, question: "A negative supply shock raises the SRPC and pushes the economy to a point with 8% inflation and 7% unemployment, with the natural rate at 5%. If policymakers do NOTHING and let the economy self-correct, what is the long-run outcome?", options: ["Unemployment returns to 5% and the SRPC shifts back down, reversing the inflation increase","Unemployment stays at 7% permanently as the new natural rate","Inflation rises further while unemployment stays at 7%","The LRPC shifts right to 7% to match the new unemployment"], correctAnswer: 0, explanation: "If the supply shock is temporary, leaving the economy alone allows high unemployment to put downward pressure on wages and prices; expected inflation falls, the SRPC shifts back down, and unemployment returns to the natural rate of 5% with inflation back near its original level. The natural rate is structural and does not move to 7% in response to a transitory shock.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 165, question: "The natural rate of unemployment is sometimes called the 'non-accelerating inflation rate of unemployment' (NAIRU) because at that rate", options: ["Inflation is exactly zero","Unemployment is at its highest sustainable level","The money supply growth rate equals real GDP growth","Inflation tends to remain stable rather than continually rising or falling"], correctAnswer: 3, explanation: "At the NAIRU, actual unemployment equals the natural rate, so there is no upward or downward pressure on the inflation rate, which therefore tends to stay stable (constant). It does NOT imply zero inflation, the highest unemployment, or any particular money-growth identity. Inflation can be steady at any level when unemployment sits at the natural rate.", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 166, question: "If the actual unemployment rate persistently stays BELOW the NAIRU, the expectations-augmented Phillips curve predicts that inflation will", options: ["Hold steady at its current rate","Accelerate (continue rising) over time","Fall toward zero","Have no predictable trend"], correctAnswer: 1, explanation: "When unemployment is below the NAIRU, actual inflation exceeds expected inflation, which then raises expectations, shifting the SRPC up and pushing inflation higher again. The result is accelerating inflation as long as unemployment stays below the natural rate. Inflation only holds steady when unemployment equals the NAIRU.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 167, question: "A central bank wants to permanently reduce inflation from 8% to 3%. According to the accelerationist (vertical LRPC) view, the SHORT-RUN cost of this disinflation is", options: ["No cost, because the LRPC is vertical","A temporary rise in unemployment above the natural rate while expectations adjust downward","A permanent increase in the natural rate of unemployment","A permanent reduction in real GDP below potential"], correctAnswer: 1, explanation: "To lower inflation, the central bank reduces AD, which in the short run raises unemployment above the natural rate and lowers inflation (a movement down the SRPC). As expected inflation falls, the SRPC shifts down and unemployment eventually returns to the natural rate at the lower inflation, so the cost is a TEMPORARY rise in unemployment, not a permanent one.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 168, question: "The 'sacrifice ratio' associated with reducing inflation refers to", options: ["The percentage of one year's real GDP lost for each percentage-point reduction in inflation","The amount the money supply must grow to keep inflation constant","The natural rate of unemployment minus the actual unemployment rate","The ratio of nominal to real interest rates during a recession"], correctAnswer: 0, explanation: "The sacrifice ratio measures the cumulative percentage of annual real GDP that must be given up (through higher unemployment) to lower inflation by one percentage point. It quantifies the short-run cost of disinflation along the SRPC. The other options describe unrelated monetary or labor-market concepts.", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 169, question: "If inflation expectations are formed RATIONALLY and a disinflationary monetary policy is fully anticipated and credible, the rational-expectations view predicts that disinflation", options: ["Will require a deep and prolonged recession","Can occur with little or no increase in unemployment","Is impossible because the LRPC is vertical","Will permanently lower the natural rate of unemployment"], correctAnswer: 1, explanation: "Under rational expectations, if a credible disinflation is fully anticipated, workers and firms immediately lower their inflation expectations; the SRPC shifts down right away, so inflation falls with little or no rise in unemployment (a low or zero sacrifice ratio). The recession is large only when the policy is not credible or anticipated.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 170, question: "An economy is at the natural rate of unemployment of 5% with stable inflation at 2%. A large, sustained increase in consumer and investment spending occurs. In the short run, which point best describes the new position?", options: ["Unemployment above 5% and inflation below 2%","Unemployment below 5% and inflation above 2%","Unemployment at 5% and inflation at 2%","Unemployment above 5% and inflation above 2%"], correctAnswer: 1, explanation: "A surge in spending raises aggregate demand, moving the economy up and to the left along the SRPC: output rises above potential, unemployment falls below the natural rate of 5%, and inflation rises above 2%. Option four describes stagflation (a supply shock), and the first option describes a demand contraction.", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 171, question: "On a Phillips-curve diagram, the long-run equilibrium of an economy is always found", options: ["At the highest point of the short-run Phillips curve","At the point where the inflation rate equals zero","Wherever aggregate demand is largest","Wherever the short-run Phillips curve crosses the vertical long-run Phillips curve"], correctAnswer: 3, explanation: "Long-run equilibrium occurs where actual inflation equals expected inflation, which graphically is the intersection of the relevant SRPC with the vertical LRPC at the natural rate of unemployment. It is not defined by zero inflation or by the level of aggregate demand; many different SRPCs (for different expected inflation rates) can each cross the LRPC.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 172, question: "Country X has a natural rate of unemployment of 5%. Over a decade, generous and indefinite unemployment benefits and stronger union bargaining raise structural unemployment. On the Phillips-curve diagram, this is shown as", options: ["A movement up along the existing SRPC","A leftward shift of the LRPC and SRPC to a lower natural rate","A rightward shift of the LRPC and SRPC to a higher natural rate","A steepening of the SRPC with no change in the natural rate"], correctAnswer: 2, explanation: "Policies that raise structural unemployment increase the natural rate, shifting the vertical LRPC to the right; the SRPC shifts right with it because it must still intersect the LRPC at the new, higher natural rate. Generous benefits and stronger unions tend to RAISE, not lower, the natural rate, so a leftward shift is incorrect.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 173, question: "Which of the following would shift BOTH the long-run Phillips curve and the long-run aggregate supply curve to indicate economic growth and a lower natural rate of unemployment?", options: ["An increase in the price level","A permanent rise in the money supply growth rate","An increase in the economy's productivity and capital stock","A temporary increase in government spending"], correctAnswer: 2, explanation: "Increases in productivity, capital, technology, or labor-force quality expand potential output (LRAS shifts right) and can lower the natural rate of unemployment (LRPC shifts left). Price-level changes and money-growth changes affect inflation, not potential output, and a temporary spending increase shifts AD without changing long-run capacity.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 174, question: "An economy moves from point A (5% unemployment, 2% inflation) to point B (3% unemployment, 5% inflation) along an UNCHANGED short-run Phillips curve. The most likely cause is", options: ["An adverse supply shock","An increase in aggregate demand","A decrease in expected inflation","A leftward shift of the long-run aggregate supply curve"], correctAnswer: 1, explanation: "Because the movement is ALONG a fixed SRPC (lower unemployment with higher inflation), it must be driven by a change in aggregate demand, specifically an increase. Supply shocks and changes in expected inflation SHIFT the curve, and an LRAS shift changes potential output rather than producing a movement along the SRPC.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 175, question: "Suppose the relationship is actual inflation = expected inflation - 0.5(u - u*), with expected inflation = 4% and the natural rate u* = 6%. The central bank wants actual inflation of 5% in the short run. What unemployment rate is consistent with that target along the SRPC?", options: ["2%","4%","6%","8%"], correctAnswer: 1, explanation: "Set 5 = 4 - 0.5(u - 6). Then 5 - 4 = 1 = -0.5(u - 6), so (u - 6) = 1/(-0.5) = -2, giving u = 6 - 2 = 4%. Because the desired inflation (5%) exceeds expected inflation (4%), unemployment must be below the natural rate of 6%, which it is at 4%. The 8% answer wrongly adds 2 instead of subtracting, and 6% ignores the inflation gap entirely.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 176, question: "During a period of credible, gradual disinflation, the central bank lowers AD growth and the public steadily revises its inflation expectations downward. On the Phillips-curve diagram, the path of the economy is best described as", options: ["Moving up successive SRPCs to higher inflation and lower unemployment","Moving down a fixed SRPC and then back to the natural rate as the SRPC shifts down","Staying on the LRPC the entire time with falling inflation","Shifting the LRPC leftward repeatedly"], correctAnswer: 1, explanation: "Reduced AD growth first moves the economy down the current SRPC (lower inflation, temporarily higher unemployment). As expected inflation falls, the SRPC shifts down, returning unemployment to the natural rate at a lower inflation rate. This repeats until the target is reached. The LRPC stays fixed at the structural natural rate throughout.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 177, question: "A favorable supply shock, such as a sharp drop in energy prices, would most likely", options: ["Shift the SRPC down/left, allowing lower inflation and lower unemployment at the same time","Shift the SRPC up/right, raising both inflation and unemployment","Move the economy up along a fixed SRPC","Shift the LRPC to the right to a higher natural rate"], correctAnswer: 0, explanation: "A favorable (positive) supply shock lowers production costs, so for any unemployment rate inflation is lower; the SRPC shifts down/left, and the economy can enjoy lower inflation and lower unemployment simultaneously. This is the opposite of stagflation. A favorable supply shock does not raise the natural rate (the LRPC would shift LEFT if anything).", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 178, question: "Which statement correctly distinguishes the short-run and long-run Phillips curves?", options: ["Both curves are downward sloping, but the long-run one is steeper","The short-run curve is downward sloping because of fixed expectations, while the long-run curve is vertical because expectations fully adjust","The short-run curve is vertical and the long-run curve is downward sloping","Both curves are vertical, but at different unemployment rates"], correctAnswer: 1, explanation: "The SRPC slopes downward because, with inflation expectations temporarily fixed, unexpected inflation changes real wages and employment. In the long run, expectations adjust fully so inflation has no real effect, and the LRPC is vertical at the natural rate. The other options misassign which curve is vertical or wrongly make the LRPC sloped.", difficulty: "easy", topicSlug: "macro-phillips-curve" },
  { id: 179, question: "An economy is in a recession with actual unemployment of 8% and a natural rate of 5%. The government enacts a large stimulus that returns the economy to full employment without overshooting. On the Phillips-curve diagram, the economy", options: ["Moves up and to the left along the existing SRPC, from 8% toward 5% unemployment with somewhat higher inflation","Shifts the SRPC downward to a new natural rate of 8%","Moves down and to the right along the SRPC to higher unemployment","Shifts the LRPC leftward to 8%"], correctAnswer: 0, explanation: "Expansionary fiscal policy raises AD, moving the economy up and to the left along the existing SRPC: unemployment falls from 8% back toward the natural rate of 5%, and inflation rises modestly. Because the policy just closes the gap without overshooting, the economy lands at the natural rate without shifting the LRPC, which remains at 5%.", difficulty: "medium", topicSlug: "macro-phillips-curve" },
  { id: 180, question: "The table shows three years of data for an economy whose natural rate of unemployment is 5%:\nYear 1: unemployment 5%, inflation 2%.\nYear 2: unemployment 3%, inflation 6%.\nYear 3: unemployment 5%, inflation 6%.\nWhich sequence of events is most consistent with this data?", options: ["A favorable supply shock in Year 2 that permanently lowered unemployment","A leftward shift of the long-run Phillips curve between Years 1 and 3","An aggregate-demand expansion in Year 2 (movement up the SRPC), followed by rising inflation expectations that shifted the SRPC up and returned unemployment to 5% by Year 3","A permanent fall in the natural rate of unemployment to 3%"], correctAnswer: 2, explanation: "Year 1 to Year 2 shows lower unemployment with higher inflation, the classic movement UP an SRPC caused by an AD increase. Year 2 to Year 3 shows unemployment returning to the natural rate (5%) while inflation stays elevated at 6%, which is the self-correction: rising inflation expectations shift the SRPC up and the economy moves back to the natural rate at higher inflation. The natural rate did not permanently change, and a favorable supply shock would have LOWERED inflation, not raised it.", difficulty: "hard", topicSlug: "macro-phillips-curve" },
  { id: 181, question: "Using one unit of labor, Country X can produce either 12 bushels of wheat or 4 yards of cloth, while Country Y can produce either 6 bushels of wheat or 6 yards of cloth. Which statement is correct?", options: ["Country X has a comparative advantage in cloth and Country Y in wheat.","Country X has a comparative advantage in wheat and Country Y in cloth.","Country X has a comparative advantage in both goods.","Neither country can gain from trade because X is more productive overall."], correctAnswer: 1, explanation: "Comparative advantage is determined by opportunity cost. In Country X, producing 12 wheat costs 4 cloth, so 1 wheat costs 1/3 cloth and 1 cloth costs 3 wheat. In Country Y, 1 wheat costs 1 cloth and 1 cloth costs 1 wheat. X gives up less cloth per wheat (1/3 < 1), so X has the comparative advantage in wheat; Y gives up less wheat per cloth (1 < 3), so Y has the comparative advantage in cloth. Absolute advantage in both (X) does not eliminate gains from trade, and comparative advantage can never be held in both goods.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 182, question: "In Alpha, 1 worker-day produces 10 phones or 20 shirts. In Beta, 1 worker-day produces 3 phones or 12 shirts. For mutually beneficial trade in which Alpha exports phones, the price of 1 phone (in shirts) must fall within which range?", options: ["Less than 2 shirts per phone","Greater than 4 shirts per phone","Between 2 shirts and 4 shirts per phone","Between 0.5 shirts and 0.25 shirts per phone"], correctAnswer: 2, explanation: "The opportunity cost of 1 phone in Alpha is 20/10 = 2 shirts; in Beta it is 12/3 = 4 shirts. A mutually beneficial terms of trade lies strictly between the two domestic opportunity costs, so 1 phone must trade for between 2 and 4 shirts. Alpha (the low-cost phone producer, exporter) accepts more than 2 shirts; Beta will pay no more than its own cost of 4 shirts. The other ranges either invert the ratio or fall outside the bargaining range.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 183, question: "A small country opens to trade in steel, and the world price is below the country's previous domestic equilibrium price. Which of the following will occur?", options: ["The country becomes an exporter; producer surplus rises and consumer surplus falls.","Total surplus falls because cheaper foreign steel hurts the economy.","The country becomes an importer; both consumer and producer surplus fall.","The country becomes an importer; consumer surplus rises and producer surplus falls."], correctAnswer: 3, explanation: "When the world price is below the domestic no-trade price, domestic consumers want to buy more than domestic producers will supply at that lower price, so the country imports the difference. Consumers gain (they pay less and buy more), so consumer surplus rises; domestic producers sell less at a lower price, so producer surplus falls. The gain to consumers exceeds the loss to producers, so total surplus rises, not falls.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 184, question: "A country imposes a $5 per-unit tariff on imported sugar. The world price is $10 and domestic demand and supply are linear. Which welfare effect is NOT a consequence of the tariff?", options: ["Government collects tariff revenue on the units still imported.","Consumer surplus increases because consumers are protected from foreign competition.","Domestic producers gain producer surplus as the domestic price rises to $15.","There is a deadweight loss from both reduced consumption and inefficient domestic production."], correctAnswer: 1, explanation: "A tariff raises the domestic price from $10 to $15, so consumers pay more and buy less; consumer surplus FALLS, it does not increase. The other three statements are correct: producers gain as price rises to $15, the government collects $5 per imported unit, and two deadweight-loss triangles arise (one from the protected, higher-cost domestic production, one from the reduction in consumption). The question asks for the statement that is not a consequence, which is the false claim about rising consumer surplus.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 185, question: "A nation runs a current account deficit of $80 billion. Assuming the capital account is zero and official reserve transactions are negligible, what must be true of its financial account?", options: ["A financial account deficit of about $80 billion (net capital outflow).","A balanced financial account of $0.","A financial account surplus of about $80 billion (net capital inflow).","A financial account surplus equal to twice the current account deficit."], correctAnswer: 2, explanation: "The balance of payments must net to zero: current account + capital account + financial account = 0 (signs depend on convention, but the accounts offset). A current account deficit means the country is importing more than it exports and must be financed by net foreign investment flowing in, i.e., a financial account surplus of roughly equal magnitude (+$80 billion). It cannot be balanced or a deficit, and there is no doubling relationship.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 186, question: "Which of the following transactions is recorded as a CREDIT in the current account of the United States?", options: ["A U.S. company builds a new factory in Mexico.","A German firm purchases consulting services from a U.S. company.","A U.S. resident buys a car manufactured in Japan.","A U.S. pension fund purchases bonds issued by the British government."], correctAnswer: 1, explanation: "Exports of goods and services are credits in the current account. When a German firm buys U.S. consulting services, the U.S. is exporting a service, which is a current-account credit. Buying a Japanese car is a U.S. import (a current-account debit). Purchasing British bonds and building a factory in Mexico are outflows recorded in the financial account, not the current account.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 187, question: "The exchange rate moves from 1 U.S. dollar = 110 Japanese yen to 1 U.S. dollar = 125 Japanese yen. Which statement correctly describes this change?", options: ["The dollar depreciated and the yen appreciated.","Both currencies appreciated.","Neither currency changed in value, only the quote did.","The dollar appreciated and the yen depreciated."], correctAnswer: 3, explanation: "Each dollar now buys more yen (125 instead of 110), so the dollar appreciated. Equivalently, each yen now buys fewer dollars (1/125 instead of 1/110), so the yen depreciated. When one currency appreciates against another, the other must depreciate; they cannot both rise, and a change in the quoted rate by definition reflects a change in relative value.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 188, question: "Holding other factors constant, the U.S. Federal Reserve raises real interest rates relative to those in the rest of the world. In the foreign exchange market for dollars, what is the most likely immediate effect?", options: ["Supply of dollars increases, causing the dollar to depreciate.","Demand for dollars increases, causing the dollar to appreciate.","Demand for dollars decreases, causing the dollar to depreciate.","There is no effect on the dollar because interest rates affect only the bond market."], correctAnswer: 1, explanation: "Higher U.S. real interest rates make U.S. financial assets more attractive to foreign investors, who must buy dollars to invest. This increase in the demand for dollars in the foreign exchange market causes the dollar to appreciate. The interest-rate change works through capital flows into the forex market; it does not leave the dollar unaffected, and it raises (not lowers) the demand for dollars.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 189, question: "Suppose the U.S. dollar appreciates substantially against the currencies of its trading partners. Which combination of effects on U.S. trade is most likely?", options: ["U.S. exports become cheaper abroad and imports become more expensive, increasing net exports.","Both exports and imports become cheaper, leaving net exports unchanged.","U.S. exports become more expensive abroad and imports become cheaper, reducing net exports.","Net exports rise because a strong dollar signals a strong economy."], correctAnswer: 2, explanation: "A stronger dollar means foreigners need more of their currency to buy each dollar, so U.S. goods become more expensive abroad (exports fall). At the same time, each dollar buys more foreign currency, so imports become cheaper for Americans (imports rise). Both effects reduce net exports (X - M). Appreciation does not make exports cheaper, and the trade effect is real, not merely a sentiment signal.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 190, question: "An economy is operating at full employment. The government adopts policies that cause the domestic currency to depreciate sharply. In the short run, what is the most likely effect on aggregate demand and the price level?", options: ["Net exports fall, shifting AD left and lowering the price level.","Net exports rise, shifting AD right and raising the price level.","Aggregate demand is unaffected because trade is a small part of GDP.","Aggregate supply shifts left while aggregate demand stays fixed."], correctAnswer: 1, explanation: "A depreciation makes domestic exports cheaper for foreigners and imports more expensive for residents, so net exports rise. Since net exports are a component of aggregate demand, AD shifts to the right, and at or near full employment this raises the price level (inflationary pressure). The depreciation works through AD via net exports, not primarily through a leftward AS shift, and the trade channel is the relevant mechanism here.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 191, question: "A country with a floating exchange rate experiences a sudden increase in foreign demand for its exported goods. In the foreign exchange market for its currency, what happens?", options: ["Supply of the currency rises and the currency depreciates.","Demand for the currency falls and the currency depreciates.","Supply of the currency falls and the currency appreciates.","Demand for the currency rises and the currency appreciates."], correctAnswer: 3, explanation: "To buy the country's exports, foreigners must first acquire its currency, which increases the demand for that currency in the foreign exchange market. Higher demand, with supply unchanged, raises the exchange rate, i.e., the currency appreciates. The export surge raises demand for, not supply of, the home currency, so it cannot cause depreciation through a supply increase.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 192, question: "If the price level in Country A rises much faster than in its trading partners while exchange rates are flexible, what is the expected long-run effect on Country A's currency, all else equal?", options: ["Country A's currency tends to depreciate.","Country A's currency tends to appreciate.","The exchange rate is unaffected by inflation differentials.","Country A's currency appreciates only if interest rates also fall."], correctAnswer: 0, explanation: "Higher relative inflation makes Country A's goods more expensive, reducing foreign demand for its exports (lower demand for its currency) and increasing residents' demand for cheaper foreign goods (greater supply of its currency offered for foreign currency). Both forces push the currency to depreciate. This is consistent with purchasing power parity: the higher-inflation country's currency tends to lose value over time.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 193, question: "Country M produces only autos and wine. With all resources in autos it makes 100 autos; with all in wine it makes 50 barrels. Country N makes 60 autos or 60 barrels. If the two specialize according to comparative advantage, which pattern of specialization is efficient?", options: ["M specializes in wine; N specializes in autos.","Both specialize in autos.","M specializes in autos; N specializes in wine.","Both specialize in wine."], correctAnswer: 2, explanation: "In M, the opportunity cost of 1 auto is 50/100 = 0.5 barrels; in N it is 60/60 = 1 barrel. M sacrifices fewer barrels per auto (0.5 < 1), so M has the comparative advantage in autos. For wine, M's cost per barrel is 2 autos while N's is 1 auto, so N has the comparative advantage in wine. Efficient specialization is therefore M in autos and N in wine.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 194, question: "A government replaces a tariff with an import quota that allows exactly the same quantity of imports. Compared with the tariff, which is the most important difference under the quota?", options: ["Domestic prices fall below the world price under the quota.","The government no longer collects tariff revenue; the difference may accrue to license holders instead.","Consumer surplus is larger under the quota than under the tariff.","Deadweight loss disappears entirely under the quota."], correctAnswer: 1, explanation: "A quota that restricts imports to the same level as a tariff produces the same higher domestic price, the same reduced consumption, and the same deadweight loss. The key difference is that with a tariff the government collects revenue, while with a quota that 'rectangle' typically becomes quota rents captured by whoever holds the import licenses (often foreign exporters). Prices do not fall below the world price, consumer surplus is the same, and deadweight loss remains.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 195, question: "The data show a country's current account balance is -$120 billion and its capital account balance is +$5 billion. Ignoring measurement error and changes in official reserves, the financial account balance must be approximately:", options: ["-$115 billion","+$115 billion","+$125 billion","-$5 billion"], correctAnswer: 1, explanation: "The balance of payments sums to zero: current account + capital account + financial account = 0. So financial account = -(current account + capital account) = -(-120 + 5) = -(-115) = +$115 billion. A current account deficit must be financed by a net inflow of foreign capital, which is a financial account surplus, consistent with the positive sign.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 196, question: "A U.S. multinational repatriates $2 billion in profits earned by its factory located in Ireland. How is this recorded in the U.S. balance of payments?", options: ["A debit in the current account, as a payment to foreigners.","A credit in the financial account, as a sale of U.S. assets.","A credit in the current account, as primary (investment) income received from abroad.","A debit in the financial account, as a purchase of foreign assets."], correctAnswer: 2, explanation: "Income earned on foreign investments and received by domestic residents (primary income / investment income) is part of the current account. Because the income flows INTO the United States, it is a credit in the current account. It is not a payment to foreigners (debit), nor is the income itself a financial-account asset transaction—the original investment in the factory was the financial-account item; the returning profit is current-account income.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 197, question: "In the loanable funds market of an open economy, the domestic real interest rate falls below the world real interest rate. What is the expected effect on net capital flows and the exchange rate?", options: ["Capital flows in, increasing demand for domestic currency and causing appreciation.","Capital flows out, increasing the supply of domestic currency in forex and causing depreciation.","Capital flows out, raising demand for domestic currency and causing appreciation.","There is no capital movement because rates always equalize instantly."], correctAnswer: 1, explanation: "When the domestic real interest rate is below the world rate, investors seek higher returns abroad, so financial capital flows out. To invest abroad, domestic residents sell their currency to buy foreign currency, increasing the supply of the domestic currency in the foreign exchange market and causing it to depreciate. Lower domestic returns push capital out, not in, and the resulting currency sales cause depreciation, not appreciation.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 198, question: "A large economy runs a persistent government budget deficit, raising domestic real interest rates. According to the open-economy framework, what is the most likely effect on the trade balance (the 'twin deficits' idea)?", options: ["Higher rates cause capital outflows, the currency depreciates, and net exports rise.","The trade balance is unaffected because fiscal and trade policy are independent.","Net exports rise because government spending boosts domestic production for export.","Higher rates attract capital inflows, the currency appreciates, and net exports tend to fall."], correctAnswer: 3, explanation: "A budget deficit that raises real interest rates draws in foreign financial capital. Foreigners buying domestic assets must buy the domestic currency, causing it to appreciate. A stronger currency makes exports dearer and imports cheaper, reducing net exports. Thus a budget (government) deficit tends to accompany a trade deficit—the 'twin deficits.' The chain runs through higher rates, appreciation, and lower net exports, not the reverse.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 199, question: "One U.S. dollar exchanges for 0.80 euros. A machine made in Germany is priced at 4,000 euros. What is the price of the machine in U.S. dollars?", options: ["$3,200","$5,000","$4,000","$320"], correctAnswer: 1, explanation: "If $1 = 0.80 euros, then 1 euro = 1/0.80 = $1.25. The machine costs 4,000 euros, so in dollars it is 4,000 x $1.25 = $5,000. The distractor $3,200 wrongly multiplies 4,000 by 0.80; $4,000 ignores the conversion; and $320 misplaces a decimal. Converting from euros to dollars requires using the dollars-per-euro rate of $1.25.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 200, question: "Which of the following would most likely cause the demand curve for a country's currency in the foreign exchange market to shift to the right?", options: ["An increase in domestic residents traveling and spending abroad.","A decrease in foreign demand for the country's exports.","An increase in foreign tourists vacationing in the country.","A fall in the country's real interest rate relative to the rest of the world."], correctAnswer: 2, explanation: "Foreign tourists must buy the home currency to spend in the country, which increases demand for that currency and shifts the demand curve right. Domestic residents traveling abroad supply the home currency (a rightward supply shift), a decrease in foreign demand for exports shifts demand left, and a fall in the relative real interest rate reduces foreign investment demand for the currency (demand left). Only the inflow of foreign tourists raises currency demand.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 201, question: "A country shifts from a current account surplus to a current account deficit over several years, while its capital account stays near zero. Which change in the financial account is consistent with this shift?", options: ["The financial account moved from a deficit (net capital outflow) toward a surplus (net capital inflow).","The financial account moved from a surplus toward a deficit.","The financial account remained exactly balanced throughout.","The financial account doubled its surplus to offset both balances."], correctAnswer: 0, explanation: "Because the accounts must offset, a current account surplus is mirrored by a financial account deficit (the country is a net lender abroad), and a current account deficit is mirrored by a financial account surplus (the country becomes a net borrower / recipient of capital). Moving from current account surplus to deficit therefore corresponds to the financial account moving from deficit toward surplus. The accounts cannot both be balanced while the current account changes sign.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 202, question: "An economy in a deep recession allows its currency to depreciate. Which outcome best describes the likely short-run macroeconomic effect, assuming the Marshall-Lerner condition holds?", options: ["Net exports fall, aggregate demand decreases, and unemployment rises.","Net exports rise, aggregate demand increases, and real GDP and employment rise.","Aggregate supply shifts right, lowering the price level with no change in output.","There is no real effect because depreciation only changes nominal prices."], correctAnswer: 1, explanation: "Depreciation makes exports cheaper abroad and imports more expensive at home; when the Marshall-Lerner condition holds, net exports rise. Higher net exports increase aggregate demand, and because the economy is in recession with idle resources, real GDP and employment rise with relatively modest price-level pressure. The mechanism boosts AD through net exports rather than shifting AS or having a purely nominal effect.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 203, question: "Country P can produce 80 units of textiles or 40 units of electronics with its resources. It currently produces and consumes 40 textiles and 20 electronics. If the world relative price is 1 electronic = 1 textile and P specializes and trades, which result is possible that was NOT possible without trade?", options: ["Consuming 80 textiles and 40 electronics simultaneously.","Producing more than 80 textiles domestically.","Consuming 50 textiles and 30 electronics.","Eliminating all opportunity cost from production."], correctAnswer: 2, explanation: "Domestically, the opportunity cost of 1 electronic is 2 textiles (80 textiles vs. 40 electronics), so P should specialize in textiles (cheaper electronics cost abroad). Producing 80 textiles and trading some at 1:1 lets P reach consumption bundles outside its production possibilities frontier, such as 50 textiles and 30 electronics (give up 30 textiles for 30 electronics, leaving 50 and gaining 30). It still cannot consume the unattainable 80/40 corner, produce beyond its PPF, or abolish opportunity cost.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 204, question: "Which transaction would be recorded as a DEBIT in the U.S. financial account?", options: ["A Canadian investor purchases U.S. Treasury bonds.","A foreign tourist pays for a hotel stay in Florida.","A U.S. firm exports software to a customer in Brazil.","A U.S. investor buys shares of a corporation listed on the Tokyo Stock Exchange."], correctAnswer: 3, explanation: "Purchasing foreign assets is a capital outflow recorded as a debit in the financial account. When a U.S. investor buys Japanese shares, the U.S. acquires a foreign asset (financial-account debit). A Canadian buying U.S. Treasuries is a capital inflow (financial-account credit). Exporting software and a foreign tourist's hotel payment are exports of goods/services—current-account credits, not financial-account items.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 205, question: "The exchange rate is currently 1 British pound = 1.40 U.S. dollars. If the pound depreciates to 1 pound = 1.25 dollars, how does the dollar cost of a 200-pound hotel bill change for an American traveler?", options: ["It rises from $250 to $280.","It falls from $280 to $250.","It stays the same because the bill is still 200 pounds.","It falls from $280 to $160."], correctAnswer: 1, explanation: "At 1 pound = $1.40, a 200-pound bill costs 200 x 1.40 = $280. After the pound depreciates to $1.25, the same bill costs 200 x 1.25 = $250. The dollar cost falls from $280 to $250 because each pound is now cheaper for Americans. The bill is fixed in pounds, but its dollar cost changes with the exchange rate, so it does not stay the same.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 206, question: "A country maintains a fixed exchange rate that is set ABOVE the equilibrium value of its currency (the currency is overvalued / pegged too high). To defend this peg, the central bank must:", options: ["Sell its own currency to increase the supply at the pegged rate.","Allow the currency to float freely to the market rate.","Raise tariffs on all imports to balance the foreign exchange market.","Buy its own currency using foreign reserves to offset the excess supply."], correctAnswer: 3, explanation: "If the official rate is above equilibrium, the currency is overvalued, meaning there is a surplus of the home currency (quantity supplied exceeds quantity demanded) at that rate. To prevent the currency from falling to equilibrium, the central bank must purchase its own currency using its foreign-exchange reserves, removing the excess supply. Selling more of its own currency would worsen the surplus, and defending the peg means precisely not letting it float.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 207, question: "Foreign investors expect a country's currency to appreciate over the next year. Holding interest rates constant, what is the most likely immediate effect on the current exchange rate?", options: ["Supply of the currency rises now, causing it to depreciate immediately.","Demand for the currency rises now, causing it to appreciate immediately.","There is no effect until the appreciation actually occurs.","The currency depreciates now and then appreciates later."], correctAnswer: 1, explanation: "Expectations of future appreciation prompt investors to buy the currency now to profit from the anticipated rise. This increase in current demand pushes the exchange rate up immediately. Expectations are a determinant of currency demand, so the effect is not delayed until the future, and an expected appreciation raises rather than lowers current demand.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 208, question: "Worker-hours of output: in Country G, 1 hour makes 6 cars or 12 computers; in Country H, 1 hour makes 1 car or 4 computers. Which good should each country export, and what is the basis?", options: ["G exports computers and H exports cars, based on lower opportunity costs.","G exports both goods because it has absolute advantage in both.","G exports cars and H exports computers, based on lower opportunity costs.","H exports both goods because its labor is cheaper."], correctAnswer: 2, explanation: "In G, 1 car costs 12/6 = 2 computers; in H, 1 car costs 4/1 = 4 computers. G gives up fewer computers per car (2 < 4), so G has the comparative advantage in cars and should export them. For computers, G's cost is 0.5 cars and H's is 0.25 cars, so H has the comparative advantage in computers and should export them. Absolute advantage (G in both) does not determine the trade pattern; comparative advantage does.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 209, question: "Which of the following is the best example of intra-industry trade, and why does it occur despite similar comparative advantages?", options: ["Saudi Arabia exports oil to Japan while importing electronics, reflecting differing resource endowments.","Germany exports BMWs to France while importing Renaults from France, reflecting product differentiation and economies of scale.","A country imposes a tariff to protect an infant industry from foreign competition.","A nation devalues its currency to make all its exports cheaper abroad."], correctAnswer: 1, explanation: "Intra-industry trade is the two-way trade of similar but differentiated products within the same industry. Germany and France both have car industries, yet they trade cars in both directions because consumers value variety and firms benefit from economies of scale—this is intra-industry trade. The oil-for-electronics example is classic inter-industry trade driven by resource endowments, while tariffs and devaluation are trade policies, not examples of intra-industry trade.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 210, question: "A small open economy imports wheat at the world price of $4 per bushel. The government then grants a $1-per-bushel subsidy to domestic wheat producers (a production subsidy, not a tariff). Compared with a $1 tariff that raises the consumer price to $5, the subsidy:", options: ["Raises the consumer price to $5 just like the tariff.","Generates government revenue rather than a government expenditure.","Keeps the consumer price at $4 and avoids the consumption distortion, but still costs the government and overproduces.","Eliminates all deadweight loss because consumers are unaffected."], correctAnswer: 2, explanation: "A production subsidy lowers domestic producers' costs without raising the price consumers pay, so the consumer price stays at the world price of $4 and there is no reduction in consumption (no consumption-side distortion). However, the subsidy is a government expenditure and still encourages inefficient domestic overproduction, creating a production-side deadweight loss. Unlike a tariff, it does not raise the consumer price to $5 or generate revenue, but it does not eliminate all deadweight loss.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 211, question: "An increase in U.S. national income, with foreign incomes unchanged, is most likely to affect the foreign exchange market for dollars in which way?", options: ["Americans buy fewer imports, decreasing the supply of dollars and tending to appreciate the dollar.","Americans buy more imports, increasing the supply of dollars and tending to depreciate the dollar.","Foreigners buy more U.S. exports, increasing demand for dollars and appreciating the dollar.","There is no effect because income changes do not influence trade."], correctAnswer: 1, explanation: "When U.S. income rises, Americans purchase more goods, including imports. To pay for imports, Americans supply dollars to the foreign exchange market (to obtain foreign currency), increasing the supply of dollars and tending to depreciate the dollar. The change works through higher imports (more dollar supply), not lower imports, and a rise in domestic income does not directly raise foreign demand for U.S. exports.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 212, question: "A country's currency is appreciating because of strong capital inflows attracted by high domestic interest rates. Which group within the country is most likely to be harmed by this appreciation?", options: ["Domestic consumers of imported goods, who now pay more for imports.","Foreign investors holding the domestic currency, who lose value.","Domestic exporters, whose goods become more expensive for foreign buyers.","Domestic tourists traveling abroad, who can buy less foreign currency."], correctAnswer: 2, explanation: "When the home currency appreciates, the country's exports become more expensive in foreign markets, hurting domestic exporters by reducing foreign demand for their goods. Consumers of imports actually benefit (imports become cheaper), foreign holders of the appreciating currency gain value, and domestic tourists abroad gain purchasing power. The exporters are the clear losers from appreciation.", difficulty: "easy", topicSlug: "macro-international-trade-finance" },
  { id: 213, question: "Suppose purchasing power parity holds. A basket of goods costs 1,200 pesos in Mexico and $80 in the United States. According to PPP, what is the implied exchange rate?", options: ["1 dollar = 0.067 pesos","1 dollar = 15 pesos","1 peso = 15 dollars","1 dollar = 1,120 pesos"], correctAnswer: 1, explanation: "Purchasing power parity sets the exchange rate so the same basket costs the same in both currencies: 1,200 pesos = $80. Dividing, 1,200/80 = 15, so 1 dollar = 15 pesos. The distractor 0.067 pesos inverts the ratio, 1 peso = 15 dollars reverses the currencies, and 1,120 pesos subtracts rather than divides. The correct PPP rate is 15 pesos per dollar.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 214, question: "A country removes a long-standing tariff on imported automobiles. In the market for autos, which sequence of welfare changes occurs?", options: ["Consumer surplus falls, producer surplus rises, and total surplus declines.","Both consumer and producer surplus rise while deadweight loss increases.","There is no welfare change because the world price was unaffected.","Consumer surplus rises, producer surplus falls, government tariff revenue disappears, and deadweight loss is eliminated."], correctAnswer: 3, explanation: "Removing a tariff lowers the domestic price back to the world price. Consumers pay less and buy more, so consumer surplus rises; domestic producers sell less at a lower price, so producer surplus falls; the government loses the tariff revenue it had collected; and the two deadweight-loss triangles created by the tariff are eliminated, raising total surplus. The net effect is a gain in total welfare, not a decline.", difficulty: "medium", topicSlug: "macro-international-trade-finance" },
  { id: 215, question: "In the market for loanable funds of a small open economy that takes the world real interest rate as given, an increase in domestic private saving (with the world interest rate unchanged) will most likely:", options: ["Decrease net capital outflow and tend to appreciate the domestic currency.","Increase net capital outflow and tend to depreciate the domestic currency.","Raise the domestic interest rate above the world rate permanently.","Have no effect on capital flows because saving stays within the country."], correctAnswer: 1, explanation: "In a small open economy facing a fixed world interest rate, more domestic saving than domestic investment demands at that rate means the surplus funds flow abroad, increasing net capital outflow. To invest abroad, residents supply their currency in the forex market, tending to depreciate it. The domestic rate stays anchored to the world rate (it does not rise permanently above it), and the extra saving does flow internationally rather than staying entirely at home.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 216, question: "A nation's exports of goods equal $300 billion, imports of goods equal $360 billion, exports of services equal $90 billion, imports of services equal $50 billion, and net primary and secondary income received from abroad equals -$10 billion. What is the country's current account balance?", options: ["-$30 billion","-$60 billion","+$30 billion","-$120 billion"], correctAnswer: 0, explanation: "The current account combines the balance on goods, the balance on services, and net income. The goods balance is 300 - 360 = -$60 billion; the services balance is 90 - 50 = +$40 billion; net income is -$10 billion. Summing: -60 + 40 - 10 = -$30 billion. The distractor -$60 billion counts only goods, +$30 billion mishandles the income sign, and -$120 billion sums absolute values incorrectly. The current account balance is -$30 billion.", difficulty: "hard", topicSlug: "macro-international-trade-finance" },
  { id: 217, question: "In a closed economy with no taxes, households spend 80 cents of every additional dollar of disposable income. If government purchases rise by $50 billion, by how much will equilibrium real GDP change, holding other things constant?", options: ["$250 billion","$62.5 billion","$40 billion","$50 billion"], correctAnswer: 0, explanation: "MPC = 0.80, so MPS = 0.20 and the spending multiplier = 1/(1 - 0.80) = 1/0.20 = 5. Change in GDP = 5 x $50 billion = $250 billion. The $62.5 billion answer uses 1/0.80; $40 billion multiplies $50 by MPC (0.80); $50 billion ignores any multiplier effect.", difficulty: "easy", topicSlug: "macro-multiplier-effect" },
  { id: 218, question: "An economy has a marginal propensity to save of 0.25. The spending (expenditure) multiplier for this economy equals", options: ["1.33","4","0.25","0.75"], correctAnswer: 1, explanation: "The spending multiplier = 1/MPS = 1/0.25 = 4. The value 1.33 comes from 1/MPC = 1/0.75. The 0.25 is just the MPS itself, and 0.75 is the MPC; neither is the multiplier.", difficulty: "easy", topicSlug: "macro-multiplier-effect" },
  { id: 219, question: "A firm increases investment spending by $20 billion in an economy where the marginal propensity to consume is 0.75. Assuming no taxes or imports, the resulting increase in aggregate output is", options: ["$15 billion","$26.7 billion","$80 billion","$20 billion"], correctAnswer: 2, explanation: "Multiplier = 1/(1 - 0.75) = 1/0.25 = 4, so the change in output = 4 x $20 billion = $80 billion. The $15 billion answer multiplies $20 by MPC; $26.7 billion uses 1/0.75 = 1.33; $20 billion ignores the multiplier.", difficulty: "easy", topicSlug: "macro-multiplier-effect" },
  { id: 220, question: "The government cuts lump-sum taxes by $40 billion. The marginal propensity to consume is 0.80, and there are no imports. By how much does equilibrium real GDP increase?", options: ["$200 billion","$32 billion","$40 billion","$160 billion"], correctAnswer: 3, explanation: "The tax multiplier = -MPC/(1 - MPC) = -0.80/0.20 = -4. A tax CUT of $40 billion (change in T = -$40) raises GDP by (-4)(-$40) = +$160 billion. The $200 billion answer wrongly uses the spending multiplier of 5; $32 billion multiplies by MPC only; $40 billion ignores the multiplier.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 221, question: "An economy is in recession, $300 billion below full-employment output. The marginal propensity to consume is 0.90. What increase in government spending would, in theory, exactly close the recessionary gap?", options: ["$270 billion","$30 billion","$300 billion","$33.3 billion"], correctAnswer: 1, explanation: "Multiplier = 1/(1 - 0.90) = 1/0.10 = 10. Needed change in spending = gap / multiplier = $300 billion / 10 = $30 billion. The $270 billion answer multiplies the gap by MPC; $300 billion ignores the multiplier; $33.3 billion uses 1/0.90 = 1.11 instead of the correct multiplier of 10.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 222, question: "To close a recessionary gap of $300 billion when the MPC is 0.75, a government chooses to cut lump-sum taxes rather than raise spending. The required tax cut is", options: ["$75 billion","$225 billion","$100 billion","$300 billion"], correctAnswer: 2, explanation: "Tax multiplier = -MPC/(1 - MPC) = -0.75/0.25 = -3. To raise GDP by $300 billion: change in T = $300 / (-3) = -$100 billion, i.e., a $100 billion tax cut. The $75 billion answer would close the gap if the spending multiplier (4) applied; $225 billion misapplies MPC to the gap; $300 billion ignores the multiplier entirely.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 223, question: "A government simultaneously increases its purchases by $60 billion and raises lump-sum taxes by $60 billion, keeping the budget balanced. With an MPC of 0.80 and no imports, the net effect on equilibrium real GDP is approximately", options: ["$0 (the effects exactly cancel)","+$300 billion","-$240 billion","+$60 billion"], correctAnswer: 3, explanation: "Spending effect = 5 x $60 = +$300 billion; tax effect = (-4) x $60 = -$240 billion. Net = $300 - $240 = +$60 billion, illustrating the balanced-budget multiplier of 1 (output rises by the amount of the equal spending and tax change). The $0 answer wrongly assumes the two multipliers are equal in size; +$300 ignores the tax side; -$240 ignores the spending side.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 224, question: "The table shows successive rounds of new spending triggered by an initial $100 increase in autonomous investment. Round 1: $100; Round 2: $70; Round 3: $49; Round 4: $34.30... What is the marginal propensity to consume implied by this pattern, and the total change in GDP?", options: ["MPC = 0.70; total change about $333","MPC = 0.70; total change about $233","MPC = 0.30; total change about $143","MPC = 0.49; total change about $196"], correctAnswer: 0, explanation: "Each round is 0.70 of the previous ($70/$100 = 0.70, $49/$70 = 0.70), so MPC = 0.70. The multiplier = 1/(1 - 0.70) = 1/0.30 = 3.33, so total change = 3.33 x $100 = about $333. The $233 answer forgets to include the initial $100 (it sums only later rounds incorrectly); MPC = 0.30 confuses MPC with MPS; MPC = 0.49 mistakes round 3 for the ratio.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 225, question: "Holding income unchanged, which change would make the spending multiplier LARGER?", options: ["An increase in the marginal propensity to save","A decrease in the marginal propensity to save","An increase in the marginal propensity to import","An increase in the marginal income tax rate"], correctAnswer: 1, explanation: "The multiplier = 1/MPS, so a lower MPS (households save less and spend more of each extra dollar) raises the multiplier. Higher MPS shrinks it. Higher import propensity and higher tax rates are both leakages that reduce the multiplier, not enlarge it.", difficulty: "easy", topicSlug: "macro-multiplier-effect" },
  { id: 226, question: "In an open economy, of each additional dollar of income households save $0.10 and spend $0.20 on imported goods; the rest is spent domestically. There are no income taxes. The realistic (open-economy) multiplier is closest to", options: ["5.00","1.43","3.33","10.0"], correctAnswer: 2, explanation: "Total leakages per dollar = MPS + MPM = 0.10 + 0.20 = 0.30. Multiplier = 1/(MPS + MPM) = 1/0.30 = 3.33. The 5.00 answer uses only MPS (1/0.20, treating spending as 0.80 domestically); 10.0 uses only MPS = 0.10; 1.43 inverts MPC = 0.70 instead of the leakage sum.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 227, question: "Two economies are identical except that Economy A has MPC = 0.90 and Economy B has MPC = 0.60. The same $10 billion increase in government spending occurs in each. Compared with Economy B, the increase in GDP in Economy A is", options: ["Smaller, because a higher MPC means more leakage","The same, because the initial spending is identical","Larger, because A has a higher MPS","Larger, because A has a higher MPC and thus a larger multiplier"], correctAnswer: 3, explanation: "A higher MPC means a smaller MPS and a larger multiplier (A: 1/0.10 = 10 gives $100B; B: 1/0.40 = 2.5 gives $25B). A higher MPC means LESS leakage to saving, not more, and A has a LOWER MPS, so the other options reflect common reversals of the relationship.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 228, question: "An economy's consumption function is C = 200 + 0.75(Y - T). Investment, government spending, and taxes are autonomous. If autonomous investment rises by $50 billion, equilibrium income rises by", options: ["$200 billion","$37.5 billion","$66.7 billion","$50 billion"], correctAnswer: 0, explanation: "The slope of the consumption function with respect to Y is the MPC = 0.75, so the multiplier = 1/(1 - 0.75) = 4. Change in Y = 4 x $50 billion = $200 billion. The $37.5 billion answer multiplies by MPC; $66.7 billion uses 1/0.75; $50 billion ignores the multiplier.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 229, question: "A country with MPC = 0.80 is at full employment. The central government raises spending by $25 billion with no offsetting tax change. Ignoring crowding out and price-level effects, the simple model predicts a change in nominal output of", options: ["$20 billion","$125 billion","$31.25 billion","$25 billion"], correctAnswer: 1, explanation: "Multiplier = 1/(1 - 0.80) = 5, so change in output = 5 x $25 billion = $125 billion. The $20 billion answer multiplies by MPC; $31.25 billion uses 1/0.80; $25 billion ignores the multiplier. (In reality, at full employment this mostly raises the price level, but the question asks for the simple-model prediction.)", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 230, question: "Suppose the spending multiplier in an economy is 2.5. What is the marginal propensity to consume?", options: ["0.40","0.25","0.60","0.75"], correctAnswer: 2, explanation: "Multiplier = 1/(1 - MPC) = 2.5, so 1 - MPC = 1/2.5 = 0.40, giving MPC = 0.60. The 0.40 answer is actually the MPS; 0.25 and 0.75 do not satisfy 1/(1 - MPC) = 2.5 (they would give multipliers of 1.33 and 4, respectively).", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 231, question: "A government wants to RAISE equilibrium GDP by $90 billion using a change in lump-sum taxes alone. The MPC is 0.75. What tax change is required?", options: ["A tax increase of $30 billion","A tax cut of $22.5 billion","A tax cut of $90 billion","A tax cut of $30 billion"], correctAnswer: 3, explanation: "Tax multiplier = -MPC/(1 - MPC) = -0.75/0.25 = -3. To raise GDP by $90 billion: change in T = $90 / (-3) = -$30 billion, a tax CUT of $30 billion. A tax INCREASE would lower GDP. The $22.5 billion answer applies MPC to the gap incorrectly; $90 billion ignores the multiplier.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 232, question: "Which of the following best explains WHY an initial increase in autonomous spending produces a larger ultimate change in GDP?", options: ["One person's spending becomes another person's income, part of which is spent again, repeating in successive rounds","Prices rise proportionally with every dollar of new spending","The government automatically matches all private spending dollar for dollar","Banks are required to lend out all new deposits immediately"], correctAnswer: 0, explanation: "The multiplier arises because spending creates income, a fraction of which (the MPC) is re-spent, becoming income again in the next round, and so on. The other choices describe price effects, fiscal matching, and the banking money multiplier, none of which is the mechanism behind the expenditure multiplier.", difficulty: "easy", topicSlug: "macro-multiplier-effect" },
  { id: 233, question: "An economy has a marginal propensity to consume of 0.75 and a proportional income tax rate of 0.20. The realistic spending multiplier (accounting for the tax leakage) is closest to", options: ["4.0","2.5","1.33","5.0"], correctAnswer: 1, explanation: "With a proportional tax, multiplier = 1/(1 - MPC(1 - t)) = 1/(1 - 0.75 x 0.80) = 1/(1 - 0.60) = 1/0.40 = 2.5. The 4.0 answer ignores the tax and uses 1/(1 - 0.75); 1.33 inverts MPC; 5.0 uses an MPC of 0.80 with no tax. The income tax acts as a leakage that lowers the multiplier from 4 to 2.5.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 234, question: "If the marginal propensity to consume rises from 0.75 to 0.80, the spending multiplier changes from", options: ["5 to 4","4 to 4.5","4 to 5","3 to 4"], correctAnswer: 2, explanation: "At MPC = 0.75, multiplier = 1/0.25 = 4. At MPC = 0.80, multiplier = 1/0.20 = 5. So it rises from 4 to 5. The '5 to 4' answer reverses the direction; the other options miscompute one or both multipliers.", difficulty: "easy", topicSlug: "macro-multiplier-effect" },
  { id: 235, question: "An economy has an MPC of 0.80 and a recessionary gap of $500 billion. A senator proposes a $125 billion increase in government purchases. Compared with what is needed to close the gap, this proposal is", options: ["Exactly the right size","Too small; $625 billion is required","Too small; $500 billion is required","Larger than needed; only $100 billion is required"], correctAnswer: 3, explanation: "Multiplier = 1/(1 - 0.80) = 5. Required spending = $500 billion / 5 = $100 billion. The $125 billion proposal exceeds this, so it would overshoot the gap. The '$625 billion' and '$500 billion' answers multiply or equate the gap to spending incorrectly rather than dividing by the multiplier.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 236, question: "Consider the tax multiplier and the spending multiplier for the same economy with MPC = 0.80. Which statement is correct?", options: ["The spending multiplier (5) is larger in absolute value than the tax multiplier (-4)","The tax multiplier (-5) is larger in absolute value than the spending multiplier (4)","Both multipliers equal 5 in absolute value","The tax multiplier is positive and larger than the spending multiplier"], correctAnswer: 0, explanation: "Spending multiplier = 1/(1 - 0.80) = 5; tax multiplier = -0.80/0.20 = -4. The spending multiplier is larger in magnitude because the first dollar of government spending enters the income stream fully, whereas a tax cut first passes through the MPC. The tax multiplier is negative, not positive, and the two are not equal.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 237, question: "A $200 billion increase in exports occurs in an economy where households save 20 percent and import 10 percent of each additional dollar of income, with no income taxes. The change in equilibrium GDP is closest to", options: ["$1,000 billion","$667 billion","$286 billion","$200 billion"], correctAnswer: 1, explanation: "Leakages = MPS + MPM = 0.20 + 0.10 = 0.30, so multiplier = 1/0.30 = 3.33. Change in GDP = 3.33 x $200 billion = about $667 billion. The $1,000 billion answer uses only MPS = 0.20 (multiplier 5); $286 billion uses 1/0.70; $200 billion ignores the multiplier.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 238, question: "An initial $80 million increase in spending generates a total increase in GDP of $400 million. What is the value of the marginal propensity to save?", options: ["0.80","0.25","0.20","0.05"], correctAnswer: 2, explanation: "Multiplier = total change / initial change = $400/$80 = 5. Since multiplier = 1/MPS, MPS = 1/5 = 0.20. The 0.80 answer is the MPC; 0.25 would correspond to a multiplier of 4; 0.05 misreads the ratio.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 239, question: "Which scenario would produce the SMALLEST multiplier effect on GDP from a given increase in autonomous spending?", options: ["A low marginal propensity to save and no taxes","A high marginal propensity to consume and no imports","A low income tax rate and a low import propensity","A high marginal propensity to import and a high income tax rate"], correctAnswer: 3, explanation: "Leakages (saving, taxes, imports) shrink the multiplier. The combination of high import propensity and high tax rate maximizes leakages, producing the smallest multiplier. Low MPS, high MPC, and low taxes/imports all reduce leakages and therefore enlarge the multiplier.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 240, question: "A consumer's autonomous consumption is $300 and MPC is 0.6. If the economy is closed with lump-sum taxes, and government spending falls by $45 billion, what happens to equilibrium GDP?", options: ["It falls by $112.5 billion","It falls by $27 billion","It rises by $112.5 billion","It falls by $45 billion"], correctAnswer: 0, explanation: "Multiplier = 1/(1 - 0.6) = 1/0.4 = 2.5. A spending DECREASE of $45 billion lowers GDP by 2.5 x $45 = $112.5 billion. The autonomous consumption figure ($300) is irrelevant to the change. The $27 billion answer multiplies by MPC; the 'rises' answer gets the sign wrong; $45 billion ignores the multiplier.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 241, question: "During a downturn, the government increases unemployment-benefit transfer payments by $50 billion. With an MPC of 0.80, the predicted change in GDP is", options: ["$250 billion","$200 billion","$40 billion","$50 billion"], correctAnswer: 1, explanation: "Transfer payments work like a negative tax: their multiplier equals the tax multiplier in magnitude, MPC/(1 - MPC) = 0.80/0.20 = 4. Change in GDP = 4 x $50 billion = $200 billion. The $250 billion answer wrongly uses the spending multiplier of 5 (transfers do not enter spending directly; recipients spend only the MPC fraction first); $40 billion multiplies by MPC only; $50 billion ignores the multiplier.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 242, question: "An economy is operating $160 billion above its full-employment level (an inflationary gap). With MPC = 0.75, the government wishes to eliminate the gap by reducing its purchases. The required reduction in government spending is", options: ["$160 billion","$120 billion","$40 billion","$53.3 billion"], correctAnswer: 2, explanation: "Multiplier = 1/(1 - 0.75) = 4. Required change in spending = gap / multiplier = $160 / 4 = $40 billion reduction. The $160 billion answer ignores the multiplier; $120 billion multiplies the gap by MPC; $53.3 billion uses 1/0.75 instead of 4.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 243, question: "Country X has MPC = 0.6 and Country Y has MPC = 0.8. Both receive an identical $100 billion stimulus in government spending. The DIFFERENCE in the resulting GDP changes (Y minus X) is", options: ["$150 billion","$200 billion","$500 billion","$250 billion"], correctAnswer: 3, explanation: "Country X multiplier = 1/0.4 = 2.5, giving $250 billion. Country Y multiplier = 1/0.2 = 5, giving $500 billion. Difference = $500 - $250 = $250 billion. The $150 billion answer subtracts multipliers (5 - 2.5 = 2.5) but then misapplies; $200 billion and $500 billion ignore the subtraction or use only Country Y's total.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 244, question: "If a tax cut of $50 billion and an equal increase in government spending of $50 billion both occur, but the MPC differs, the balanced-budget multiplier predicts the net effect on GDP equals", options: ["$50 billion, regardless of the MPC","$0, because the budget is balanced","$250 billion if MPC = 0.8","It cannot be determined without the MPC"], correctAnswer: 0, explanation: "The balanced-budget multiplier is exactly 1 for any MPC: spending multiplier minus tax multiplier magnitude = 1/(1-MPC) - MPC/(1-MPC) = (1-MPC)/(1-MPC) = 1. So equal spending and tax increases of $50 billion raise GDP by $50 billion regardless of the MPC. A balanced budget does not mean zero effect, and the result does not depend on the MPC.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 245, question: "An economist observes that a $30 billion increase in investment ultimately raised GDP by $90 billion. Based on this, the marginal propensity to consume is", options: ["0.333","0.667","0.90","3.0"], correctAnswer: 1, explanation: "Multiplier = $90/$30 = 3. Since 1/(1 - MPC) = 3, then 1 - MPC = 1/3, so MPC = 2/3 = 0.667. The 0.333 answer is the MPS; 0.90 is unrelated; 3.0 is the multiplier itself, not the MPC.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 246, question: "In a simple Keynesian model with no taxes or trade, autonomous spending totals $500 billion and the MPC is 0.8. Equilibrium GDP is", options: ["$625 billion","$400 billion","$2,500 billion","$500 billion"], correctAnswer: 2, explanation: "Equilibrium GDP = autonomous spending x multiplier = $500 billion x [1/(1 - 0.8)] = $500 x 5 = $2,500 billion. The $625 billion answer uses 1/0.8; $400 billion multiplies by MPC; $500 billion ignores the multiplier. The multiplier scales total autonomous spending into equilibrium output here.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 247, question: "A policymaker notes that adding a marginal propensity to import to the model makes fiscal stimulus 'less powerful.' This is because imports", options: ["Increase domestic consumption in each round, raising the multiplier","Have no effect on the multiplier in any model","Reduce the marginal propensity to save dollar for dollar","Are a leakage that reduces the fraction of each dollar re-spent domestically, lowering the multiplier"], correctAnswer: 3, explanation: "Spending on imports leaks out of the domestic income stream, so less is re-spent at home in each round; this shrinks the multiplier (1/(MPS + MPM) is smaller than 1/MPS). Imports do not raise domestic consumption rounds, they are not neutral in an open-economy model, and they are distinct from saving.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 248, question: "Government spending rises by $40 billion while, at the same time, lump-sum taxes are cut by $40 billion. With MPC = 0.75, the combined effect on equilibrium GDP is", options: ["$280 billion","$40 billion","$160 billion","$120 billion"], correctAnswer: 0, explanation: "Spending effect = 4 x $40 = $160 billion. Tax cut effect = (tax multiplier -3) x (-$40) = +$120 billion. Combined = $160 + $120 = $280 billion. Note this is NOT a balanced-budget case (taxes are cut while spending rises, widening the deficit), so the effect exceeds $40 billion. The $40 billion answer wrongly applies the balanced-budget multiplier; $160 and $120 use only one channel.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 249, question: "A simple model has MPC = 0.9. A natural disaster destroys $20 billion of autonomous investment spending. The fall in equilibrium GDP, all else equal, is", options: ["$18 billion","$200 billion","$22.2 billion","$20 billion"], correctAnswer: 1, explanation: "Multiplier = 1/(1 - 0.9) = 10. A $20 billion drop in autonomous spending lowers GDP by 10 x $20 = $200 billion. The $18 billion answer multiplies by MPC; $22.2 billion uses 1/0.9; $20 billion ignores the multiplier. The high MPC makes the contraction large.", difficulty: "medium", topicSlug: "macro-multiplier-effect" },
  { id: 250, question: "Which combination would give a spending multiplier of exactly 2?", options: ["MPC = 0.8 (and MPS = 0.2)","MPC = 0.2 (and MPS = 0.8)","MPC = 0.5 (and MPS = 0.5)","MPC = 0.75 (and MPS = 0.25)"], correctAnswer: 2, explanation: "Multiplier = 1/MPS = 2 requires MPS = 0.5, i.e., MPC = 0.5. MPS = 0.2 gives a multiplier of 5, MPS = 0.8 gives 1.25, and MPS = 0.25 gives 4. Only MPC = 0.5 yields a multiplier of 2.", difficulty: "easy", topicSlug: "macro-multiplier-effect" },
  { id: 251, question: "An economy with MPC = 0.80 receives a $100 billion increase in government purchases. Of the eventual $500 billion total increase in GDP, how much comes from the multiplier (induced) rounds of spending BEYOND the initial $100 billion injection?", options: ["$500 billion","$80 billion","$320 billion","$400 billion"], correctAnswer: 3, explanation: "Multiplier = 5, so total change = 5 x $100 = $500 billion. The initial injection is $100 billion, so the induced (later-round) spending accounts for $500 - $100 = $400 billion. The $500 billion answer includes the initial injection; $80 billion is just the first induced round; $320 billion misallocates the rounds.", difficulty: "hard", topicSlug: "macro-multiplier-effect" },
  { id: 252, question: "A country produces only two final goods. In a given year it makes 200 loaves of bread that sell for $2 each and 50 bicycles that sell for $120 each. Using the value-of-final-goods approach, what is this country's nominal GDP for the year?", options: ["$6,400","$400","$6,000","$24,400"], correctAnswer: 0, explanation: "GDP equals the market value of all final goods produced: (200 × $2) + (50 × $120) = $400 + $6,000 = $6,400. The distractor $400 counts only bread, $6,000 counts only bicycles, and $24,400 incorrectly multiplies the two quantities together rather than valuing each good at its own price.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 253, question: "An automaker buys $8,000 of steel from a domestic steel mill and uses it to build a car that it sells to a consumer for $25,000. The steel mill purchased $3,000 of iron ore to make that steel. To avoid double counting, how much do these transactions add to GDP?", options: ["$36,000","$25,000","$33,000","$8,000"], correctAnswer: 1, explanation: "Only the value of the final good (the car) is counted, which is $25,000; the steel and iron ore are intermediate goods whose value is already embedded in the car's price. Equivalently, summing value added — $3,000 (ore) + $5,000 (mill's added value) + $17,000 (automaker's added value) — also equals $25,000. The $36,000 and $33,000 figures double-count intermediate stages.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 254, question: "In the expenditure approach, GDP = C + I + G + (X − M). Given consumption $11,000, gross private investment $2,500, government purchases $3,000, exports $1,200, and imports $1,800, what is GDP?", options: ["$16,300","$19,500","$15,900","$17,700"], correctAnswer: 2, explanation: "Net exports = X − M = $1,200 − $1,800 = −$600. GDP = 11,000 + 2,500 + 3,000 + (−600) = $15,900. The $19,500 distractor wrongly adds both exports and imports as positives ignoring the subtraction; $16,300 adds the full $1,200 and forgets imports; $17,700 mishandles the net export sign.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 255, question: "Which of the following transactions WOULD be directly counted in current-year U.S. GDP?", options: ["The government sends a $1,500 Social Security check to a retiree","A family buys a 10-year-old used car from a neighbor for $4,000","An investor buys 100 shares of an existing company's stock for $5,000","A barber cuts a customer's hair for $30 this year"], correctAnswer: 3, explanation: "The haircut is a newly produced service this year, so it counts in GDP. A used car was counted when first produced and is not new output. Buying existing stock is a transfer of financial asset ownership, not production. Social Security is a transfer payment with no corresponding current production. These exclusions are core to what GDP measures.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 256, question: "Nominal GDP in 2015 was $800 billion and the GDP deflator (base year 2010, index = 100) was 125. What was real GDP in 2015 expressed in 2010 dollars?", options: ["$640 billion","$1,000 billion","$675 billion","$925 billion"], correctAnswer: 0, explanation: "Real GDP = (Nominal GDP / GDP deflator) × 100 = (800 / 125) × 100 = $640 billion. The $1,000 billion distractor multiplies instead of divides; $675 and $925 come from incorrectly subtracting or adding 25% of nominal GDP rather than dividing by the index.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 257, question: "An economy produces the same physical quantity of goods in 2020 and 2021, but every price rises by 10%. What happens to nominal GDP and real GDP from 2020 to 2021?", options: ["Both nominal and real GDP rise 10%","Nominal GDP rises 10%; real GDP is unchanged","Nominal GDP is unchanged; real GDP rises 10%","Both nominal and real GDP are unchanged"], correctAnswer: 1, explanation: "Nominal GDP uses current prices, so a 10% price increase with unchanged output raises nominal GDP by 10%. Real GDP holds prices constant at a base year, so with identical physical output it does not change. Mistaking nominal increases for real growth is a classic error this question targets.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 258, question: "Real GDP was $18.0 trillion in Year 1 and $18.54 trillion in Year 2. What was the real GDP growth rate from Year 1 to Year 2?", options: ["5.4%","0.54%","3.0%","1.03%"], correctAnswer: 2, explanation: "Growth rate = (New − Old) / Old × 100 = (18.54 − 18.0) / 18.0 × 100 = 0.54 / 18.0 × 100 = 3.0%. The 0.54% and 5.4% distractors misplace the decimal or use the raw change; 1.03% mistakenly reports the ratio 18.54/18.0 minus an arithmetic slip.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 259, question: "Using the Rule of 70, approximately how many years will it take a country's real GDP to double if it grows at a constant 3.5% per year?", options: ["70 years","35 years","10 years","20 years"], correctAnswer: 3, explanation: "The Rule of 70 estimates doubling time as 70 divided by the annual percentage growth rate: 70 / 3.5 = 20 years. The distractor 35 divides 70 by 2, 10 divides by 7, and 70 ignores the rule entirely. The rule provides a quick approximation for exponential growth.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 260, question: "A nation's real GDP grows by 2% in a year while its population grows by 3% in the same year. What happens to real GDP per capita?", options: ["It falls by approximately 1%","It rises by approximately 1%","It rises by approximately 5%","It stays exactly constant"], correctAnswer: 0, explanation: "Real GDP per capita growth ≈ real GDP growth − population growth = 2% − 3% = −1%, so per-capita output falls about 1%. When population outpaces output, average living standards decline even though total output rose. The +1% and +5% distractors mishandle the sign or add the rates.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 261, question: "Which of the following is the BEST single indicator of a country's average material standard of living over time?", options: ["Nominal GDP","Real GDP per capita","Total real GDP","The GDP deflator"], correctAnswer: 1, explanation: "Real GDP per capita adjusts for both inflation (using 'real') and population size (using 'per capita'), making it the standard proxy for average living standards. Nominal GDP is distorted by price changes, total real GDP ignores population differences, and the GDP deflator measures the price level, not output per person.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 262, question: "An economy's GDP deflator was 120 in Year 1 and 126 in Year 2. What was the inflation rate, as measured by the deflator, between the two years?", options: ["4.76%","6%","5%","1.05%"], correctAnswer: 2, explanation: "Inflation rate = (New deflator − Old deflator) / Old deflator × 100 = (126 − 120) / 120 × 100 = 6/120 × 100 = 5%. The distractor 6% uses the raw point change as a percent; 4.76% divides by the new value instead of the old; 1.05% reports the index ratio without converting to a rate.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 263, question: "A simple economy produces only apples and books. In the base year, 100 apples at $1 and 20 books at $10. In the current year, it produces 120 apples and 25 books, and current prices are $1.50 per apple and $12 per book. What is current-year REAL GDP (valued at base-year prices)?", options: ["$430","$480","$300","$370"], correctAnswer: 3, explanation: "Real GDP uses current quantities at base-year prices: (120 × $1) + (25 × $10) = $120 + $250 = $370. The $480 figure uses current prices (nominal GDP), $300 is base-year GDP, and $430 mixes one base price with one current price. Real GDP isolates output changes by holding prices fixed.", difficulty: "hard", topicSlug: "macro-gdp-growth" },
  { id: 264, question: "Using the same economy — base year 100 apples at $1 and 20 books at $10; current year 120 apples and 25 books at current prices $1.50 and $12 — what is the GDP deflator for the current year?", options: ["Approximately 129.7","Approximately 100.0","Approximately 77.1","Approximately 160.0"], correctAnswer: 0, explanation: "Nominal GDP = (120 × 1.50) + (25 × 12) = 180 + 300 = $480. Real GDP (base prices) = $370. Deflator = (Nominal / Real) × 100 = (480 / 370) × 100 ≈ 129.7. The 100 distractor assumes no price change, 77.1 inverts the ratio, and 160 mishandles the quantity-price combination.", difficulty: "hard", topicSlug: "macro-gdp-growth" },
  { id: 265, question: "Which scenario would cause MEASURED GDP to understate the true level of economic activity?", options: ["Firms increase production of final goods sold in formal markets","A growing share of transactions occurs in the unreported underground economy","The government raises spending on new infrastructure projects","Households shift from home cooking to buying restaurant meals"], correctAnswer: 1, explanation: "Underground (off-the-books) transactions represent real production that official statistics miss, so a larger underground economy makes measured GDP understate true activity. The other choices involve market transactions that ARE captured; the shift to restaurant meals actually moves previously unmeasured home production into measured GDP, raising rather than lowering the measured figure.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 266, question: "Which of the following, if it increased, would tend to raise an economy's long-run rate of economic growth by increasing labor productivity?", options: ["A rise in current-period consumption spending financed by borrowing","An increase in the consumer price index","Investment in workers' education and training (human capital)","An increase in transfer payments to retirees"], correctAnswer: 2, explanation: "Human capital investment raises output per worker, shifting the economy's productive capacity outward and increasing long-run growth. A rising CPI is inflation, not growth. Borrowing for current consumption does not expand productive capacity, and transfer payments redistribute income without directly increasing output per worker.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 267, question: "On a production possibilities curve (PPC) diagram for capital goods versus consumer goods, which change BEST represents long-run economic growth?", options: ["An inward shift of the entire PPC","A movement from a point inside the PPC to a point on the PPC","A movement along the PPC from one point to another","An outward shift of the entire PPC"], correctAnswer: 3, explanation: "Economic growth means an expansion of an economy's productive capacity, shown as an outward shift of the whole PPC. Moving from inside to the frontier reflects reducing unemployment of existing resources (using current capacity more fully), and movement along the curve is reallocation, not growth. An inward shift represents shrinking capacity.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 268, question: "In the aggregate demand–aggregate supply model, long-run economic growth is best represented by which of the following?", options: ["A rightward shift of the long-run aggregate supply (LRAS) curve","A rightward shift of the aggregate demand (AD) curve only","A movement up along a fixed short-run aggregate supply curve","A leftward shift of the short-run aggregate supply curve"], correctAnswer: 0, explanation: "LRAS reflects the economy's full-employment level of output (potential output). Sustained economic growth — more resources, capital, or productivity — shifts LRAS rightward. An AD shift changes output only in the short run and primarily raises the price level in the long run, while SRAS shifts do not represent a permanent increase in productive capacity.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 269, question: "A country's real GDP grows at 2% per year and its population grows at 0% (constant population). Using the Rule of 70, in approximately how many years will the average standard of living (real GDP per capita) double?", options: ["70 years","35 years","20 years","14 years"], correctAnswer: 1, explanation: "With zero population growth, real GDP per capita grows at the same 2% rate as real GDP. Rule of 70 doubling time = 70 / 2 = 35 years. The 70-year distractor divides by 1, 20 divides by 3.5, and 14 divides by 5; all misidentify the per-capita growth rate.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 270, question: "Country A has real GDP per capita of $40,000 growing at 1% per year. Country B has real GDP per capita of $10,000 growing at 5% per year. Holding these rates constant, which statement is most accurate about the long-run gap between them?", options: ["The two will reach the same level within exactly four years","Country A will always remain richer because it started with a higher level","Country B's living standard will eventually catch up to and surpass Country A's because of its faster growth rate","Country B can never catch up because absolute dollar gaps only widen"], correctAnswer: 2, explanation: "Compound growth means a higher growth rate eventually overtakes a higher starting level: B doubles roughly every 14 years (70/5) while A doubles every 70 years (70/1), so B closes and surpasses the gap over time. The claim that A 'always' stays ahead ignores compounding; the four-year and 'never' claims contradict exponential growth dynamics.", difficulty: "hard", topicSlug: "macro-gdp-growth" },
  { id: 271, question: "Gross domestic product measures output produced within a country's borders, while gross national product measures output produced by a country's residents. A car factory in Country X is owned by a firm based in Country Y. The factory's output is counted in:", options: ["Neither country's GDP because of foreign ownership","Country Y's GDP and Country X's GNP","Both countries' GDP equally","Country X's GDP and Country Y's GNP"], correctAnswer: 3, explanation: "GDP is location-based, so production inside Country X counts in Country X's GDP. GNP is ownership/residency-based, so output earned by Country Y's residents (the owning firm) counts in Country Y's GNP. The distractors confuse the location versus ownership criteria that distinguish GDP from GNP.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 272, question: "An economy is producing at a point inside its production possibilities curve. Which best explains this situation, and is it the same as economic growth?", options: ["Resources are unemployed or underused; reaching the frontier is a recovery toward potential, not economic growth","The economy is growing because it can still produce more","The PPC has shifted inward, which is the definition of growth","It is impossible to produce inside the PPC"], correctAnswer: 0, explanation: "A point inside the PPC indicates inefficient use of existing resources (e.g., cyclical unemployment). Moving to the frontier uses current capacity more fully — a recovery — but does not expand capacity, so it is not long-run economic growth. Growth requires an outward shift of the curve itself, not merely producing more within existing limits.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 273, question: "Which of the following is NOT included in U.S. GDP?", options: ["Wages paid to a newly hired teacher in a public school","The value of intermediate goods used up in producing final goods","A consumer's purchase of a new washing machine","A firm's purchase of newly produced factory equipment"], correctAnswer: 1, explanation: "Intermediate goods are excluded to avoid double counting, since their value is already embedded in final goods. The teacher's services (government output), the new washing machine (consumption of a final good), and new factory equipment (investment) are all final-output components that count in GDP. The key is distinguishing intermediate from final goods.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 274, question: "Suppose a country's nominal GDP rose from $500 billion to $560 billion in one year while its GDP deflator rose from 100 to 112. What was the approximate REAL GDP growth rate?", options: ["6%","12%","0%","−12%"], correctAnswer: 2, explanation: "Real GDP Year 1 = (500/100)×100 = $500B. Real GDP Year 2 = (560/112)×100 = $500B. Since real GDP is unchanged, real growth is 0% — the entire 12% nominal increase was inflation. The 12% distractor mistakes nominal growth for real growth; 6% and −12% are arithmetic misreadings.", difficulty: "hard", topicSlug: "macro-gdp-growth" },
  { id: 275, question: "Which of the following would be classified as INVESTMENT (I) in the expenditure approach to GDP?", options: ["A consumer's purchase of a new smartphone for personal use","A household's purchase of newly issued corporate bonds","A retiree's purchase of shares of stock on an exchange","A firm's purchase of newly built office space and an increase in its unsold inventories"], correctAnswer: 3, explanation: "In national accounting, investment means new physical capital (structures, equipment) plus changes in business inventories — both appear in the correct answer. Buying bonds or existing stock is a financial transaction, not production. A consumer's smartphone is counted as consumption (C), not investment. Macroeconomic 'investment' differs from everyday financial 'investing.'", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 276, question: "A nation's real GDP per capita has been stagnant for a decade. Which single development would most directly raise its real GDP per capita over the long run?", options: ["A sustained increase in labor productivity (output per worker-hour)","An increase in the overall price level","A one-time increase in nominal wages with no change in output","Faster population growth with no change in total output"], correctAnswer: 0, explanation: "Real GDP per capita rises when each worker produces more, i.e., when labor productivity increases. A higher price level is inflation, not real growth. Nominal wage increases without added output do not raise real per-capita output. Faster population growth with fixed output would actually lower real GDP per capita.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 277, question: "Which of the following best illustrates a limitation of using GDP as a measure of overall well-being?", options: ["GDP includes the value of all newly produced final goods and services","GDP rises when a hurricane forces large amounts of reconstruction spending, even though the storm destroyed wealth and reduced welfare","GDP can be calculated using the expenditure approach","GDP rises when firms produce more output and hire more workers"], correctAnswer: 1, explanation: "GDP counts the market value of production but ignores the destruction of existing wealth and changes in welfare, so disaster-driven reconstruction can raise GDP even as society is worse off. The other statements are accurate descriptions of GDP that do not, by themselves, reveal a shortcoming as a welfare measure.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 278, question: "A country reports the following for a year (in billions): consumption $700, investment $200, government purchases $250, exports $120, imports $90, and transfer payments $60. What is GDP using the expenditure approach?", options: ["$1,270 billion","$1,240 billion","$1,180 billion","$1,360 billion"], correctAnswer: 2, explanation: "GDP = C + I + G + (X − M) = 700 + 200 + 250 + (120 − 90) = 700 + 200 + 250 + 30 = $1,180 billion. Transfer payments are NOT included because they do not correspond to current production. The $1,240 distractor wrongly adds the $60 transfers; the others mishandle net exports or include transfers.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 279, question: "Two economies start with identical real GDP. Over 35 years, Economy X grows at 2% annually and Economy Y grows at 4% annually. Using the Rule of 70, how many times will each economy's real GDP have doubled?", options: ["X doubles three times; Y doubles once","X doubles twice; Y doubles once","Both double the same number of times","X doubles once; Y doubles twice"], correctAnswer: 3, explanation: "Doubling time for X = 70/2 = 35 years, so X doubles once in 35 years. Doubling time for Y = 70/4 ≈ 17.5 years, so Y doubles about twice in 35 years (17.5 × 2 = 35). Thus Y ends roughly four times its start while X is only double — illustrating how small growth-rate differences compound dramatically.", difficulty: "hard", topicSlug: "macro-gdp-growth" },
  { id: 280, question: "Which of the following productive activities is counted in GDP?", options: ["A homeowner pays a contractor $5,000 to remodel a kitchen","A parent spends the afternoon cleaning their own home","A volunteer staffs a charity food bank for free","Two neighbors trade an hour of lawn mowing for an hour of babysitting with no money exchanged"], correctAnswer: 0, explanation: "The paid contractor's remodeling is a market transaction for a newly produced service, so it counts in GDP. Unpaid household work, volunteer labor, and non-market barter generally are not measured because no market price is recorded. This is a well-known limitation: GDP omits valuable non-market production.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 281, question: "An economy's real GDP grew 3% while its labor force grew 1% and average hours worked were unchanged. Approximately what was the growth rate of labor productivity (output per worker)?", options: ["About 4%","About 2%","About 3%","About 0%"], correctAnswer: 1, explanation: "Output growth ≈ productivity growth + labor-input growth, so productivity growth ≈ output growth − labor growth = 3% − 1% = 2%. The 4% distractor adds the rates, 3% ignores the labor change, and 0% assumes all growth came from added workers. Rising productivity is the main engine of long-run per-capita growth.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 282, question: "Which factor would shift a nation's long-run aggregate supply (and its PPC) to the LEFT, representing negative economic growth?", options: ["A technological breakthrough that raises productivity","An increase in the saving rate that funds new factories","A war that destroys a large portion of the nation's capital stock and labor force","Discovery of large new oil reserves within the country"], correctAnswer: 2, explanation: "Destruction of capital and labor reduces the economy's productive capacity, shifting LRAS and the PPC leftward (negative growth). The other three — more saving funding investment, new technology, and newly discovered resources — all expand productive capacity and shift LRAS and the PPC rightward.", difficulty: "easy", topicSlug: "macro-gdp-growth" },
  { id: 283, question: "A country's nominal GDP doubled over ten years, but economists report that real GDP barely changed. What is the most likely explanation?", options: ["The GDP deflator must have decreased over the decade","The country's population fell by half during the decade","Real output grew faster than nominal output","The price level (inflation) rose substantially over the decade, inflating nominal figures without raising real output"], correctAnswer: 3, explanation: "Nominal GDP = real GDP × (deflator/100). If nominal GDP doubled while real GDP was roughly flat, the GDP deflator (the price level) must have approximately doubled — i.e., high inflation. Real growth cannot exceed nominal growth here, and a falling deflator would mean deflation, which contradicts the data. Population change does not directly affect the nominal-versus-real relationship.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 284, question: "An economist computes that a country's real GDP rose 4% while nominal GDP rose 7% over the same year. What does this imply about the GDP deflator (the price level)?", options: ["The price level rose by approximately 3%","The price level fell by approximately 3%","The price level rose by approximately 11%","The price level was unchanged"], correctAnswer: 0, explanation: "Nominal GDP growth ≈ real GDP growth + inflation, so inflation ≈ nominal growth − real growth = 7% − 4% = 3%. The price level (deflator) therefore rose about 3%. The −3% distractor reverses the subtraction, 11% adds the rates, and 'unchanged' would require nominal and real growth to be equal.", difficulty: "medium", topicSlug: "macro-gdp-growth" },
  { id: 285, question: "Which of the following best explains why fiat money, such as the U.S. dollar, has value even though it is not backed by gold or any other commodity?", options: ["It is generally accepted as a medium of exchange and its supply is controlled by the government","It can be redeemed at any commercial bank for a fixed weight of gold","It has high intrinsic value because of the materials used to produce it","Its value is permanently fixed by international treaty"], correctAnswer: 0, explanation: "Fiat money has no intrinsic value and is not commodity-backed. It derives its value from government decree (legal tender status) and, crucially, from the fact that people accept it as a medium of exchange. A controlled supply preserves its purchasing power. Gold redeemability (a commodity standard) and intrinsic material value are precisely the features fiat money lacks.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 286, question: "A small economy uses cigarettes as money in a prison camp. Cigarettes serve as a medium of exchange, a unit of account, and a store of value. Which characteristic of cigarettes would MOST undermine their function as a store of value over a long period?", options: ["Cigarettes are widely accepted by other prisoners","Cigarettes can be divided into smaller units for small transactions","Cigarettes deteriorate physically and can be consumed, reducing their quantity over time","Cigarettes have a recognizable and uniform shape"], correctAnswer: 2, explanation: "A store of value must hold purchasing power over time. Because cigarettes deteriorate, get smoked, and otherwise disappear from circulation, holding them as wealth is risky and their real value erodes—undermining the store-of-value function specifically. Wide acceptance (medium of exchange), divisibility, and uniformity actually strengthen money's usefulness, not weaken its store-of-value role.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 287, question: "A bank has $200,000 in checkable deposits and is subject to a required reserve ratio of 10 percent. The bank currently holds $35,000 in total reserves. What is the maximum amount of NEW loans this single bank can make?", options: ["$20,000","$15,000","$35,000","$165,000"], correctAnswer: 1, explanation: "Required reserves = 10% × $200,000 = $20,000. Total reserves are $35,000, so excess reserves = $35,000 − $20,000 = $15,000. A single bank can lend out only its excess reserves, so the maximum new loan is $15,000. The $20,000 is required reserves, $35,000 is total reserves, and $165,000 misuses the deposit figure.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 288, question: "The required reserve ratio is 20 percent. A customer deposits $5,000 in cash into a checking account at a bank that previously had no excess reserves. Assuming the banking system is fully loaned up and there are no cash leakages, what is the maximum total increase in the money supply (including the initial deposit)?", options: ["$20,000","$5,000","$100,000","$25,000"], correctAnswer: 3, explanation: "The simple money multiplier = 1 / reserve ratio = 1 / 0.20 = 5. A $5,000 cash deposit creates $4,000 of excess reserves (after $1,000 required). The total change in the money supply equals the change in reserves available for lending times the multiplier. Because the cash came out of currency in circulation and went into deposits, the maximum total deposit expansion = $5,000 × 5 = $25,000. The $20,000 omits the initial deposit, $5,000 ignores expansion, and $100,000 uses the wrong base.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 289, question: "If the Federal Reserve wants to increase the money supply using open market operations, which action should it take, and what is the immediate effect on bond prices?", options: ["Sell government bonds, which raises bond prices","Buy government bonds, which raises bond prices","Buy government bonds, which lowers bond prices","Sell government bonds, which lowers bond prices"], correctAnswer: 1, explanation: "To increase the money supply, the Fed buys government bonds, injecting reserves into the banking system. Increased demand for bonds bids up their price (and lowers the interest rate / yield). Selling bonds would drain reserves and shrink the money supply. The inverse relationship between bond prices and yields is central: Fed buying = higher bond prices = lower interest rates.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 290, question: "An economy has a required reserve ratio of 12.5 percent. The Federal Reserve purchases $8 million in government securities from commercial banks. Assuming banks lend all excess reserves and there are no leakages into currency, what is the maximum possible increase in the money supply?", options: ["$64 million","$8 million","$56 million","$1 million"], correctAnswer: 0, explanation: "When the Fed buys $8 million in securities directly from banks, the entire $8 million becomes excess reserves (it is an asset swap, not a new deposit, so none is required to be held against it initially). The money multiplier = 1 / 0.125 = 8. Maximum money supply increase = $8 million × 8 = $64 million. The $56 million answer wrongly subtracts a required-reserve portion as if it were a customer deposit.", difficulty: "hard", topicSlug: "macro-money-banking" },
  { id: 291, question: "Use the simplified balance sheet below for First National Bank. Assets: Reserves $30,000; Loans $90,000. Liabilities: Demand Deposits $120,000. If the required reserve ratio is 15 percent, how much can the bank lend out in new loans?", options: ["$30,000","$18,000","$120,000","$12,000"], correctAnswer: 3, explanation: "Required reserves = 15% × $120,000 = $18,000. The bank holds $30,000 in reserves, so excess reserves = $30,000 − $18,000 = $12,000. A single bank can create new loans only up to its excess reserves, so it can lend $12,000. The $18,000 is required reserves and $30,000 is total reserves—neither is the lendable amount.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 292, question: "The money multiplier in an economy is 4. Holding the simple multiplier assumptions, what is the required reserve ratio?", options: ["4 percent","40 percent","25 percent","75 percent"], correctAnswer: 2, explanation: "The simple money multiplier = 1 / required reserve ratio. So required reserve ratio = 1 / multiplier = 1 / 4 = 0.25 = 25 percent. The other options confuse the reciprocal relationship or misplace the decimal.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 293, question: "Suppose households decide to hold more of their money as currency instead of depositing it in banks. Holding the required reserve ratio constant, what is the most likely effect on the actual money multiplier and the money supply?", options: ["The actual money multiplier falls and the money supply tends to decrease","The actual money multiplier rises and the money supply tends to increase","The actual money multiplier is unchanged because it depends only on the reserve ratio","The actual money multiplier rises but the money supply is unchanged"], correctAnswer: 0, explanation: "Currency held by the public ('cash leakages') does not get lent out and re-deposited, so it interrupts the deposit-expansion process. Greater currency holdings reduce the actual (real-world) money multiplier below the simple 1/rr value, shrinking the total amount of money the banking system can create. Thus both the multiplier and the money supply fall, all else equal.", difficulty: "hard", topicSlug: "macro-money-banking" },
  { id: 294, question: "Which of the following is counted as part of the M1 money supply but NOT part of the monetary base?", options: ["Currency held in bank vaults","Reserves held on deposit at the Federal Reserve","Currency in circulation held by the public","Checkable (demand) deposits held by the public"], correctAnswer: 3, explanation: "The monetary base = currency in circulation + bank reserves (vault cash + deposits at the Fed). M1 = currency in circulation + checkable deposits + other liquid items. Checkable deposits are part of M1 (they are spendable money held by the public) but are NOT part of the monetary base. Currency in circulation appears in both; vault cash and Fed reserves are base but not M1.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 295, question: "In the money market, the supply of money is typically drawn as a vertical line. What does this vertical shape imply?", options: ["The quantity of money supplied rises as the interest rate rises","The quantity of money supplied is set by the central bank and does not depend on the interest rate","The quantity of money demanded falls as the interest rate rises","The money supply is determined entirely by household saving decisions"], correctAnswer: 1, explanation: "A vertical money supply curve indicates that the quantity of money is fixed by the central bank's policy and is independent of (perfectly inelastic with respect to) the interest rate. The interest rate is the price of money on the vertical axis, and changing it does not change the quantity the Fed has chosen to supply. The downward-sloping money demand curve is a separate relationship.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 296, question: "In the money market, an increase in real GDP, holding the money supply and the price level constant, will most likely cause which of the following?", options: ["Money demand decreases, lowering the nominal interest rate","Money supply increases, lowering the nominal interest rate","Money demand increases, raising the nominal interest rate","Money supply decreases, raising the nominal interest rate"], correctAnswer: 2, explanation: "Higher real GDP means more transactions, which raises the transactions demand for money, shifting money demand to the right. With a fixed (vertical) money supply, greater demand for money pushes the equilibrium nominal interest rate up. The money supply is set by the Fed and does not shift in response to GDP.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 297, question: "The nominal interest rate is 7 percent and the expected inflation rate is 3 percent. According to the Fisher equation (approximation), what is the expected real interest rate?", options: ["10 percent","21 percent","2.33 percent","4 percent"], correctAnswer: 3, explanation: "By the Fisher approximation, real interest rate ≈ nominal interest rate − expected inflation = 7% − 3% = 4%. The 10% answer adds instead of subtracts, 21% multiplies, and 2.33% divides—none of which is the Fisher relationship.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 298, question: "A saver deposits money in a one-year CD paying a 6 percent nominal interest rate, expecting 2 percent inflation. Inflation instead turns out to be 5 percent. Compared with what was expected, how is the saver affected, and who benefits from the surprise?", options: ["The realized real return is higher than expected, benefiting the saver","The realized real return is lower than expected, benefiting borrowers at the saver's expense","The realized real return equals the nominal rate, so no one is affected","The realized real return is unchanged because inflation does not affect real returns"], correctAnswer: 1, explanation: "Expected real return was 6% − 2% = 4%, but the realized real return is 6% − 5% = 1%. Unexpectedly high inflation erodes the real value of fixed-rate repayments, hurting lenders/savers and benefiting borrowers, who repay in cheaper dollars. Thus the saver earns less in real terms than anticipated and borrowers gain.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 299, question: "Which of the following monetary policy actions by the Federal Reserve would be considered contractionary?", options: ["Lowering the discount rate and buying government bonds","Lowering the required reserve ratio and buying government bonds","Raising the discount rate and selling government bonds","Buying government bonds and lowering the interest paid on reserves"], correctAnswer: 2, explanation: "Contractionary (tight) monetary policy reduces the money supply and raises interest rates. Raising the discount rate makes borrowing from the Fed more costly, and selling bonds drains reserves from the banking system—both shrink the money supply. Lowering the discount rate, buying bonds, and reducing the reserve ratio are all expansionary actions.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 300, question: "An economy is experiencing a recessionary gap with high unemployment. Which combination of central bank actions and resulting effects represents appropriate expansionary monetary policy?", options: ["Buy bonds → money supply increases → interest rates fall → investment and AD rise","Sell bonds → money supply decreases → interest rates rise → investment and AD fall","Buy bonds → money supply decreases → interest rates rise → investment and AD fall","Sell bonds → money supply increases → interest rates fall → investment and AD rise"], correctAnswer: 0, explanation: "To close a recessionary gap, the Fed pursues expansionary policy. Buying bonds injects reserves, increasing the money supply; the larger money supply lowers the nominal interest rate; lower rates stimulate interest-sensitive spending (investment and consumption), shifting aggregate demand to the right. The other options reverse one or more links in this transmission chain.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 301, question: "Use the quantity theory equation MV = PQ. In a given year, the money supply (M) is $800 billion, the velocity of money (V) is 5, and real output (Q) is 200 billion units of final goods. What is the average price level (P) per unit?", options: ["$32,000 per unit","$20 per unit","$8 per unit","$25 per unit"], correctAnswer: 1, explanation: "From MV = PQ, solve P = (M × V) / Q = ($800 billion × 5) / (200 billion) = $4,000 billion / 200 billion = $20 per unit. The $25 answer divides V by Q incorrectly, $8 inverts a step, and $32,000 misuses the billions. Nominal GDP here is MV = $4,000 billion, and dividing by real output gives the price level of $20.", difficulty: "hard", topicSlug: "macro-money-banking" },
  { id: 302, question: "According to the quantity theory of money, if velocity (V) and real output (Q) are constant, a 6 percent increase in the money supply (M) will lead to which change in the price level (P)?", options: ["A 6 percent decrease in P","No change in P","A 6 percent increase in P","A 3 percent increase in P"], correctAnswer: 2, explanation: "The equation of exchange is MV = PQ. If V and Q are held constant, then percentage changes satisfy %ΔM = %ΔP. A 6% rise in M therefore produces a 6% rise in P. This is the classical/monetarist conclusion that, with fixed velocity and output, money growth translates one-for-one into inflation.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 303, question: "The Federal Reserve is often described as a 'lender of last resort.' Which scenario best illustrates this function?", options: ["During a bank panic, the Fed lends reserves to solvent banks facing sudden deposit withdrawals to prevent their collapse","The Fed purchases stocks on the open market to raise asset prices","The Fed sets a minimum wage for bank employees during a recession","The Fed guarantees a fixed return on all checking accounts in the country"], correctAnswer: 0, explanation: "As lender of last resort, the central bank provides emergency liquidity—typically through the discount window—to fundamentally solvent banks that face short-term funding pressure (e.g., a bank run). This stabilizes the financial system and prevents panics from cascading. The Fed does not buy stocks as policy, set wages, or guarantee account returns; deposit insurance (FDIC) is a separate institution.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 304, question: "A bank's balance sheet shows: Reserves $50,000; Loans $250,000; Securities $100,000 (assets) and Deposits $360,000; Owners' equity (net worth) ? (liabilities + equity). Total assets equal total liabilities plus net worth. What is the bank's net worth (owners' equity)?", options: ["$400,000","$360,000","$50,000","$40,000"], correctAnswer: 3, explanation: "Total assets = $50,000 + $250,000 + $100,000 = $400,000. The balance sheet must balance: assets = liabilities + net worth. So net worth = total assets − deposits = $400,000 − $360,000 = $40,000. The $400,000 is total assets and $360,000 is deposits, neither of which is owners' equity.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 305, question: "Which of the following correctly distinguishes the discount rate from the federal funds rate?", options: ["The discount rate is the rate banks charge each other; the federal funds rate is set directly by Congress","Both rates are identical and are fixed by the U.S. Treasury","The discount rate is the rate the Fed charges banks for loans; the federal funds rate is the rate banks charge one another for overnight loans of reserves","The discount rate is the rate on consumer mortgages; the federal funds rate is the rate on credit cards"], correctAnswer: 2, explanation: "The discount rate is the interest rate the Federal Reserve charges commercial banks that borrow reserves directly from it (through the discount window). The federal funds rate is the market-determined rate banks charge each other for overnight loans of reserves; the Fed targets it through open market operations. They are distinct policy and market rates, not Treasury- or Congress-set consumer rates.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 306, question: "The Federal Reserve lowers the required reserve ratio from 20 percent to 10 percent. Holding deposits constant, what happens to the simple money multiplier?", options: ["It falls from 5 to 10","It rises from 5 to 10","It rises from 10 to 20","It stays the same because the deposit base is unchanged"], correctAnswer: 1, explanation: "The simple money multiplier = 1 / required reserve ratio. At 20% (0.20) the multiplier is 1/0.20 = 5. At 10% (0.10) it is 1/0.10 = 10. Lowering the ratio increases the multiplier, so it rises from 5 to 10, allowing greater deposit expansion from any given amount of excess reserves.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 307, question: "Suppose the Fed conducts an open market sale of $10 million in bonds when the required reserve ratio is 25 percent. Assuming no cash leakages and that banks were fully loaned up, what is the maximum change in the money supply?", options: ["An increase of $40 million","A decrease of $10 million","A decrease of $2.5 million","A decrease of $40 million"], correctAnswer: 3, explanation: "An open market sale drains reserves, contracting the money supply. The multiplier = 1 / 0.25 = 4. Selling $10 million in bonds removes $10 million in reserves, so the maximum contraction = $10 million × 4 = $40 million decrease. The sign is negative because a sale reduces the money supply; $10 million ignores the multiplier and $2.5 million inverts the multiplier.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 308, question: "A scenario describes an economy where the central bank pays interest on reserves (IOR) and decides to raise the IOR rate significantly. What is the most likely effect on bank lending and the money supply?", options: ["Banks hold more excess reserves and lend less, tending to reduce the money supply","Banks lend more aggressively, increasing the money supply","Banks are required to reduce their reserves to zero, increasing the money supply","The IOR rate has no effect on lending decisions"], correctAnswer: 0, explanation: "When the central bank raises the interest paid on reserves, holding reserves becomes more attractive relative to making loans. Banks respond by keeping more excess reserves and reducing lending, which slows deposit creation and tends to shrink (or slow the growth of) the money supply. Raising IOR is thus a contractionary tool.", difficulty: "hard", topicSlug: "macro-money-banking" },
  { id: 309, question: "Money demand consists of transactions demand and asset (speculative) demand. Which of the following would shift the entire money demand curve to the LEFT?", options: ["An increase in the nominal interest rate","An increase in real GDP","An increase in the price level","A decrease in the price level, requiring less money for the same real transactions"], correctAnswer: 3, explanation: "The money demand curve shifts with changes in the price level or real GDP (the determinants of nominal transactions). A lower price level means each transaction requires fewer dollars, reducing money demand at every interest rate—shifting the curve left. A change in the interest rate is a movement ALONG the curve, not a shift. Higher GDP or a higher price level would shift demand right.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 310, question: "An economy is at full employment and inflation is accelerating. Following the monetary policy transmission mechanism, which sequence correctly shows how appropriate Fed policy reduces inflation?", options: ["Sell bonds → MS decreases → interest rate rises → investment falls → AD shifts left → price level falls","Buy bonds → MS increases → interest rate falls → investment rises → AD shifts right → price level rises","Sell bonds → MS increases → interest rate falls → investment rises → AD shifts right → price level falls","Buy bonds → MS decreases → interest rate rises → investment falls → AD shifts left → price level falls"], correctAnswer: 0, explanation: "To fight inflation, the Fed uses contractionary policy: selling bonds drains reserves, decreasing the money supply; the smaller money supply raises the nominal interest rate; higher rates reduce interest-sensitive investment (and consumption); aggregate demand shifts left; the price level (and inflationary pressure) falls. The other chains mismatch the direction of bond operations with the money-supply or AD effects.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 311, question: "Which of the following assets is the MOST liquid?", options: ["A 10-year corporate bond","Currency (paper money and coins)","A residential house","Shares of a thinly traded small-company stock"], correctAnswer: 1, explanation: "Liquidity measures how quickly and cheaply an asset can be converted into a medium of exchange without loss of value. Currency IS the medium of exchange, so it is perfectly liquid. Bonds, real estate, and thinly traded stocks all require time and/or incur transaction costs or price risk to convert into spendable money, making them less liquid.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 312, question: "A bank with no excess reserves receives a new $1,000 cash deposit. The required reserve ratio is 10 percent. Considering only this individual bank, how do its required reserves, excess reserves, and lending capacity change?", options: ["Required reserves rise by $1,000, excess reserves are $0, and it can lend $0","Required reserves rise by $100, excess reserves rise by $900, and it can lend up to $9,000","Required reserves rise by $100, excess reserves rise by $900, and it can lend up to $900","Required reserves rise by $900, excess reserves rise by $100, and it can lend up to $100"], correctAnswer: 2, explanation: "On a $1,000 deposit with a 10% reserve ratio, required reserves increase by 10% × $1,000 = $100. The remaining $900 becomes excess reserves. A single bank can lend out only its excess reserves, so it can make up to $900 in new loans. The $9,000 figure is the system-wide multiplied expansion, not this single bank's capacity.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 313, question: "Holding all else constant, an increase in the money supply will most likely have which short-run effects on the nominal interest rate and aggregate demand?", options: ["The nominal interest rate rises and aggregate demand decreases","The nominal interest rate falls and aggregate demand increases","The nominal interest rate falls and aggregate demand decreases","The nominal interest rate rises and aggregate demand increases"], correctAnswer: 1, explanation: "An increase in the money supply (a rightward shift of the vertical money supply curve) lowers the equilibrium nominal interest rate in the money market. The lower interest rate stimulates interest-sensitive spending such as investment and consumer durables, increasing aggregate demand. Thus the interest rate falls and AD rises.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 314, question: "Two banks are fully loaned up. The required reserve ratio is 5 percent. The Fed buys $20,000 of bonds from Bank A. Ignoring cash leakages, what is the maximum total amount of new money the banking system can create from this transaction?", options: ["$20,000","$1,000","$100,000","$400,000"], correctAnswer: 3, explanation: "When the Fed buys bonds directly from a bank, the full $20,000 becomes excess reserves. The money multiplier = 1 / 0.05 = 20. Maximum money creation = $20,000 × 20 = $400,000. The $20,000 ignores multiplied expansion, $1,000 is merely a required-reserve figure, and $100,000 misapplies a 5x multiplier.", difficulty: "hard", topicSlug: "macro-money-banking" },
  { id: 315, question: "Which scenario describes a situation where the money multiplier process would be WEAKER than the simple model predicts?", options: ["Banks choose to hold substantial excess reserves rather than lend them out","Banks lend out every dollar of excess reserves immediately","The public deposits all currency it receives back into banks","The required reserve ratio is reduced to a very low level"], correctAnswer: 0, explanation: "The simple money multiplier assumes banks lend all excess reserves and the public re-deposits everything. When banks instead hold excess reserves (perhaps for safety or because lending is unprofitable), each round of the deposit-expansion process leaks reserves out of lending, so actual money creation falls short of 1/rr. Full lending, full re-depositing, and a lower reserve ratio all strengthen the process.", difficulty: "hard", topicSlug: "macro-money-banking" },
  { id: 316, question: "Barter economies are often described as inefficient compared with monetary economies. Which problem of barter does the use of money most directly solve?", options: ["The existence of scarcity in the economy","The presence of opportunity costs in production","The need for a double coincidence of wants between trading partners","The tendency for prices to change over time"], correctAnswer: 2, explanation: "Barter requires a 'double coincidence of wants'—each party must want exactly what the other offers—which makes trade costly and slow. Money serves as a universally accepted medium of exchange, eliminating this requirement and dramatically lowering transaction costs. Money does not eliminate scarcity, opportunity cost, or price changes, which exist in any economy.", difficulty: "easy", topicSlug: "macro-money-banking" },
  { id: 317, question: "Suppose nominal GDP is $12 trillion and the money supply is $3 trillion. According to the equation of exchange, what is the velocity of money?", options: ["0.25","4","9","36"], correctAnswer: 1, explanation: "From MV = PQ, where PQ is nominal GDP, velocity V = nominal GDP / M = $12 trillion / $3 trillion = 4. This means each dollar is spent on average 4 times per year on final goods and services. The 0.25 answer inverts the ratio, 9 subtracts, and 36 multiplies—none of which gives velocity.", difficulty: "medium", topicSlug: "macro-money-banking" },
  { id: 318, question: "The economy of Vendia is operating at full employment. The central bank unexpectedly increases the money supply, lowering interest rates. In the short run, which of the following best describes the effect on the aggregate demand (AD) curve and the resulting outcome?", options: ["AD shifts right; real GDP rises above potential and the price level increases","AD shifts left; real GDP falls below potential and the price level decreases","The short-run aggregate supply (SRAS) curve shifts right; only the price level falls","AD remains unchanged because monetary policy affects only nominal variables"], correctAnswer: 0, explanation: "Lower interest rates reduce the cost of borrowing, raising interest-sensitive spending such as investment and consumer durables. This increases aggregate demand, shifting AD to the right. Starting at full employment, the rightward AD shift pushes real GDP above potential (an inflationary gap) and raises the price level along the upward-sloping SRAS curve. Monetary policy is not neutral in the short run because of sticky prices and wages.", difficulty: "easy", topicSlug: "macro-aggregate-demand-supply" },
  { id: 319, question: "An economy is initially in long-run equilibrium. A sharp, sustained increase in the world price of crude oil raises production costs across most industries. In the short run, what happens to the price level and real output?", options: ["The price level falls and real output rises","Both the price level and real output rise","The price level rises and real output falls (stagflation)","Both the price level and real output fall"], correctAnswer: 2, explanation: "A rise in a key input cost like oil is a negative supply shock that shifts the short-run aggregate supply (SRAS) curve to the left. With AD unchanged, the new short-run equilibrium occurs at a higher price level and a lower level of real output. This simultaneous higher inflation and lower output is called stagflation, and it is the defining outcome of an adverse supply shock.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 320, question: "In the long run, the aggregate supply (LRAS) curve is vertical. Which of the following best explains why?", options: ["In the long run, higher prices always cause firms to produce more output indefinitely","In the long run, aggregate demand has no effect on the price level","In the long run, the nominal wage is fixed by contracts and cannot change","In the long run, output is determined by resources and technology, not the price level, because wages and other input prices fully adjust"], correctAnswer: 3, explanation: "The LRAS curve is vertical at potential (full-employment) output because, in the long run, all input prices including nominal wages adjust fully to changes in the price level. Once wages and prices have fully adjusted, the quantity of real output supplied depends only on the economy's available resources, capital stock, and technology, not on the price level. Therefore changes in the price level leave long-run output unchanged.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 321, question: "A nation's government simultaneously increases spending on infrastructure and cuts personal income taxes during a recession. Assuming the marginal propensity to consume is positive and the economy has unused capacity, what is the most likely short-run effect?", options: ["AD shifts right, raising both real GDP and the price level","AD shifts left, reducing both real GDP and the price level","SRAS shifts right, reducing the price level while raising real GDP","There is no change in AD because the policies offset each other"], correctAnswer: 0, explanation: "Both expansionary fiscal tools increase aggregate demand. Higher government spending directly raises the G component of AD, and a tax cut raises disposable income, which increases consumption (C) given a positive MPC. Both effects shift AD to the right. With unused capacity along an upward-sloping SRAS, real GDP rises and the price level increases modestly. The two policies reinforce rather than offset one another.", difficulty: "easy", topicSlug: "macro-aggregate-demand-supply" },
  { id: 322, question: "An economy has a marginal propensity to consume (MPC) of 0.8. The government increases its purchases by $50 billion. Ignoring crowding out and assuming spare capacity, by how much does the aggregate demand curve shift horizontally?", options: ["$50 billion","$250 billion","$40 billion","$200 billion"], correctAnswer: 1, explanation: "The spending multiplier is 1/(1 − MPC) = 1/(1 − 0.8) = 1/0.2 = 5. A $50 billion increase in government purchases therefore shifts AD by 5 × $50 billion = $250 billion. The horizontal shift of AD equals the initial change in spending times the multiplier, not the initial change alone ($50 billion) nor the change times the MPS ($40 billion).", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 323, question: "Consumer confidence rises sharply after a long period of pessimism, and households decide to spend more out of every dollar of income. Holding all else equal, which component of aggregate demand changes first, and in which direction does AD move?", options: ["Investment falls, and AD shifts to the left","Net exports rise, and AD shifts to the right","Consumption rises, and AD shifts to the right","Government spending rises, and AD shifts to the right"], correctAnswer: 2, explanation: "Higher consumer confidence directly raises consumption (C), the largest component of aggregate demand. When households are optimistic, they spend more at every price level, shifting the entire AD curve to the right. Investment and net exports are not the direct channel here, and government spending is a policy variable unaffected by consumer sentiment.", difficulty: "easy", topicSlug: "macro-aggregate-demand-supply" },
  { id: 324, question: "The domestic currency of Maritia appreciates significantly against its trading partners' currencies. All else equal, what is the most likely effect on aggregate demand?", options: ["AD shifts right because cheaper imports raise consumer purchasing power and spending","AD is unaffected because exchange rates influence only the price level, not real output","AD shifts right because exports become cheaper for foreign buyers","AD shifts left because exports become more expensive abroad and imports become cheaper, lowering net exports"], correctAnswer: 3, explanation: "A currency appreciation makes a nation's exports more expensive for foreigners and makes imports cheaper for domestic buyers. Exports fall and imports rise, so net exports (X − M) decline. Since net exports are a component of AD, the AD curve shifts to the left. The cheaper-imports effect lowers net exports rather than boosting overall domestic demand.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 325, question: "An economy is in a recessionary gap with no policy intervention. According to the self-correcting (classical) mechanism, how does the economy return to long-run equilibrium, and what happens to the price level during the adjustment?", options: ["Aggregate demand automatically rises, shifting AD right; the price level rises and output returns to potential","Nominal wages and input prices fall, shifting SRAS right; the price level falls and output returns to potential","Nominal wages rise, shifting SRAS left; the price level rises and output returns to potential","The LRAS curve shifts left to meet the recessionary output level"], correctAnswer: 1, explanation: "In a recessionary gap, high unemployment and excess capacity put downward pressure on nominal wages and other input prices. As these costs fall, the SRAS curve shifts to the right. This lowers the price level and raises real output until the economy returns to potential output at the intersection with LRAS. The self-correction works through supply-side wage and price flexibility, not through automatic AD increases.", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 326, question: "A negative wealth effect occurs when the price level rises. Which of the following best describes how this effect contributes to the downward slope of the aggregate demand curve?", options: ["A higher price level reduces the real value of money holdings, lowering consumption and the quantity of real GDP demanded","A higher price level raises real interest rates, increasing investment and the quantity demanded","A higher price level makes domestic goods cheaper abroad, raising net exports and the quantity demanded","A higher price level increases the real value of savings, raising consumption and the quantity demanded"], correctAnswer: 0, explanation: "The wealth (real-balances) effect explains part of the downward slope of AD. When the price level rises, the purchasing power of fixed nominal money holdings and financial assets falls, so households feel poorer and reduce consumption. This lowers the quantity of real GDP demanded as the price level rises, contributing to the inverse relationship captured by the downward-sloping AD curve.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 327, question: "The table shows an economy's short-run aggregate supply schedule. Price level / Real GDP supplied: 100 / $800B; 110 / $900B; 120 / $1,000B; 130 / $1,050B. Aggregate demand intersects SRAS where real GDP is $1,000B. If AD then increases so that the new equilibrium price level is 130, by how much does real GDP rise?", options: ["$100 billion","$150 billion","$50 billion","$200 billion"], correctAnswer: 2, explanation: "At the initial equilibrium the price level is 120 and real GDP is $1,000B. After the AD increase the price level is 130, where SRAS shows real GDP of $1,050B. The rise in real GDP is $1,050B − $1,000B = $50 billion. Notice the SRAS schedule flattens at higher output (output rises by only $50B for the 120-to-130 step), reflecting the economy approaching capacity.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 328, question: "Which of the following events would shift the long-run aggregate supply (LRAS) curve to the right?", options: ["A temporary increase in the price of imported oil","An increase in government spending financed by borrowing","A rise in consumer confidence that boosts spending","A large net increase in the labor force due to immigration of working-age adults"], correctAnswer: 3, explanation: "LRAS depends on the quantity and quality of resources, the capital stock, and technology. A permanent net increase in the labor force expands the economy's productive capacity, shifting LRAS to the right. A temporary oil price change affects only SRAS. Increased government spending and higher consumer confidence shift AD, not LRAS, because they change demand rather than potential output.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 329, question: "An economy is producing at an output level above its full-employment level (an inflationary gap). If policymakers take no action, what does the self-correcting mechanism predict for nominal wages and the SRAS curve?", options: ["Nominal wages fall, shifting SRAS right until output returns to potential at a lower price level","Nominal wages rise, shifting SRAS left until output returns to potential at a higher price level","Nominal wages remain fixed, so the gap persists indefinitely","The LRAS curve shifts right to accommodate the higher output"], correctAnswer: 1, explanation: "In an inflationary gap, output exceeds potential and unemployment is below the natural rate, creating tight labor markets. Workers bid up nominal wages and other input prices rise. Higher production costs shift the SRAS curve to the left, raising the price level and reducing output until the economy returns to potential output on the LRAS curve. The adjustment ends at a higher price level than before.", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 330, question: "A country reduces business taxes and provides investment tax credits, encouraging firms to purchase more capital and improve productivity. In the long run, what is the most likely effect on aggregate supply?", options: ["Only AD shifts right, with no change in potential output","SRAS shifts left because taxes raise costs","Both SRAS and LRAS shift right, raising potential output","LRAS shifts left as firms reduce hiring"], correctAnswer: 2, explanation: "Investment incentives that increase the capital stock and productivity expand the economy's productive capacity. Greater capital and productivity lower per-unit costs, shifting SRAS right, and increase potential output, shifting LRAS right. The result is higher potential real GDP. Although there may be a short-run AD effect from increased investment spending, the question's emphasis on capital and productivity points to a supply-side expansion of potential output.", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 331, question: "In a simple Keynesian model with no taxes and no imports, the marginal propensity to save (MPS) is 0.25. The central bank's actions reduce planned investment by $30 billion. By how much will the aggregate demand curve shift, and in which direction?", options: ["AD shifts left by $30 billion","AD shifts left by $7.5 billion","AD shifts right by $120 billion","AD shifts left by $120 billion"], correctAnswer: 3, explanation: "The spending multiplier equals 1/MPS = 1/0.25 = 4. A $30 billion decrease in planned investment lowers AD by the multiplier times the change: 4 × $30 billion = $120 billion. Because investment fell, AD shifts to the left (a decrease). The shift equals $120 billion, not the initial $30 billion change alone and not $30 billion × MPS.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 332, question: "Consider the aggregate demand curve. A movement ALONG the AD curve (rather than a shift of the entire curve) is caused by which of the following?", options: ["A change in consumer confidence","A change in the economy's overall price level","A change in government spending","A change in the expected future profitability of investment"], correctAnswer: 1, explanation: "A movement along the AD curve is a change in the quantity of real GDP demanded caused by a change in the price level, operating through the wealth, interest-rate, and exchange-rate effects. By contrast, changes in consumer confidence, government spending, or investment expectations are non-price determinants that shift the entire AD curve. Distinguishing movements along from shifts of the curve is a core AP skill.", difficulty: "easy", topicSlug: "macro-aggregate-demand-supply" },
  { id: 333, question: "An economy begins in long-run equilibrium. The government dramatically increases spending, shifting AD to the right and opening an inflationary gap. After the economy fully self-corrects in the long run, how do real GDP and the price level compare to their original values?", options: ["Real GDP is permanently higher, and the price level returns to its original level","Both real GDP and the price level return to their original levels","Real GDP returns to its original (potential) level, but the price level is permanently higher","Both real GDP and the price level are permanently higher"], correctAnswer: 2, explanation: "The rightward AD shift first raises both output and the price level (inflationary gap). Over time, rising nominal wages shift SRAS left until output returns to potential on the vertical LRAS curve. Because LRAS fixes long-run output, real GDP returns to its original potential level. However, both the AD increase and the SRAS leftward shift push the price level up, so the price level is permanently higher than before.", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 334, question: "Which of the following correctly pairs an aggregate demand component with an event that would increase it?", options: ["Net exports — a recession in trading-partner economies that reduces foreign demand for this nation's goods","Investment — a decrease in real interest rates that lowers borrowing costs for firms","Consumption — an increase in personal income taxes","Government spending — a balanced-budget requirement that forces spending cuts"], correctAnswer: 1, explanation: "A decrease in real interest rates lowers the cost of borrowing, encouraging firms to undertake more investment projects, which increases the I component of AD. A recession abroad would reduce net exports, not increase them. Higher income taxes reduce disposable income and lower consumption. A balanced-budget rule forcing cuts would lower, not raise, government spending. Only the investment pairing is correct.", difficulty: "easy", topicSlug: "macro-aggregate-demand-supply" },
  { id: 335, question: "Suppose an economy is in a recessionary gap of $200 billion (actual GDP is $200 billion below potential). If the MPC is 0.75, what is the minimum increase in government purchases needed to close the gap, ignoring crowding out and price-level effects?", options: ["$200 billion","$150 billion","$800 billion","$50 billion"], correctAnswer: 3, explanation: "The spending multiplier is 1/(1 − MPC) = 1/(1 − 0.75) = 1/0.25 = 4. To close a $200 billion gap, the required increase in government purchases is the gap divided by the multiplier: $200 billion / 4 = $50 billion. A $50 billion spending increase, multiplied by 4, produces the $200 billion increase in real GDP needed to reach potential output.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 336, question: "A graph shows AD intersecting SRAS to the LEFT of the vertical LRAS curve. Which statement about this economy is correct?", options: ["The economy has an inflationary gap, with unemployment below the natural rate","The economy has a recessionary gap, with cyclical unemployment above zero and output below potential","The economy is in long-run equilibrium with no output gap","The economy is producing beyond its physical capacity"], correctAnswer: 1, explanation: "When the short-run equilibrium (AD ∩ SRAS) lies to the left of LRAS, current real output is below potential output. This is a recessionary gap, characterized by cyclical unemployment (an unemployment rate above the natural rate) and idle resources. An inflationary gap would place the short-run equilibrium to the right of LRAS, and long-run equilibrium would have AD, SRAS, and LRAS intersecting at the same point.", difficulty: "easy", topicSlug: "macro-aggregate-demand-supply" },
  { id: 337, question: "An improvement in technology lowers per-unit production costs throughout the economy while simultaneously raising potential output. In the short run, what happens to the price level and real GDP, assuming AD is unchanged?", options: ["The price level rises and real GDP falls","Both the price level and real GDP fall","The price level falls and real GDP rises","Both the price level and real GDP rise"], correctAnswer: 2, explanation: "A favorable technology shock lowers production costs, shifting SRAS to the right (and LRAS right as well). With AD held constant, the rightward SRAS shift moves the short-run equilibrium down along AD to a lower price level and a higher level of real output. This is the opposite of stagflation: output expands while inflationary pressure eases.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 338, question: "Which of the following best explains the interest-rate effect that contributes to the downward slope of the aggregate demand curve?", options: ["A higher price level reduces money demand, pushing interest rates down and increasing spending","A higher price level makes domestic exports cheaper, raising net exports","A higher price level increases the real value of cash, raising consumption","A higher price level raises money demand, pushing interest rates up and reducing interest-sensitive spending"], correctAnswer: 3, explanation: "The interest-rate effect works through money markets: when the price level rises, households and firms need more money to conduct transactions, increasing money demand. With a fixed money supply, higher money demand raises the nominal interest rate. Higher interest rates reduce interest-sensitive spending such as investment and consumer durables, lowering the quantity of real GDP demanded. This inverse relationship steepens the AD curve's downward slope.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 339, question: "An economy's nominal wages are set by multi-year contracts and are 'sticky' in the short run. The price level unexpectedly rises. Why does the short-run aggregate supply curve slope upward as a result?", options: ["Higher output prices immediately raise nominal wages by the same proportion, leaving production unchanged","Higher output prices with fixed nominal wages raise firms' profit margins, so they expand production","Higher output prices reduce real wages so much that firms cut production","Higher output prices have no effect on production because supply is vertical in the short run"], correctAnswer: 1, explanation: "The sticky-wage theory of upward-sloping SRAS holds that nominal wages are fixed by contracts in the short run. When the price level rises but nominal wages stay fixed, the real wage firms pay falls and per-unit profit margins widen. Firms respond by hiring more workers and increasing output. This positive relationship between the price level and real output produces the upward-sloping SRAS curve in the short run.", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 340, question: "A foreign government places large tariffs on goods imported from Country Z, reducing Country Z's exports substantially. Holding everything else constant, what is the immediate effect on Country Z's aggregate demand and short-run output?", options: ["AD shifts right; real GDP and the price level both rise","SRAS shifts left; real GDP falls and the price level rises","AD shifts left; real GDP and the price level both fall","AD is unchanged because tariffs affect only foreign economies"], correctAnswer: 2, explanation: "Foreign tariffs reduce demand for Country Z's exports, lowering net exports (X − M), a component of AD. The AD curve shifts to the left. Along an upward-sloping SRAS, a leftward AD shift reduces both real GDP and the price level, potentially opening a recessionary gap. The shock operates through demand (net exports), not through domestic production costs, so SRAS is unaffected initially.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 341, question: "An economy is in long-run equilibrium with potential output of $2,000 billion. A severe drought destroys a large share of agricultural capital and reduces the available stock of productive resources. Assuming the loss is permanent, what happens to LRAS and the long-run price level if AD is unchanged?", options: ["LRAS shifts right; potential output rises and the long-run price level falls","LRAS shifts left; potential output falls and the long-run price level rises","LRAS is unchanged; only the short-run price level rises","LRAS shifts left; potential output falls and the long-run price level falls"], correctAnswer: 1, explanation: "A permanent destruction of productive resources reduces the economy's capacity, shifting LRAS to the left so potential output falls below $2,000 billion. With AD unchanged, the long-run equilibrium moves up along AD to a higher price level. So potential output falls and the long-run price level rises. (A temporary shock would shift only SRAS, but a permanent loss of capital affects LRAS.)", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 342, question: "Which combination of events would unambiguously shift the aggregate demand curve to the LEFT?", options: ["An increase in government spending combined with a decrease in taxes","A decrease in interest rates combined with an increase in consumer confidence","An increase in net exports combined with an increase in investment","A decrease in government spending combined with an increase in personal income taxes"], correctAnswer: 3, explanation: "Aggregate demand decreases (shifts left) when its components fall. A decrease in government spending directly reduces the G component, and an increase in income taxes lowers disposable income and consumption (C). Both push AD to the left, so the combination is unambiguously contractionary. The other options describe expansionary forces (lower rates, higher confidence, higher net exports, higher investment) that shift AD right.", difficulty: "easy", topicSlug: "macro-aggregate-demand-supply" },
  { id: 343, question: "An economy has an aggregate expenditures multiplier of 5. Policymakers want to increase real GDP by $400 billion to close a recessionary gap. If they instead use a lump-sum tax cut (where the tax multiplier is MPC/(1 − MPC)), and the MPC is 0.8, what tax cut is required?", options: ["$100 billion","$80 billion","$400 billion","$320 billion"], correctAnswer: 0, explanation: "With MPC = 0.8, the tax multiplier is MPC/(1 − MPC) = 0.8/0.2 = 4. To raise real GDP by $400 billion, the required tax cut is the target change divided by the tax multiplier: $400 billion / 4 = $100 billion. (Note the tax multiplier of 4 is smaller in magnitude than the spending multiplier of 5, which is why a larger tax cut than a spending increase would be needed; here $100 billion vs. $80 billion of spending.)", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 344, question: "During a deep recession, a government dramatically increases deficit-financed spending. Critics argue that 'crowding out' will partially offset the policy's effect on AD. Which mechanism do they have in mind?", options: ["Increased government spending lowers interest rates, raising private investment","Increased taxes reduce consumption directly, lowering AD","Increased government borrowing raises interest rates, reducing private investment","Increased money supply raises the price level, reducing real balances"], correctAnswer: 2, explanation: "Crowding out occurs when deficit-financed government spending increases the demand for loanable funds, pushing real interest rates up. Higher interest rates discourage interest-sensitive private investment (and some interest-sensitive consumption). This decline in private spending partially offsets the increase in government spending, so AD rises by less than the simple multiplier would suggest. The effect works through interest rates, not directly through taxes or the money supply.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 345, question: "The following short-run equilibrium is observed: real GDP equals potential output, and the price level is stable. AD then decreases. Which sequence correctly describes the short-run and long-run adjustment with no policy response?", options: ["Short run: output falls below potential and price level falls; long run: wages fall, SRAS shifts right, output returns to potential at a still-lower price level","Short run: output rises above potential and price level rises; long run: wages rise, SRAS shifts left, output returns to potential","Short run: output falls and price level rises; long run: SRAS shifts left, output falls further","Short run: no change occurs because the economy is at potential; long run: LRAS shifts left"], correctAnswer: 0, explanation: "Starting at potential, a leftward AD shift moves the short-run equilibrium down along SRAS, so output falls below potential (recessionary gap) and the price level falls. With no policy response, persistent unemployment drives nominal wages and input prices down, shifting SRAS to the right. Output returns to potential on LRAS, but the price level ends even lower than the short-run level because both AD and SRAS shifts lowered prices.", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 346, question: "A country experiences simultaneous events: (1) a wave of new business investment due to optimism, and (2) a sudden increase in worker productivity from new training programs. In the short run, what is the combined effect on real GDP?", options: ["Real GDP unambiguously falls because both AD and SRAS shift left","Real GDP unambiguously rises because both AD and SRAS shift right","Real GDP is unchanged because the two effects exactly cancel","Real GDP rises only if AD shifts more than SRAS"], correctAnswer: 1, explanation: "Increased investment optimism shifts AD to the right, raising output. Higher worker productivity lowers per-unit costs and shifts SRAS to the right, also raising output. When both AD and SRAS shift right, real GDP unambiguously increases, although the effect on the price level is ambiguous (the rightward AD shift pushes prices up while the rightward SRAS shift pushes prices down). Output, however, clearly rises.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 347, question: "An economist states: 'In the short run an increase in aggregate demand raises both output and prices, but in the long run it raises only prices.' Which assumption about aggregate supply is essential to this statement?", options: ["Both SRAS and LRAS are vertical at potential output","Both SRAS and LRAS are horizontal","SRAS is vertical while LRAS is upward-sloping","SRAS is upward-sloping while LRAS is vertical at potential output"], correctAnswer: 3, explanation: "For an AD increase to raise both output and prices in the short run, SRAS must be upward-sloping, so a rightward AD shift moves the economy up along SRAS. For the AD increase to raise only prices in the long run, LRAS must be vertical at potential output, so output ultimately returns to potential while only the price level rises. This standard AS framework underlies the statement.", difficulty: "medium", topicSlug: "macro-aggregate-demand-supply" },
  { id: 348, question: "An economy is operating well below potential output (a large recessionary gap) on the relatively flat portion of its SRAS curve. The government enacts a large increase in spending. Compared with an economy operating near full employment, what is the most likely short-run outcome of the same spending increase?", options: ["A smaller increase in real GDP and a larger increase in the price level","An equal increase in real GDP and the price level in both economies","A larger increase in real GDP and a smaller increase in the price level","A decrease in real GDP because the economy is below potential"], correctAnswer: 2, explanation: "On the flat (Keynesian) range of SRAS, abundant idle resources allow output to expand with little upward pressure on prices. A rightward AD shift there produces a large gain in real GDP and only a small rise in the price level. Near full employment, SRAS is steep, so the same AD shift yields a smaller output gain and a larger price increase. The slope of SRAS at the operating point determines how the AD change splits between output and prices.", difficulty: "hard", topicSlug: "macro-aggregate-demand-supply" },
  { id: 349, question: "The required reserve ratio is 10%. A commercial bank receives a new checkable deposit of $5,000 in currency that had previously been held outside the banking system. If banks lend out all excess reserves and no cash leaks out, what is the maximum possible increase in the total money supply, including the original deposit?", options: ["$45,000","$5,000","$50,000","$500"], correctAnswer: 0, explanation: "The simple deposit multiplier is 1/0.10 = 10. The original $5,000 was currency already counted in M1, so depositing it does not by itself change the money supply: currency falls by $5,000 while demand deposits rise by $5,000, a net change of zero. The expansion comes entirely from lending the $4,500 of excess reserves: 4,500 × 10 = $45,000 of new deposits created through the system, so the money supply rises by $45,000. The $50,000 choice double-counts the original $5,000, which only converted existing currency into deposits. The $5,000 choice ignores multiple expansion entirely, and $500 confuses the required reserve with the money change.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 350, question: "A central bank's required reserve ratio is 20%. The Fed buys $800 in government bonds directly from a commercial bank. Assuming banks hold no excess reserves and the public holds no additional currency, by how much can the total money supply increase at most?", options: ["$4,000","$800","$3,200","$1,600"], correctAnswer: 0, explanation: "When the Fed buys a bond from a bank, the entire $800 becomes new excess reserves (no deposit was created, so none is required to be held). The money multiplier is 1/0.20 = 5, so the maximum money creation is 800 × 5 = $4,000. The $3,200 choice mistakenly removes a 20% reserve as if the $800 were a deposit (800 × 0.8 × 5). The $800 choice ignores multiple expansion, and $1,600 uses a multiplier of 2.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 351, question: "The money multiplier in an economy is 4. If the central bank wants to increase the money supply by $600 billion through open market operations, approximately how large a bond purchase is required, assuming the simple multiplier holds?", options: ["$2,400 billion","$600 billion","$2,400 billion divided by the reserve ratio","$150 billion"], correctAnswer: 3, explanation: "If the multiplier is 4, then change in money supply = multiplier × change in reserves. To get $600 billion, the Fed must inject 600 / 4 = $150 billion in new reserves, so it buys $150 billion in bonds. Buying $2,400 billion would multiply to $9,600 billion. Buying $600 billion would expand the money supply by $2,400 billion, four times too much.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 352, question: "A required reserve ratio of 12.5% applies to all banks. A single bank receives a $400 increase in checkable deposits. How much of this deposit must the bank hold as required reserves, and how much can it initially lend out?", options: ["Hold $50; lend $350","Hold $350; lend $50","Hold $80; lend $320","Hold $400; lend $0"], correctAnswer: 0, explanation: "Required reserves = 0.125 × $400 = $50, leaving excess reserves of $400 − $50 = $350 available to lend immediately. The bank lends only its excess reserves, not the full deposit. The reversed choice swaps the two figures, and the $80/$320 choice applies a 20% ratio instead of 12.5%.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 353, question: "An economy's money supply is $500 billion and velocity is 8. According to the equation of exchange (MV = PQ), what is the level of nominal GDP?", options: ["$62.5 billion","$4,000 billion","$508 billion","$500 billion"], correctAnswer: 1, explanation: "Nominal GDP equals PQ, which by the equation of exchange equals M × V = 500 × 8 = $4,000 billion. The $62.5 billion choice divides M by V instead of multiplying, and the other choices ignore velocity entirely.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 354, question: "Suppose the velocity of money and real output are both constant. According to the quantity theory of money, if the central bank doubles the money supply, what happens to the price level in the long run?", options: ["It is unchanged because output absorbs the new money","It falls by half","It doubles","It rises by exactly the growth rate of velocity"], correctAnswer: 2, explanation: "With MV = PQ and both V and Q (real output) held fixed, the price level P is proportional to M. Doubling M doubles P. This is the monetarist long-run neutrality result: money affects only nominal variables. The other options contradict the proportional relationship implied when V and Q are constant.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 355, question: "In a given year, nominal GDP is $10,000 billion, the price index expressed as a decimal is 2.0, and the money supply is $2,000 billion. Using MV = PQ, what is the velocity of money?", options: ["2.5","10.0","0.2","5.0"], correctAnswer: 3, explanation: "Velocity V = PQ / M = nominal GDP / M = 10,000 / 2,000 = 5.0. (Equivalently, P×Q = nominal GDP = $10,000 billion.) The 10.0 choice mistakenly uses real GDP-style double counting, and 2.5 inverts part of the ratio.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 356, question: "The Federal Open Market Committee announces a decision to LOWER its target for the federal funds rate. Which open market action is consistent with reaching this new lower target, and what is the immediate effect on bank reserves?", options: ["Sell government bonds; reserves decrease","Buy government bonds; reserves increase","Buy government bonds; reserves decrease","Raise the reserve requirement; reserves increase"], correctAnswer: 1, explanation: "To push the federal funds rate down, the Fed must increase the supply of reserves in the interbank market. It does this by buying government bonds, which credits banks with new reserves. More reserves available for overnight lending drives the federal funds rate down toward the new target. Selling bonds would drain reserves and raise the rate.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 357, question: "On a graph of the money market, the money supply curve is vertical and the money demand curve slopes downward. If the central bank conducts a large bond SALE, which change best describes the new equilibrium?", options: ["Money supply shifts left; nominal interest rate rises","Money supply shifts right; nominal interest rate falls","Money demand shifts left; nominal interest rate falls","Money supply shifts left; nominal interest rate falls"], correctAnswer: 0, explanation: "Selling bonds withdraws reserves and reduces the money supply, shifting the vertical money supply curve leftward. Along a downward-sloping money demand curve, a smaller money supply produces a higher equilibrium nominal interest rate. The other options either shift the wrong curve or get the direction of the rate change backward.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 358, question: "Real GDP is below potential and the central bank wishes to close the recessionary gap using monetary policy. Which combination of actions and outcomes is fully consistent with appropriate expansionary monetary policy?", options: ["Sell bonds, raise the discount rate; interest rates fall, AD rises","Buy bonds, raise reserve requirements; interest rates rise, AD falls","Lower reserve requirements; interest rates rise, investment falls","Buy bonds, lower the discount rate, lower reserve requirements; interest rates fall, AD rises"], correctAnswer: 3, explanation: "Expansionary monetary policy increases the money supply: buy bonds, lower the discount rate, and lower reserve requirements. A larger money supply lowers the nominal interest rate, stimulating interest-sensitive investment and consumption, which shifts aggregate demand right to close the recessionary gap. The other options mix contractionary tools or contradict the rate-investment relationship.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 359, question: "A bank's T-account shows demand deposits of $10,000 and total reserves of $2,500. If the required reserve ratio is 15%, how much does this bank currently hold in EXCESS reserves?", options: ["$1,500","$1,000","$2,500","$375"], correctAnswer: 1, explanation: "Required reserves = 0.15 × $10,000 = $1,500. Excess reserves = total reserves − required reserves = $2,500 − $1,500 = $1,000. The $1,500 choice reports required (not excess) reserves, $2,500 is total reserves, and $375 misapplies the ratio to the reserves figure.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 360, question: "The nominal interest rate on a one-year loan is 6% and expected inflation over the year is 2%. According to the Fisher relationship, what is the approximate expected real interest rate?", options: ["8%","3%","4%","12%"], correctAnswer: 2, explanation: "The approximate real interest rate equals the nominal rate minus expected inflation: 6% − 2% = 4%. Adding the two (8%) reverses the Fisher equation, and the other choices misuse the relationship.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 361, question: "An economy is at full employment when the central bank unexpectedly increases the money supply. In the SHORT run, which sequence best traces the effects through the loanable funds and goods markets?", options: ["Real interest rate falls, investment rises, AD shifts right, real GDP rises above potential","Real interest rate rises, investment falls, AD shifts left, real GDP falls below potential","Real interest rate falls, investment falls, AD unchanged, only prices rise","Nominal interest rate rises, saving rises, AD shifts right"], correctAnswer: 0, explanation: "More money lowers the real (and nominal) interest rate in the short run, increasing the supply of loanable funds and stimulating interest-sensitive investment. Higher investment and consumption shift aggregate demand right, pushing real GDP temporarily above potential and creating an inflationary gap. The other paths reverse the rate change or the direction of AD.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 362, question: "A central banker states: 'Our policy rate is already near zero, banks are accumulating large excess reserves, and additional open market purchases are not increasing lending or spending.' This situation is best described as:", options: ["Crowding out","Cost-push inflation","The crowding-in effect","A liquidity trap"], correctAnswer: 3, explanation: "When interest rates are near the zero lower bound and further injections of reserves fail to stimulate borrowing or spending, conventional expansionary monetary policy loses traction. This is the liquidity trap. Crowding out involves government borrowing raising rates, which is not occurring here.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 363, question: "The Fed pays interest on reserves (IOR) that banks hold at the central bank. If the Fed RAISES the interest rate it pays on reserves while leaving everything else unchanged, what is the most likely effect on bank lending and the money supply?", options: ["Banks lend more; money supply expands","Banks are unaffected because IOR is not a policy tool","Banks hold more reserves and lend less; money supply contracts","Banks lend more because they earn more on reserves"], correctAnswer: 2, explanation: "A higher interest rate on reserves raises the opportunity cost of lending, since holding reserves at the Fed becomes relatively more attractive. Banks therefore hold more excess reserves and make fewer loans, which is contractionary and tends to slow growth of the money supply. IOR is a modern tool used to influence the federal funds rate.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 364, question: "The required reserve ratio is 25%. A bank has $40,000 in deposits and is exactly meeting its reserve requirement with no excess reserves. The Fed then lowers the required reserve ratio to 20%. How much in excess reserves does the bank now have, holding deposits constant?", options: ["$2,000","$8,000","$10,000","$1,000"], correctAnswer: 0, explanation: "Originally required reserves = 0.25 × $40,000 = $10,000, which the bank holds exactly. After the ratio falls to 20%, required reserves = 0.20 × $40,000 = $8,000. Since the bank still holds $10,000 in reserves, it now has $10,000 − $8,000 = $2,000 in excess reserves available to lend. The $8,000 and $10,000 choices report required reserves at the two ratios rather than the difference.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 365, question: "Which of the following best distinguishes the DISCOUNT RATE from the FEDERAL FUNDS RATE?", options: ["The discount rate is what banks charge each other; the federal funds rate is what the Fed charges banks","The discount rate is what the Fed charges banks borrowing from it; the federal funds rate is what banks charge each other for overnight loans","Both rates are set directly by Congress","The federal funds rate applies only to consumer mortgages"], correctAnswer: 1, explanation: "The discount rate is the interest rate the Fed charges commercial banks that borrow reserves directly from the discount window. The federal funds rate is the market-determined rate banks charge one another for overnight loans of reserves; the Fed influences it through open market operations. The first choice reverses the two definitions.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 366, question: "Suppose the money supply grows at 7% per year, real output grows at 3% per year, and the velocity of money is constant. According to the quantity theory of money, what is the approximate annual inflation rate?", options: ["10%","7%","21%","4%"], correctAnswer: 3, explanation: "In growth-rate form, %ΔM + %ΔV ≈ %ΔP + %ΔQ. With %ΔV = 0, inflation %ΔP ≈ %ΔM − %ΔQ = 7% − 3% = 4%. Adding the rates (10%) or using money growth alone (7%) misapplies the equation, and 21% incorrectly multiplies the two growth rates.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 367, question: "A central bank raises its policy interest rate to fight inflation. In an open economy with flexible exchange rates, which additional channel reinforces the contractionary effect on aggregate demand?", options: ["Higher rates attract financial inflows, the currency appreciates, net exports fall","Higher rates cause the currency to depreciate, net exports rise","Higher rates have no effect on the exchange rate","Higher rates increase exports by lowering domestic prices immediately"], correctAnswer: 0, explanation: "Higher domestic interest rates attract foreign financial capital, increasing demand for the domestic currency and causing it to appreciate. A stronger currency makes exports more expensive and imports cheaper, reducing net exports and reinforcing the decline in aggregate demand. The other options reverse the exchange-rate or trade response.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 368, question: "On a correctly drawn money market graph, the money DEMAND curve slopes downward primarily because:", options: ["The Fed sets money demand directly","As the nominal interest rate rises, the opportunity cost of holding money increases, so people hold less money","Higher interest rates increase the money supply","Money demand depends only on the price level, not the interest rate"], correctAnswer: 1, explanation: "The nominal interest rate is the opportunity cost of holding non-interest-bearing money instead of interest-bearing assets like bonds. When the interest rate rises, that opportunity cost rises and people economize on money holdings, so the quantity of money demanded falls. This gives money demand its negative slope. The level of money demand also shifts with the price level and real GDP, but the slope reflects the interest-rate trade-off.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 369, question: "A bank receives a new deposit of $1,000 and the required reserve ratio is 10%. Through the entire banking system, what is the maximum amount of NEW loans the system can create from this deposit (excluding the original $1,000 deposit itself)?", options: ["$10,000","$900","$9,000","$1,000"], correctAnswer: 2, explanation: "The first bank must hold 10% × $1,000 = $100 in reserves, leaving $900 in excess reserves to lend. As that loan is spent, redeposited, and re-lent through the system, total new loans equal the initial excess reserves times the multiplier: $900 × (1/0.10) = $900 × 10 = $9,000. The $10,000 figure is the change in total deposits including the original $1,000, and $900 is only the first loan.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 370, question: "The economy is in a recession. The Fed conducts expansionary monetary policy, but a year later output has barely responded. Which explanation involving policy LAGS is most consistent with this outcome?", options: ["Monetary policy works instantly, so lags cannot be the cause","Open market operations require new legislation, creating long delays","Monetary policy affects only the price level and never real output","There are recognition, implementation, and impact lags, so changes in interest rates affect investment and spending only gradually"], correctAnswer: 3, explanation: "Monetary policy is subject to lags. Although implementation through open market operations is relatively fast, the impact lag is long: lower interest rates influence investment, durable purchases, and spending only over many months as projects and plans adjust. This can delay the effect on real GDP. Unlike fiscal policy, monetary policy does not require new legislation.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 371, question: "Bank A has $50,000 in checkable deposits, holds $12,000 in total reserves, and the required reserve ratio is 20%. The Fed then conducts an open market PURCHASE that adds $3,000 in reserves to Bank A. What are Bank A's excess reserves immediately after this purchase?", options: ["$5,000","$2,000","$15,000","$10,000"], correctAnswer: 0, explanation: "Required reserves = 0.20 × $50,000 = $10,000. Before the purchase, excess reserves = $12,000 − $10,000 = $2,000. The open market purchase adds $3,000 in reserves with no new deposit, so new excess reserves = $2,000 + $3,000 = $5,000. The $2,000 figure ignores the purchase, and $10,000 is required reserves.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 372, question: "Which statement correctly describes the relationship between bond PRICES and interest rates that underlies open market operations?", options: ["When the Fed buys bonds, bond prices fall and interest rates fall","When the Fed buys bonds, bond prices rise and interest rates fall","When the Fed buys bonds, bond prices rise and interest rates rise","Bond prices and interest rates always move in the same direction"], correctAnswer: 1, explanation: "Bond prices and interest rates move inversely. When the Fed buys bonds, the increased demand pushes bond prices up, which lowers their effective yield (interest rate). This is consistent with expansionary policy, where buying bonds increases reserves and lowers interest rates. The remaining options either get the inverse relationship wrong or pair the wrong directions.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 373, question: "A central bank targets a 2% inflation rate. Inflation rises to 5% while unemployment is at its natural rate. Which policy response is appropriate, and what is the expected short-run effect on real GDP?", options: ["Expansionary policy: buy bonds; real GDP rises","Contractionary policy: buy bonds; real GDP rises","Contractionary policy: sell bonds; real GDP falls in the short run","No action is possible through monetary policy"], correctAnswer: 2, explanation: "With inflation above target and the economy already at the natural rate of unemployment (likely in an inflationary gap), the bank should tighten. Selling bonds drains reserves, raises interest rates, and reduces interest-sensitive spending, shifting aggregate demand left. In the short run this lowers real GDP and eases inflation. Buying bonds would be expansionary and worsen inflation.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 374, question: "Two economies are identical except that Economy X has a required reserve ratio of 5% and Economy Y has a required reserve ratio of 25%. The same $1,000 open market purchase is conducted in each. How do the maximum money supply changes compare?", options: ["Economy X expands by $4,000; Economy Y expands by $20,000","Both expand by the same amount because the purchase is identical","Economy X expands by $5,000; Economy Y expands by $25,000","Economy X expands by $20,000; Economy Y expands by $4,000"], correctAnswer: 3, explanation: "The multiplier is 1/reserve ratio. Economy X: 1/0.05 = 20, so $1,000 × 20 = $20,000. Economy Y: 1/0.25 = 4, so $1,000 × 4 = $4,000. A lower reserve ratio produces a larger multiplier and a larger money expansion. The reversed choice swaps the two economies.", difficulty: "medium", topicSlug: "macro-monetary-policy" },
  { id: 375, question: "Which of the following is the MOST direct goal of contractionary monetary policy?", options: ["To reduce inflationary pressure by decreasing the money supply and raising interest rates","To increase the money supply and lower interest rates","To increase government spending and cut taxes","To reduce the national debt directly by retiring bonds"], correctAnswer: 0, explanation: "Contractionary monetary policy aims to reduce inflationary pressure. The central bank decreases the money supply (for example by selling bonds), which raises interest rates, reduces interest-sensitive spending, and shifts aggregate demand left. Increasing government spending and cutting taxes are fiscal tools, not monetary policy.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 376, question: "An economy has a money supply of $1,000 billion and velocity of 6, so nominal GDP is $6,000 billion. The central bank wants nominal GDP to reach $7,200 billion, and velocity is expected to stay constant. By approximately how much must the money supply increase?", options: ["$1,200 billion","$200 billion","$1,200 billion divided by 6","$7,200 billion"], correctAnswer: 1, explanation: "From MV = PQ with V = 6 constant, the required money supply is M = nominal GDP / V = 7,200 / 6 = $1,200 billion. Since the money supply is currently $1,000 billion, it must rise by 1,200 − 1,000 = $200 billion. The $1,200 billion choice gives the new level rather than the change.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 377, question: "When the Fed conducts an open market sale of securities, which set of effects on bank reserves, the money supply, and aggregate demand is correct?", options: ["Reserves rise, money supply rises, AD shifts right","Reserves fall, money supply rises, AD shifts right","Reserves fall, money supply falls, AD shifts left","Reserves rise, money supply falls, AD shifts left"], correctAnswer: 2, explanation: "An open market sale removes reserves from the banking system as buyers pay the Fed. With fewer reserves, banks contract lending and the money supply falls. Higher interest rates reduce interest-sensitive spending, shifting aggregate demand left. This is contractionary policy. The other options mix incompatible directions.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 378, question: "A student claims that the Fed's three traditional tools are 'open market operations, the discount rate, and income tax rates.' Which correction is accurate?", options: ["The statement is correct as written","The discount rate is a fiscal tool and should be removed","Open market operations are a fiscal tool controlled by Congress","Income tax rates are a fiscal policy tool set by the legislature, not a monetary tool; the third traditional tool is the reserve requirement"], correctAnswer: 3, explanation: "The Fed's traditional monetary policy tools are open market operations, the discount rate, and the reserve requirement (with interest on reserves as a modern addition). Income tax rates are a fiscal policy tool determined by the legislature, not the central bank, so they do not belong on the list. The discount rate and open market operations are correctly classified as monetary tools.", difficulty: "easy", topicSlug: "macro-monetary-policy" },
  { id: 379, question: "Following an expansionary open market operation, the nominal interest rate falls from 5% to 3%. On a graph of the investment-demand (loanable funds) relationship, what is the expected effect on planned investment and the corresponding movement?", options: ["Planned investment falls; a leftward shift of investment demand","Planned investment is unchanged; investment is not interest-sensitive","Planned investment rises; a movement down along the investment demand curve","Planned investment rises; a rightward shift of the investment demand curve"], correctAnswer: 2, explanation: "A lower interest rate reduces the cost of borrowing, so more investment projects become profitable and planned investment rises. Because the change is caused by a movement in the interest rate (not a change in expected returns or other determinants), this is a movement DOWN ALONG a fixed downward-sloping investment demand curve, not a shift of the curve.", difficulty: "hard", topicSlug: "macro-monetary-policy" },
  { id: 380, question: "An economy is operating below full employment in a recession. Which of the following is the most appropriate discretionary fiscal policy to close the recessionary gap?", options: ["Increase government spending on infrastructure","Raise income tax rates on households","Increase the required reserve ratio for banks","Sell government bonds on the open market"], correctAnswer: 0, explanation: "A recessionary gap calls for expansionary fiscal policy to raise aggregate demand. Increasing government spending directly adds to AD. Raising taxes is contractionary. Changing the reserve ratio and conducting open-market operations are monetary policy tools controlled by the central bank, not fiscal policy tools controlled by the legislature.", difficulty: "easy", topicSlug: "macro-fiscal-policy-tools" },
  { id: 381, question: "The marginal propensity to consume (MPC) in an economy is 0.8. If the government increases its spending by $50 billion, by how much will real GDP change once the multiplier process is complete, holding other factors constant?", options: ["$62.5 billion increase","$250 billion increase","$40 billion increase","$200 billion increase"], correctAnswer: 1, explanation: "The spending multiplier is 1/(1 − MPC) = 1/(1 − 0.8) = 1/0.2 = 5. The change in real GDP = multiplier × change in spending = 5 × $50 billion = $250 billion. The distractor $200 billion forgets the initial injection by using MPC/(1−MPC), and $62.5 billion incorrectly uses 1.25 as the multiplier.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 382, question: "A government wants to increase real GDP by $300 billion to reach full employment. If the marginal propensity to save (MPS) is 0.25, how much should the government increase its spending, assuming no crowding out?", options: ["$300 billion","$1,200 billion","$75 billion","$240 billion"], correctAnswer: 2, explanation: "The spending multiplier = 1/MPS = 1/0.25 = 4. To achieve a $300 billion increase, required spending = $300 billion ÷ 4 = $75 billion. The distractor $1,200 billion mistakenly multiplies rather than divides by the multiplier.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 383, question: "The MPC is 0.75. The government wants to use a tax cut to increase aggregate demand. By how much must taxes be cut to raise real GDP by $90 billion, assuming the full multiplier effect?", options: ["$22.5 billion tax cut","$90 billion tax cut","$120 billion tax cut","$30 billion tax cut"], correctAnswer: 3, explanation: "The tax multiplier = −MPC/(1 − MPC) = −0.75/0.25 = −3 (magnitude 3). Required tax change = desired GDP change ÷ tax multiplier = $90 billion ÷ 3 = $30 billion cut. Using the spending multiplier of 4 (giving $22.5 billion) is the common error, but tax changes work through the smaller tax multiplier.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 384, question: "Which of the following best describes an automatic stabilizer in the federal budget?", options: ["Congress passing a new stimulus bill after a recession begins","Unemployment insurance payments rising automatically during a recession","The central bank lowering the policy interest rate","A one-time tax rebate approved during an economic downturn"], correctAnswer: 1, explanation: "Automatic stabilizers change without new legislation as the economy moves through the business cycle. Unemployment insurance increases automatically when unemployment rises, cushioning the downturn. A new stimulus bill and a one-time tax rebate are discretionary fiscal policy, and lowering the interest rate is monetary policy.", difficulty: "easy", topicSlug: "macro-fiscal-policy-tools" },
  { id: 385, question: "A progressive income tax system acts as an automatic stabilizer. During an economic expansion with rising incomes, how does it affect the economy without any new legislation?", options: ["Tax revenue falls, boosting aggregate demand further","Tax revenue stays constant as a share of GDP","Tax revenue rises faster than income, restraining aggregate demand","Government spending automatically rises with income"], correctAnswer: 2, explanation: "Under a progressive tax, as incomes rise during an expansion, people move into higher brackets and tax revenue grows faster than income. This automatically pulls spending power out of the economy, dampening the boom and helping prevent overheating, all without new legislation.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 386, question: "An economy is experiencing demand-pull inflation while operating above full-employment output. Which combination of fiscal actions would most effectively reduce the inflationary gap?", options: ["Increase government spending and decrease taxes","Decrease government spending and decrease taxes","Increase transfer payments and decrease taxes","Decrease government spending and increase taxes"], correctAnswer: 3, explanation: "An inflationary gap requires contractionary fiscal policy to reduce aggregate demand. Decreasing government spending lowers AD directly, and increasing taxes reduces disposable income and consumption. Options that cut taxes or raise spending are expansionary and would worsen the inflation.", difficulty: "easy", topicSlug: "macro-fiscal-policy-tools" },
  { id: 387, question: "The government simultaneously increases both spending and taxes by $40 billion each. If the MPC is 0.8, what is the predicted change in real GDP from this balanced-budget policy?", options: ["$40 billion increase","$0, the effects exactly cancel","$200 billion increase","$160 billion increase"], correctAnswer: 0, explanation: "Spending multiplier = 1/(1−0.8) = 5, so $40B × 5 = +$200B. Tax multiplier = −0.8/0.2 = −4, so $40B tax increase gives $40B × (−4) = −$160B. Net = $200B − $160B = +$40B. This illustrates the balanced-budget multiplier of 1: equal increases in spending and taxes raise GDP by the amount of the change.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 388, question: "When the government finances a budget deficit by borrowing heavily in financial (loanable funds) markets, what is the most likely short-run consequence known as 'crowding out'?", options: ["Lower real interest rates that increase private investment","An increase in the money supply controlled by the central bank","Higher real interest rates that reduce private investment","A decrease in the price level due to lower demand for goods"], correctAnswer: 2, explanation: "Government borrowing increases demand for loanable funds, pushing the real interest rate up. Higher interest rates discourage private investment (and interest-sensitive consumption), partially offsetting the expansionary effect of the deficit spending. This reduction in private investment is the crowding-out effect.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 389, question: "A nation's GDP is $2,000 billion. Its government spending is $500 billion and tax revenue is $420 billion. What is the budget balance, and how would it be classified?", options: ["An $80 billion surplus","A $920 billion deficit","A balanced budget of $0","An $80 billion deficit"], correctAnswer: 3, explanation: "The budget balance = tax revenue − government spending = $420B − $500B = −$80B. A negative balance means spending exceeds revenue, so the government runs an $80 billion deficit. The $920 billion figure incorrectly adds the two values instead of subtracting.", difficulty: "easy", topicSlug: "macro-fiscal-policy-tools" },
  { id: 390, question: "A country ran budget deficits of $100 billion, $150 billion, and a surplus of $50 billion over three consecutive years, starting from zero accumulated debt. What is the national debt at the end of the three years?", options: ["$200 billion","$300 billion","$100 billion","$50 billion"], correctAnswer: 0, explanation: "The national debt is the accumulation of annual deficits minus surpluses. Deficits add to debt and surpluses reduce it: $100B + $150B − $50B = $200B. This distinguishes the debt (a stock) from the annual deficit (a flow); summing only the deficits ($250B) ignores the surplus.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 391, question: "Suppose the MPC is 0.9 and the government increases transfer payments by $20 billion. Compared with an equal increase in direct government purchases, the effect on real GDP from the transfer payment increase is:", options: ["Larger, because transfers are spent fully","Smaller, because the first round depends on the MPC","Identical, because both use the spending multiplier","Zero, because transfers do not affect aggregate demand"], correctAnswer: 1, explanation: "Government purchases enter aggregate demand directly and in full in the first round. Transfer payments only raise disposable income; households spend a fraction (the MPC) and save the rest, so the first-round injection is MPC × $20B. The transfer multiplier (MPC/(1−MPC)) is smaller than the spending multiplier (1/(1−MPC)), so the transfer's effect is smaller.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 392, question: "An economy has a recessionary gap of $400 billion. Policymakers know the MPC is 0.6 but expect that crowding out will offset 25% of the intended fiscal stimulus. Roughly how much must government spending increase to close the gap?", options: ["About $160 billion","About $400 billion","About $120 billion","About $213 billion"], correctAnswer: 3, explanation: "Spending multiplier = 1/(1−0.6) = 2.5. Without crowding out, required spending = $400B/2.5 = $160B. But crowding out cuts the effect to 75% of intended, so the effective multiplier is 2.5 × 0.75 = 1.875. Required spending = $400B/1.875 ≈ $213B. The $160B answer ignores crowding out.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 393, question: "Which scenario best illustrates a contractionary fiscal policy enacted through the tax side of the budget?", options: ["The legislature raises the corporate income tax rate to cool an overheating economy","The central bank raises the federal funds rate target","The government increases spending on defense procurement","Unemployment benefits automatically decline as employment rises"], correctAnswer: 0, explanation: "Contractionary fiscal policy reduces aggregate demand. Raising the corporate income tax rate is a deliberate (discretionary) tax change by the legislature that lowers after-tax income and investment. Raising the federal funds rate is monetary policy, increased spending is expansionary, and the decline in unemployment benefits is an automatic stabilizer rather than a discretionary tax action.", difficulty: "easy", topicSlug: "macro-fiscal-policy-tools" },
  { id: 394, question: "In the AD/AS model, an economy is at long-run equilibrium at potential output. The government then enacts a large unfunded tax cut. In the short run, what happens to the price level and real output?", options: ["The price level rises and real output falls","Both the price level and real output rise","Both the price level and real output fall","The price level falls and real output rises"], correctAnswer: 1, explanation: "A tax cut raises disposable income and consumption, shifting aggregate demand to the right. Starting from full employment, the rightward AD shift moves the economy along the short-run aggregate supply curve, raising both the price level and real output above potential, creating an inflationary gap in the short run.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 395, question: "A government uses expansionary fiscal policy during a recession. According to the loanable funds market, if the policy is debt-financed, which graphical change best represents the crowding-out effect?", options: ["Supply of loanable funds shifts right, lowering the real interest rate","Demand for loanable funds shifts left, lowering the real interest rate","Demand for loanable funds shifts right, raising the real interest rate","Supply of loanable funds shifts left, raising the nominal exchange rate"], correctAnswer: 2, explanation: "When the government borrows to finance deficit spending, it adds to the demand for loanable funds, shifting that curve rightward. This raises the equilibrium real interest rate, which discourages private investment, the essence of crowding out.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 396, question: "The MPC is 0.75. The government increases spending by $80 billion and simultaneously raises taxes by $20 billion. What is the net change in real GDP?", options: ["$260 billion increase","$320 billion increase","$60 billion increase","$240 billion increase"], correctAnswer: 0, explanation: "Spending multiplier = 1/(1−0.75) = 4, so $80B × 4 = +$320B. Tax multiplier = −0.75/0.25 = −3, so $20B tax increase gives $20B × (−3) = −$60B. Net change = $320B − $60B = +$260B. The $320B distractor ignores the tax increase entirely.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 397, question: "Why does the tax multiplier have a smaller absolute value than the government spending multiplier for the same MPC?", options: ["Tax changes are always offset by automatic stabilizers","A tax change first affects disposable income, so only the MPC fraction is spent initially","Government spending is taxed before it enters the economy","The tax multiplier excludes the saving leakage entirely"], correctAnswer: 1, explanation: "A dollar of government spending enters aggregate demand fully in the first round. A dollar of tax cut, however, raises disposable income, of which households spend only the MPC fraction and save the rest. Because the initial injection is smaller (MPC × the tax change), the tax multiplier MPC/(1−MPC) is smaller than the spending multiplier 1/(1−MPC).", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 398, question: "An economy has full-employment output of $5,000 billion but is currently producing $4,700 billion. The MPC is 0.8. Ignoring crowding out, what increase in government purchases would bring the economy to full employment?", options: ["$300 billion","$240 billion","$60 billion","$375 billion"], correctAnswer: 2, explanation: "The output gap = $5,000B − $4,700B = $300B. The spending multiplier = 1/(1−0.8) = 5. Required spending increase = $300B ÷ 5 = $60B. The $300B distractor confuses the gap itself with the required spending; the $375B uses the wrong multiplier.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 399, question: "A budget deficit financed by selling bonds to foreign investors leads to capital inflows. In the foreign exchange market for the domestic currency, what is the most likely short-run effect of the higher domestic interest rates?", options: ["The domestic currency depreciates as supply of it rises","The exchange rate is unaffected by interest rate changes","Net exports increase due to a weaker currency","The domestic currency appreciates as foreign demand for it rises"], correctAnswer: 3, explanation: "Higher domestic real interest rates from deficit financing attract foreign financial capital. Foreign investors demand the domestic currency to buy domestic bonds, increasing demand for that currency and causing it to appreciate. The stronger currency then tends to reduce net exports, a key open-economy link.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 400, question: "Which of the following describes a structural (full-employment) budget deficit rather than a cyclical deficit?", options: ["A deficit caused entirely by falling tax revenue during a recession","A deficit that would persist even if the economy were at full employment","A deficit that disappears once automatic stabilizers reverse in an expansion","A deficit equal to the change in the national debt during a downturn"], correctAnswer: 1, explanation: "A structural deficit reflects the budget's underlying stance, the deficit that would remain even at full employment, independent of the business cycle. A cyclical deficit arises from the economy operating below potential (lower revenues, higher transfers) and shrinks as the economy recovers.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 401, question: "The government cuts taxes by $50 billion. If the resulting increase in real GDP is $150 billion, what is the implied MPC?", options: ["0.50","0.67","0.75","0.25"], correctAnswer: 2, explanation: "The tax multiplier = GDP change ÷ tax change = $150B ÷ $50B = 3 (in magnitude). The tax multiplier formula is MPC/(1−MPC) = 3, so MPC = 3(1−MPC) → MPC = 3 − 3·MPC → 4·MPC = 3 → MPC = 0.75. Confirming: tax multiplier = 0.75/0.25 = 3. An MPC of 0.5 would give a tax multiplier of only 1.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 402, question: "During a severe recession, a government dramatically increases deficit spending, but private investment barely changes despite the larger deficit. Which condition best explains the weak crowding-out effect?", options: ["The economy is at full employment with no slack","The central bank is selling bonds to drain reserves","Households have an MPC near zero","There is substantial idle capacity and saving, so interest rates rise little"], correctAnswer: 3, explanation: "Crowding out depends on how much the real interest rate rises when the government borrows. In a deep recession with idle resources and abundant saving, the demand for loanable funds can rise without pushing interest rates up much, so private investment is barely reduced. At full employment, by contrast, crowding out tends to be strong.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 403, question: "Which of the following correctly pairs a fiscal policy lag with its description?", options: ["Recognition lag: the time before policymakers realize a downturn has begun","Recognition lag: the time it takes for spending changes to affect GDP","Implementation lag: the delay caused by gathering economic data","Impact lag: the time legislators spend debating and passing a bill"], correctAnswer: 0, explanation: "The recognition lag is the delay before policymakers identify that the economy needs intervention, because data arrive with a delay. The implementation (legislative) lag is the time to enact policy, and the impact lag is the time for the policy to affect the economy. Only the first pairing is correctly matched.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 404, question: "An economy has an inflationary gap of $120 billion. The MPC is 0.6. By how much should the government cut its spending to eliminate the gap, assuming no crowding out?", options: ["$120 billion","$72 billion","$48 billion","$300 billion"], correctAnswer: 2, explanation: "The spending multiplier = 1/(1−0.6) = 2.5. Required spending cut = gap ÷ multiplier = $120B ÷ 2.5 = $48B. The $300B distractor multiplies instead of dividing, and $120B mistakes the gap for the required spending change.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 405, question: "A legislature passes a stimulus package, but by the time the spending actually reaches the economy, output has already recovered to full employment. What is the most likely unintended consequence?", options: ["The stimulus has no effect because the multiplier is now zero","The stimulus permanently lowers the price level","The stimulus reduces the national debt through higher growth","The stimulus becomes procyclical and pushes the economy into an inflationary gap"], correctAnswer: 3, explanation: "Because of fiscal policy lags, a stimulus can arrive after the economy has already self-corrected. Adding aggregate demand at full employment is procyclical, pushing output above potential and creating an inflationary gap, the opposite of stabilization. This is a key argument against relying solely on discretionary fiscal policy.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 406, question: "A government increases spending by $100 billion. The income tax system takes 20 cents of every additional dollar of income, and the MPC out of disposable income is 0.9. The presence of the income tax does what to the spending multiplier?", options: ["Reduces it because taxes are an additional leakage from the spending stream","Increases it because taxes raise government revenue","Leaves it unchanged because the MPC is what matters","Eliminates it entirely because all income is taxed"], correctAnswer: 0, explanation: "An income tax creates a leakage: part of each dollar of new income is taxed away and not available for consumption. This reduces the size of each successive spending round, shrinking the multiplier compared with a no-tax economy. Income (proportional) taxes therefore act as automatic stabilizers by damping the multiplier.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 407, question: "Country X has a national debt of $900 billion and nominal GDP of $3,000 billion. After a year of strong growth, nominal GDP rises to $3,600 billion while the debt is unchanged. What happens to the debt-to-GDP ratio?", options: ["It rises from 30% to 25%","It falls from 30% to 25%","It stays constant at 30%","It falls from 30% to 20%"], correctAnswer: 1, explanation: "Initial ratio = $900B/$3,000B = 0.30 = 30%. New ratio = $900B/$3,600B = 0.25 = 25%. Even with the debt level unchanged, faster GDP growth lowers the debt-to-GDP ratio. This shows why the ratio, not the absolute debt, is often used to judge debt sustainability.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 408, question: "Suppose expansionary fiscal policy raises real interest rates and causes the domestic currency to appreciate. Which secondary effect partly offsets the increase in aggregate demand in an open economy?", options: ["An increase in net exports as imports become cheaper to foreigners","A rise in private investment due to lower interest rates","A decrease in the price level due to lower import prices","A decline in net exports as exports become more expensive abroad"], correctAnswer: 3, explanation: "Expansionary fiscal policy can raise interest rates, attract foreign capital, and appreciate the currency. A stronger currency makes domestic exports more expensive abroad and imports cheaper, reducing net exports. This 'net export effect' (a form of international crowding out) partially offsets the stimulus to aggregate demand.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 409, question: "The government is choosing between a $60 billion increase in spending and a $60 billion tax cut, with an MPC of 0.8. Which statement correctly compares the two policies' impact on real GDP?", options: ["The spending increase raises GDP more than the tax cut does","The tax cut raises GDP more than the spending increase does","Both raise GDP by exactly the same amount","Neither affects GDP because they cost the same"], correctAnswer: 0, explanation: "Spending multiplier = 5, so $60B spending → +$300B. Tax multiplier = 0.8/0.2 = 4, so $60B tax cut → +$240B. For equal dollar amounts, the spending increase produces a larger GDP effect because the entire amount enters AD directly, whereas a tax cut is partly saved in the first round.", difficulty: "medium", topicSlug: "macro-fiscal-policy-tools" },
  { id: 410, question: "An economy's aggregate demand is described by the relationship that each $1 of new autonomous spending eventually generates $4 of GDP. If the government wants to AVOID changing the budget balance while still increasing GDP by $80 billion, which policy works, given this multiplier and a tax multiplier of magnitude 3?", options: ["Increase spending by $20 billion only","Cut taxes by $80 billion only","Increase both spending and taxes by $80 billion","Increase spending by $80 billion and cut taxes by $80 billion"], correctAnswer: 2, explanation: "A balanced-budget change keeps the budget balance unchanged. Raising spending and taxes equally by $80B: spending effect = 4 × $80B = +$320B; tax effect = −3 × $80B = −$240B; net = +$80B. The balanced-budget multiplier equals 1, so the GDP increase equals the $80B change. The other options either change the budget balance or give the wrong magnitude.", difficulty: "hard", topicSlug: "macro-fiscal-policy-tools" },
  { id: 411, question: "The nation of Aurelia has an adult population of 250 million. Of these, 50 million are not in the labor force, 180 million are employed, and the rest are unemployed. What is Aurelia's unemployment rate (rounded to one decimal place)?", options: ["8.0%","11.1%","20.0%","10.0%"], correctAnswer: 3, explanation: "The labor force = employed + unemployed = adult population minus those not in the labor force = 250 - 50 = 200 million. Unemployed = labor force - employed = 200 - 180 = 20 million. Unemployment rate = unemployed / labor force = 20 / 200 = 10.0%. The 8.0% distractor mistakenly divides unemployed by the full adult population (20/250). The 11.1% divides unemployed by employed, and 20.0% confuses the count with the rate.", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 412, question: "In Brevia, the working-age population is 80 million. There are 48 million employed workers and 6 million unemployed workers actively seeking jobs. What is the labor force participation rate?", options: ["60.0%","67.5%","75.0%","85.0%"], correctAnswer: 1, explanation: "Labor force = employed + unemployed = 48 + 6 = 54 million. Labor force participation rate = labor force / working-age population = 54 / 80 = 0.675 = 67.5%. The 60.0% distractor uses only the employed (48/80), omitting the unemployed from the labor force. The 75.0% and 85.0% distractors come from incorrectly inflating the labor force figure.", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 413, question: "A worker who was laid off from an automobile factory because consumers shifted to buying foreign cars, and whose skills no longer match available job openings in her region, is BEST classified as experiencing which type of unemployment?", options: ["Frictional unemployment","Cyclical unemployment","Structural unemployment","Seasonal unemployment"], correctAnswer: 2, explanation: "Structural unemployment occurs when there is a mismatch between workers' skills (or locations) and the jobs available, often due to permanent changes in the economy such as shifts in consumer demand or technology. Frictional unemployment is temporary job-search unemployment. Cyclical unemployment results from a downturn in the business cycle (insufficient aggregate demand). Seasonal unemployment relates to predictable time-of-year fluctuations.", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 414, question: "During a severe recession, total measured unemployment rises sharply. Which component of the unemployment rate increases the MOST as a direct result of the falling level of real GDP?", options: ["Frictional unemployment","Structural unemployment","Cyclical unemployment","The natural rate of unemployment"], correctAnswer: 2, explanation: "Cyclical unemployment is the portion of unemployment caused by a downturn in the business cycle—when real GDP falls below potential and aggregate demand is insufficient, firms lay off workers. Frictional and structural unemployment together make up the natural rate, which is relatively stable over the business cycle. The natural rate does not rise simply because real GDP falls.", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 415, question: "An economy has 4% frictional unemployment, 1% seasonal unemployment, 2% structural unemployment, and 3% cyclical unemployment. Assuming the natural rate consists of frictional and structural unemployment, what is the natural rate of unemployment?", options: ["6%","5%","9%","10%"], correctAnswer: 0, explanation: "The natural rate of unemployment is the sum of frictional and structural unemployment: 4% + 2% = 6%. Cyclical unemployment (3%) is excluded because it reflects the business cycle, not the natural rate. The 5% answer omits structural unemployment, 9% incorrectly adds cyclical unemployment to the natural rate, and 10% adds everything together.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 416, question: "A discouraged worker who has given up actively searching for a job during a prolonged recession decides to stop looking entirely. Holding all else constant, how does this single person's decision affect the measured unemployment rate and the labor force participation rate?", options: ["Both the unemployment rate and the participation rate rise.","The unemployment rate rises and the participation rate falls.","The unemployment rate falls and the participation rate rises.","The unemployment rate falls and the participation rate falls."], correctAnswer: 3, explanation: "A discouraged worker who stops searching is no longer counted as unemployed and leaves the labor force entirely. Removing this person from the unemployed count (numerator) lowers the unemployment rate. Removing them from the labor force lowers the participation rate. This is why the official unemployment rate can understate labor-market weakness: discouraged workers exiting the labor force mechanically reduce the measured rate.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 417, question: "A consumer price index (CPI) market basket is fixed. The basket cost $200 in the base year and $230 in the current year. What is the CPI in the current year, and what does it indicate about prices since the base year?", options: ["CPI = 115; prices rose 15% since the base year.","CPI = 130; prices rose 30% since the base year.","CPI = 30; prices rose 30% since the base year.","CPI = 86.96; prices fell since the base year."], correctAnswer: 0, explanation: "CPI = (cost of basket in current year / cost of basket in base year) x 100 = (230 / 200) x 100 = 115. Because the base-year CPI is defined as 100, a current CPI of 115 means prices have risen 15% since the base year. The 130 answer incorrectly adds 100 to a percentage change, and 86.96 inverts the ratio (200/230).", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 418, question: "The CPI was 150 at the end of 2024 and 159 at the end of 2025. What was the inflation rate during 2025?", options: ["6.0%","5.7%","9.0%","59.0%"], correctAnswer: 0, explanation: "The inflation rate equals the percentage change in the CPI: (159 - 150) / 150 x 100 = 9 / 150 x 100 = 6.0%. The 5.7% answer mistakenly divides by the newer index (9/159). The 9.0% answer reports the raw point change rather than the percentage change, and 59.0% subtracts 100 from the new index.", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 419, question: "A union negotiates a contract giving workers a 7% nominal wage increase for the coming year. Over that same year, the inflation rate turns out to be 4%. Using the approximation that real wage growth equals nominal growth minus inflation, how did workers' real wages change?", options: ["Real wages fell by about 3%.","Real wages rose by about 11%.","Real wages were unchanged.","Real wages rose by about 3%."], correctAnswer: 3, explanation: "The approximate real wage change equals the nominal wage change minus the inflation rate: 7% - 4% = +3%. Because the nominal raise exceeded inflation, workers' purchasing power rose by roughly 3%. The 'fell by 3%' answer reverses the subtraction, and the +11% answer incorrectly adds the two rates.", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 420, question: "A bank issues a one-year loan at a nominal interest rate of 8%. Both the bank and the borrower expected inflation of 3% for the year, but actual inflation turned out to be 6%. Compared with what each party expected, who benefited from the unexpected inflation, and why?", options: ["The lender (bank) benefited because it collected a higher nominal return.","Neither party was affected because the nominal rate was fixed in advance.","Both parties benefited equally because inflation raises all incomes.","The borrower benefited because the real value of the repayment was lower than expected."], correctAnswer: 3, explanation: "When actual inflation (6%) exceeds expected inflation (3%), the realized real interest rate (8% - 6% = 2%) is lower than the expected real rate (8% - 3% = 5%). The borrower repays dollars worth less than anticipated, so the borrower gains and the lender loses. Unanticipated inflation systematically redistributes purchasing power from lenders to borrowers.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 421, question: "Nominal GDP in Calderia rose from $2.0 trillion in Year 1 to $2.2 trillion in Year 2. Over the same period, the GDP deflator rose from 100 to 104. Approximately what happened to real GDP between Year 1 and Year 2?", options: ["Real GDP fell by about 6%.","Real GDP rose by about 10%.","Real GDP was unchanged.","Real GDP rose by about 6%."], correctAnswer: 3, explanation: "Real GDP = (nominal GDP / GDP deflator) x 100. Year 1 real GDP = (2.0/100) x 100 = $2.0 trillion. Year 2 real GDP = (2.2/104) x 100 = $2.115 trillion. The percentage change = (2.115 - 2.0)/2.0 = about +5.8%, approximately +6%. Equivalently, real growth approximately equals nominal growth (10%) minus inflation (4%) = 6%. The +10% answer ignores inflation by using nominal figures.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 422, question: "Which of the following individuals would be counted as UNEMPLOYED in the official U.S. labor statistics?", options: ["A full-time college student who is not looking for work.","A retiree who volunteers 20 hours a week but is not seeking paid employment.","A laid-off factory worker who applied to three jobs last week.","A discouraged worker who wants a job but has stopped searching."], correctAnswer: 2, explanation: "To be counted as unemployed, a person must be without a job, available for work, and actively searching for work. The laid-off factory worker who applied to jobs meets all criteria. The student and retiree are not in the labor force (not seeking work), and the discouraged worker is also out of the labor force because they have stopped actively searching, even though they want a job.", difficulty: "easy", topicSlug: "macro-unemployment-inflation" },
  { id: 423, question: "A government statistician notes that a part-time barista who wants full-time work but cannot find it is counted as 'employed' in the official statistics. Why does this counting convention cause the official unemployment rate to potentially UNDERSTATE the degree of labor underutilization?", options: ["Because underemployed part-time workers are counted as fully employed, so their unmet desire for more work is not reflected in the rate.","Because part-time workers are counted as unemployed, inflating the rate.","Because part-time workers are excluded from the labor force entirely.","Because the official rate only counts salaried workers as employed."], correctAnswer: 0, explanation: "Anyone who works at least one hour for pay is counted as employed, even if they want full-time work but can only find part-time work. These underemployed workers are recorded as fully employed, so their underutilization is invisible in the headline unemployment rate. Along with discouraged workers, this is a key reason the official rate can understate true labor-market slack.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 424, question: "An economy is operating at its full-employment level of output. Economists describe the unemployment present at this point as the 'natural rate.' Which statement BEST characterizes the natural rate of unemployment?", options: ["It includes frictional and structural unemployment but not cyclical unemployment.","It is zero, because everyone who wants a job has one.","It includes only cyclical unemployment caused by recessions.","It is the highest unemployment rate the economy can reach during a depression."], correctAnswer: 0, explanation: "The natural rate of unemployment is the rate that exists when the economy produces at potential output (full employment). It consists of frictional unemployment (job search/transition) and structural unemployment (skills/location mismatch). It is not zero because some frictional and structural unemployment always exists. Cyclical unemployment is zero at full employment, so it is excluded from the natural rate.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 425, question: "The actual unemployment rate in Doria is 7%, while economists estimate the natural rate of unemployment is 5%. Based on this information, the economy is MOST likely:", options: ["Producing above potential output with an inflationary gap.","Producing below potential output with a recessionary gap.","Producing exactly at potential output with no output gap.","Experiencing only frictional unemployment."], correctAnswer: 1, explanation: "When the actual unemployment rate (7%) exceeds the natural rate (5%), there is positive cyclical unemployment (about 2 percentage points). Cyclical unemployment indicates the economy is producing below potential output, which corresponds to a recessionary gap. If unemployment were below the natural rate, the economy would have an inflationary gap; if equal, it would be at potential.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 426, question: "A retiree on a fixed nominal pension finds that her standard of living declines steadily over a decade of moderate inflation. This experience BEST illustrates which cost of inflation?", options: ["Menu costs imposed on businesses.","Shoe-leather costs from frequent bank trips.","The arbitrary redistribution of purchasing power away from those on fixed nominal incomes.","An increase in the real value of her savings."], correctAnswer: 2, explanation: "People who receive fixed nominal incomes (such as a pension not indexed to inflation) lose purchasing power as prices rise, because their income buys fewer goods each year. This is the redistributive cost of inflation: it shifts purchasing power away from those whose incomes do not keep pace with prices. Menu costs and shoe-leather costs are real but distinct costs and do not describe this fixed-income scenario.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 427, question: "The price of gasoline rose sharply this year because of a supply disruption, while the prices of most other goods in the CPI basket changed only modestly. Why might the CPI overstate the change in the typical consumer's cost of living in this situation, according to the substitution-bias critique?", options: ["Consumers buy more gasoline as its price rises, raising true costs.","The fixed CPI basket does not account for consumers substituting toward relatively cheaper goods when gasoline becomes expensive.","Gasoline is excluded from the CPI, so its rise is irrelevant.","The CPI is updated every month to reflect new purchases."], correctAnswer: 1, explanation: "Substitution bias arises because the CPI uses a fixed market basket. When the relative price of a good (gasoline) rises, consumers tend to buy less of it and substitute toward relatively cheaper alternatives. Because the fixed basket assumes unchanged quantities, it overweights the now-expensive good and overstates the increase in the true cost of living. This is one of several reasons the CPI may overstate inflation.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 428, question: "An economy experiences a sudden, sharp increase in the world price of oil, a key input for many firms. In the short run, how does this supply shock affect the price level and the unemployment rate simultaneously?", options: ["The price level falls and unemployment falls.","The price level rises and unemployment falls.","The price level falls and unemployment rises.","The price level rises and unemployment rises (stagflation)."], correctAnswer: 3, explanation: "A negative (adverse) supply shock such as a spike in oil prices raises production costs, shifting short-run aggregate supply leftward. This causes the price level to rise (inflation) and real output to fall, which increases unemployment. The simultaneous combination of rising prices and rising unemployment is called stagflation, and it is the defining feature of an adverse supply shock.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 429, question: "The short-run Phillips curve illustrates a relationship between inflation and unemployment. A movement along a given short-run Phillips curve from a point of high unemployment/low inflation to low unemployment/high inflation is MOST consistent with which underlying change in the aggregate demand–aggregate supply model?", options: ["A leftward shift of aggregate demand.","A rightward shift of aggregate demand.","A leftward shift of short-run aggregate supply.","A rightward shift of short-run aggregate supply."], correctAnswer: 1, explanation: "Movements along a single short-run Phillips curve reflect shifts in aggregate demand. A rightward (increasing) shift of aggregate demand raises the price level (higher inflation) and increases real output, lowering unemployment—moving the economy up and to the left along the SRPC. A leftward AD shift does the opposite. Supply shocks shift the entire Phillips curve rather than causing a movement along it.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 430, question: "According to the long-run Phillips curve, what is the relationship between inflation and unemployment in the long run, and where is the curve located?", options: ["It is downward sloping, showing a permanent inflation-unemployment trade-off.","It is horizontal at the natural rate of inflation.","It is upward sloping at potential output.","It is vertical at the natural rate of unemployment, showing no long-run trade-off."], correctAnswer: 3, explanation: "The long-run Phillips curve is vertical at the natural rate of unemployment. In the long run, the economy returns to its natural rate regardless of the inflation rate, because expectations adjust fully. This means there is no permanent trade-off between inflation and unemployment: policymakers cannot keep unemployment permanently below the natural rate by accepting higher inflation. The short-run trade-off exists only because expectations adjust slowly.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 431, question: "A central bank uses expansionary policy to push unemployment below the natural rate. Over time, workers and firms come to expect higher inflation and build it into wage and price decisions. According to the expectations-augmented Phillips curve, what is the long-run result of repeatedly trying to keep unemployment below the natural rate?", options: ["Permanently lower unemployment with stable inflation.","Unemployment returns to the natural rate but at a permanently higher inflation rate.","Both unemployment and inflation fall permanently.","The natural rate of unemployment falls to zero."], correctAnswer: 1, explanation: "When policymakers push unemployment below the natural rate, inflation rises. As people adjust their inflation expectations upward, the short-run Phillips curve shifts up, and unemployment returns to the natural rate—now paired with higher inflation. Repeating this process ratchets inflation higher while leaving unemployment unchanged in the long run. This is why the long-run Phillips curve is vertical at the natural rate.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 432, question: "An adverse supply shock, such as a sharp rise in energy prices, hits the economy. How does this event affect the SHORT-RUN Phillips curve, and what does the resulting position imply for policymakers?", options: ["The short-run Phillips curve shifts left (down), improving the inflation-unemployment trade-off.","The short-run Phillips curve shifts right (up), worsening the trade-off so that any given unemployment rate is paired with higher inflation.","The economy moves down along a fixed short-run Phillips curve.","The long-run Phillips curve becomes downward sloping."], correctAnswer: 1, explanation: "An adverse supply shock shifts the short-run Phillips curve outward (up and to the right), so that for any given unemployment rate, inflation is higher than before. This worsens the trade-off and confronts policymakers with stagflation: efforts to reduce inflation raise unemployment further, while efforts to reduce unemployment raise inflation. A favorable supply shock would shift the SRPC inward.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 433, question: "Country X is a small open economy. Last year nominal GDP grew 9% while the GDP deflator increased 7%, and the population grew 1%. Which statement about Country X's economic performance is MOST accurate?", options: ["Real GDP grew about 2%, and real GDP per capita grew about 1%.","Real GDP fell, so living standards declined.","Real GDP grew about 9%, the same as nominal GDP.","Real GDP per capita grew about 8%."], correctAnswer: 0, explanation: "Real GDP growth is approximately nominal GDP growth minus inflation: 9% - 7% = about 2%. Real GDP per capita growth is approximately real GDP growth minus population growth: 2% - 1% = about 1%. So real output grew about 2% and output per person grew about 1%. The 9% figure ignores inflation, and 8% incorrectly subtracts only population growth from nominal growth.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 434, question: "A nominal contract sets a worker's wage at $60,000 for next year. The worker and employer agreed to this figure expecting 2% inflation, but actual inflation comes in at 5%. Compared with their expectations, how is the worker's real wage affected, and who benefits from the forecasting error?", options: ["The worker's real wage is higher than expected; the worker benefits.","The worker's real wage is lower than expected; the employer benefits.","The real wage matches expectations; neither party is affected.","The employer's real labor cost is higher than expected; the worker benefits."], correctAnswer: 1, explanation: "With the nominal wage fixed, higher-than-expected inflation (5% vs. 2%) erodes the real value of the $60,000 more than anticipated. The worker's real wage is lower than expected, and the employer's real labor cost is lower than expected. Thus unanticipated inflation transfers purchasing power from the worker to the employer, who pays a fixed nominal wage worth less in real terms. The employer benefits from the error.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 435, question: "Suppose every nominal value in an economy—wages, prices, debts, and incomes—were perfectly and instantly indexed to a fully anticipated inflation rate. In this idealized case, which cost of inflation would STILL remain?", options: ["Arbitrary redistribution between borrowers and lenders.","Loss of real income for workers on fixed nominal wages.","Menu costs and shoe-leather costs.","All costs of inflation would disappear entirely."], correctAnswer: 2, explanation: "If inflation is fully anticipated and all contracts are indexed, the redistributive costs disappear because nominal values adjust automatically. However, menu costs (the resources used to change prices) and shoe-leather costs (the effort to economize on cash holdings that lose value) persist even when inflation is fully anticipated, because changing prices and minimizing cash holdings still consume real resources. Hence not all costs vanish.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 436, question: "An economist is comparing two job-market situations. In Situation A, a software engineer voluntarily quits to spend two months searching for a better-matched position. In Situation B, coal miners are permanently displaced when the country shifts to renewable energy and their skills are no longer demanded. Which classification correctly matches each situation?", options: ["A is structural; B is frictional.","A is cyclical; B is structural.","A is frictional; B is cyclical.","A is frictional; B is structural."], correctAnswer: 3, explanation: "Situation A is frictional unemployment: a voluntary, temporary period of job search as the worker transitions between jobs—a normal, often beneficial feature of a dynamic labor market. Situation B is structural unemployment: a lasting mismatch between workers' skills and available jobs caused by a permanent change in the economy's structure. Neither is cyclical, since cyclical unemployment stems from business-cycle downturns, not skill mismatches or voluntary search.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
  { id: 437, question: "In Year 1 the CPI is 120, and in Year 2 it is 126. A worker earned a nominal salary of $50,000 in Year 1 and $52,000 in Year 2. Using Year 1 as the reference for real values, did the worker's real salary rise or fall, and by approximately how much?", options: ["Real salary fell about 1% because inflation (5%) exceeded the nominal raise (4%).","Real salary rose about 4% because the nominal salary increased.","Real salary was unchanged because both rose by similar amounts.","Real salary fell about 5% because inflation was 5%."], correctAnswer: 0, explanation: "Inflation = (126 - 120)/120 = 5%. The nominal raise = (52,000 - 50,000)/50,000 = 4%. Real salary change is approximately nominal change minus inflation = 4% - 5% = about -1%. Equivalently, Year 2 real salary in Year 1 dollars = 52,000 x (120/126) = about $49,524, slightly below $50,000. The worker's purchasing power fell by roughly 1% because inflation outpaced the raise.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 438, question: "A country reports an unemployment rate that has fallen from 6% to 5% over the past year. However, the labor force participation rate also fell during the same period. An analyst cautions that the falling unemployment rate may not signal a healthier labor market. What is the BEST explanation for this caution?", options: ["Lower participation always means more people are employed.","The unemployment rate and participation rate are unrelated measures.","A falling unemployment rate guarantees rising real GDP.","Some unemployed workers may have become discouraged and left the labor force, lowering the unemployment rate without new jobs being created."], correctAnswer: 3, explanation: "If discouraged workers stop searching and exit the labor force, they are no longer counted as unemployed, which mechanically lowers the unemployment rate even though no new jobs were created. A simultaneous drop in the participation rate is a warning sign that the lower unemployment rate may reflect people leaving the labor force rather than genuine improvement in employment. The headline rate alone can therefore mislead.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 439, question: "An economy's actual unemployment rate equals its natural rate, and real GDP equals potential GDP. Aggregate demand then increases sharply. In the short run, before expectations adjust, what happens to unemployment and inflation, and which Phillips-curve concept describes this?", options: ["Unemployment rises and inflation falls; a movement down the long-run Phillips curve.","Unemployment falls below the natural rate and inflation rises; a movement up the short-run Phillips curve.","Unemployment and inflation both stay constant; the economy is on the long-run Phillips curve.","Unemployment rises above the natural rate and inflation rises; a rightward shift of the short-run Phillips curve."], correctAnswer: 1, explanation: "A sharp increase in aggregate demand raises the price level (higher inflation) and pushes real GDP above potential, driving unemployment below the natural rate in the short run. This is a movement up and to the left along the existing short-run Phillips curve. It is not a shift of the curve (that requires a supply shock or a change in expectations) and not a long-run outcome, because expectations have not yet adjusted.", difficulty: "hard", topicSlug: "macro-unemployment-inflation" },
  { id: 440, question: "A savings account pays a nominal interest rate of 5% per year. Over the same year, the inflation rate is 2%. Using the approximation that the real interest rate equals the nominal rate minus inflation, what is the real interest rate, and what does it tell the saver?", options: ["7%; the saver's purchasing power grew by 7%.","5%; inflation does not affect real returns on savings.","3%; the saver's purchasing power grew by about 3%.","2%; the saver's purchasing power was unchanged."], correctAnswer: 2, explanation: "The real interest rate is approximately the nominal interest rate minus the inflation rate: 5% - 2% = 3%. This positive real rate means the saver's purchasing power grew by about 3% over the year, since the nominal return outpaced inflation. The 7% answer incorrectly adds the rates, and the 5% answer ignores inflation's erosion of purchasing power.", difficulty: "medium", topicSlug: "macro-unemployment-inflation" },
]

// Lesson-slug → bank-slug alias map. Lesson registry uses granular `macro-*` slugs;
// existing bank uses 4 coarse category slugs.
const topicSlugAliases: Record<string, string[]> = {}

export function getApMacroQuestions(count: number = 10, topicSlug?: string): ApMacroQuestion[] {
  let pool = allQuestions
  if (topicSlug) {
    const targets = topicSlugAliases[topicSlug] ?? [topicSlug]
    const filtered = allQuestions.filter(q => targets.includes(q.topicSlug))
    if (filtered.length > 0) pool = filtered
  }
  const shuffled = [...pool].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, Math.min(count, shuffled.length))
}
